            ],
            'search_text' => 'image class overview introduction to the thunderphp image class, what it does, and when to use it. classes image class  the image class is a gd based utility for working with image files inside thunderphp. it can resize, crop, contain, convert, generate thumbnails, process uploaded images, create files from binary strings, and output images directly to the browser. this class is best used when you need server side image processing for: profile pictures blog thumbnails product images admin previews format conversion such as jpg to webp image upload workflows the class is designed to work primarily with file paths, which makes it easy to integrate with existing upload systems and file storage logic. supported image types the class supports these formats for reading: jpeg png gif webp it can also save to these same formats depending on the destination file extension or chosen output type. main capabilities the class provides methods for: proportional resize exact crop contain fit inside a box saving as another format converting to webp generating one thumbnail generating many thumbnails at once processing uploaded files building image files from raw binary data outputting files directly to the browser basic example use \\core\\image; $image = new image(); $image resize(rootpath . \'public/uploads/photo.jpg\', 1200); when to use resize, crop, or contain use resize() when you want to reduce an image proportionally without forcing exact dimensions. use crop() when you want a fixed box such as 300x300 for avatars or 1200x630 for article cards. use fit contain() when the whole image must remain visible inside a fixed area, such as logos or admin previews.',
            'plain_text' => 'The Image class is a GD based utility for working with image files inside ThunderPHP. It can resize, crop, contain, convert, generate thumbnails, process uploaded images, create files from binary strings, and output images directly to the browser. This class is best used when you need server side image processing for: profile pictures blog thumbnails product images admin previews format conversion such as jpg to webp image upload workflows The class is designed to work primarily with file paths, which makes it easy to integrate with existing upload systems and file storage logic. Supported Image Types The class supports these formats for reading: jpeg png gif webp It can also save to these same formats depending on the destination file extension or chosen output type. Main Capabilities The class provides methods for: proportional resize exact crop contain fit inside a box saving as another format converting to webp generating one thumbnail generating many thumbnails at once processing uploaded files building image files from raw binary data outputting files directly to the browser Basic Example use \\Core\\Image; $image = new Image(); $image resize(ROOTPATH . \'public/uploads/photo.jpg\', 1200); When To Use Resize, Crop, or Contain Use resize() when you want to reduce an image proportionally without forcing exact dimensions. Use crop() when you want a fixed box such as 300x300 for avatars or 1200x630 for article cards. Use fit contain() when the whole image must remain visible inside a fixed area, such as logos or admin previews.',
            'order' => 1,
        ],
