            ],
            'search_text' => 'configuration and defaults learn how to configure quality, compression, thumbnail directories, and file naming behavior. classes image class  before processing images, you can adjust the class configuration to control quality, compression, thumbnail folder behavior, and whether small images should be enlarged. available configuration methods set jpeg quality(int $quality) set png compression(int $compression) set webp quality(int $quality) allow upscale(bool $upscale = true) set thumbnail dir(string $dir) use hashed names(bool $use hashed names = true) jpeg quality jpeg quality is a value from 0 to 100. higher values preserve more detail but create larger files. $image = new \\core\\image(); $image set jpeg quality(85); a practical range for web uploads is often 80 to 88. png compression png compression is a value from 0 to 9. $image = new \\core\\image(); $image set png compression(7); higher values may reduce file size but can cost more cpu time. webp quality webp quality also uses a value from 0 to 100. $image = new \\core\\image(); $image set webp quality(80); a good range for general web thumbnails is often 75 to 85. allow or prevent upscaling if upscaling is disabled, small images will not be enlarged beyond their original size during resize or contain operations. this helps prevent blurry results. $image = new \\core\\image(); $image allow upscale(false); set a separate thumbnail directory you can store thumbnails in a different folder instead of placing them next to the original image. $image = new \\core\\image(); $image set thumbnail dir(rootpath . \'public/uploads/thumbs/\'); readable or hashed thumbnail names by default, thumbnail names are human readable. you can switch to hashed names if you prefer less predictable output names. $image = new \\core\\image(); $image use hashed names(true); recommended defaults a balanced configuration for many web applications looks like this: $image = new \\core\\image(); $image set jpeg quality(85) set png compression(7) set webp quality(80) allow upscale(false);',
            'plain_text' => 'Before processing images, you can adjust the class configuration to control quality, compression, thumbnail folder behavior, and whether small images should be enlarged. Available Configuration Methods set jpeg quality(int $quality) set png compression(int $compression) set webp quality(int $quality) allow upscale(bool $upscale = true) set thumbnail dir(string $dir) use hashed names(bool $use hashed names = true) JPEG Quality JPEG quality is a value from 0 to 100. Higher values preserve more detail but create larger files. $image = new \\Core\\Image(); $image set jpeg quality(85); A practical range for web uploads is often 80 to 88. PNG Compression PNG compression is a value from 0 to 9. $image = new \\Core\\Image(); $image set png compression(7); Higher values may reduce file size but can cost more CPU time. WEBP Quality WEBP quality also uses a value from 0 to 100. $image = new \\Core\\Image(); $image set webp quality(80); A good range for general web thumbnails is often 75 to 85. Allow or Prevent Upscaling If upscaling is disabled, small images will not be enlarged beyond their original size during resize or contain operations. This helps prevent blurry results. $image = new \\Core\\Image(); $image allow upscale(false); Set a Separate Thumbnail Directory You can store thumbnails in a different folder instead of placing them next to the original image. $image = new \\Core\\Image(); $image set thumbnail dir(ROOTPATH . \'public/uploads/thumbs/\'); Readable or Hashed Thumbnail Names By default, thumbnail names are human readable. You can switch to hashed names if you prefer less predictable output names. $image = new \\Core\\Image(); $image use hashed names(true); Recommended Defaults A balanced configuration for many web applications looks like this: $image = new \\Core\\Image(); $image set jpeg quality(85) set png compression(7) set webp quality(80) allow upscale(false);',
            'order' => 2,
        ],
