            ],
            'search_text' => 'resizing images reference for proportional resizing and how destination paths work. classes image class  the resize() method resizes an image proportionally so that its longest side fits within a given maximum size. method signature resize(?string $filename, int $max size = 700, ?string $dest = null): string parameters filename: path to the source image max size: maximum width or height dest: optional destination file path if dest is omitted, the original file is overwritten. basic resize $image = new \\core\\image(); $image resize(rootpath . \'public/uploads/photo.jpg\', 1200); this reduces the image so that its width or height does not exceed 1200. resize to another file $image = new \\core\\image(); $image resize( rootpath . \'public/uploads/photo.jpg\', 1200, rootpath . \'public/uploads/photo resized.jpg\' ); this preserves the original and writes the resized image to a new file. how it works the class keeps the original aspect ratio. it does not stretch the image. if upscaling is disabled, smaller images will not be enlarged past their original size. typical use cases reducing large uploads before storage making medium size display versions preparing files before conversion to another format useful note if you need exact dimensions such as 300x300, use crop() or fit contain() instead of resize().',
            'plain_text' => 'The resize() method resizes an image proportionally so that its longest side fits within a given maximum size. Method Signature resize(?string $filename, int $max size = 700, ?string $dest = null): string Parameters filename: path to the source image max size: maximum width or height dest: optional destination file path If dest is omitted, the original file is overwritten. Basic Resize $image = new \\Core\\Image(); $image resize(ROOTPATH . \'public/uploads/photo.jpg\', 1200); This reduces the image so that its width or height does not exceed 1200. Resize To Another File $image = new \\Core\\Image(); $image resize( ROOTPATH . \'public/uploads/photo.jpg\', 1200, ROOTPATH . \'public/uploads/photo resized.jpg\' ); This preserves the original and writes the resized image to a new file. How It Works The class keeps the original aspect ratio. It does not stretch the image. If upscaling is disabled, smaller images will not be enlarged past their original size. Typical Use Cases reducing large uploads before storage making medium size display versions preparing files before conversion to another format Useful Note If you need exact dimensions such as 300x300, use crop() or fit contain() instead of resize().',
