            'search_text' => 'cropping images reference for exact-dimension cropping, crop positions, and common use cases. classes image class  the crop() method creates an image with exact dimensions by cropping the source image to fit the target ratio. method signature crop(string $filename, int $max width = 700, int $max height = 700, ?string $dest = null, string $position = \'center\'): string parameters filename: source image path max width: final width max height: final height dest: optional destination path position: crop alignment such as center, top, bottom, left, or right basic crop $image = new \\core\\image(); $image crop(rootpath . \'public/uploads/photo.jpg\', 300, 300); this creates a square crop, commonly used for avatars. crop into another file $image = new \\core\\image(); $image crop( rootpath . \'public/uploads/banner.jpg\', 1200, 630, rootpath . \'public/uploads/banner card.jpg\' ); using crop position if a portrait photo has the person near the top, top may be more useful than center. $image = new \\core\\image(); $image crop( rootpath . \'public/uploads/profile.jpg\', 300, 300, rootpath . \'public/uploads/profile crop.jpg\', \'top\' ); typical use cases profile pictures blog cards hero image crops uniform product thumbnails important behavior cropping is best when every output must have identical dimensions. this is usually what you want for grids and cards.',
            'plain_text' => 'The crop() method creates an image with exact dimensions by cropping the source image to fit the target ratio. Method Signature crop(string $filename, int $max width = 700, int $max height = 700, ?string $dest = null, string $position = \'center\'): string Parameters filename: source image path max width: final width max height: final height dest: optional destination path position: crop alignment such as center, top, bottom, left, or right Basic Crop $image = new \\Core\\Image(); $image crop(ROOTPATH . \'public/uploads/photo.jpg\', 300, 300); This creates a square crop, commonly used for avatars. Crop Into Another File $image = new \\Core\\Image(); $image crop( ROOTPATH . \'public/uploads/banner.jpg\', 1200, 630, ROOTPATH . \'public/uploads/banner card.jpg\' ); Using Crop Position If a portrait photo has the person near the top, top may be more useful than center. $image = new \\Core\\Image(); $image crop( ROOTPATH . \'public/uploads/profile.jpg\', 300, 300, ROOTPATH . \'public/uploads/profile crop.jpg\', \'top\' ); Typical Use Cases profile pictures blog cards hero image crops uniform product thumbnails Important Behavior Cropping is best when every output must have identical dimensions. This is usually what you want for grids and cards.',
