            'search_text' => 'contain fit inside a box reference for fitting an image inside a fixed box without cropping. classes image class  the fit contain() method resizes an image so that the whole image fits inside a fixed rectangle without being cropped. any extra space is filled with a background color. method signature fit contain(string $filename, int $max width = 700, int $max height = 700, ?string $dest = null, array $bg color = [255,255,255]): string parameters filename: source image path max width: outer box width max height: outer box height dest: optional destination file bg color: background fill color basic example $image = new \\core\\image(); $image fit contain( rootpath . \'public/uploads/logo.png\', 400, 300, rootpath . \'public/uploads/logo preview.png\' ); custom background color for jpeg output, a white background is common. $image = new \\core\\image(); $image fit contain( rootpath . \'public/uploads/product.png\', 500, 500, rootpath . \'public/uploads/product box.jpg\', [255,255,255] ); for transparent capable output like png or webp, you can provide alpha values when appropriate. $image = new \\core\\image(); $image fit contain( rootpath . \'public/uploads/logo.png\', 400, 300, rootpath . \'public/uploads/logo box.webp\', [0,0,0,127] ); when to use it use fit contain() when cropping would remove important parts of the image. this is especially useful for: logos product images admin previews document style thumbnails',
            'plain_text' => 'The fit contain() method resizes an image so that the whole image fits inside a fixed rectangle without being cropped. Any extra space is filled with a background color. Method Signature fit contain(string $filename, int $max width = 700, int $max height = 700, ?string $dest = null, array $bg color = [255,255,255]): string Parameters filename: source image path max width: outer box width max height: outer box height dest: optional destination file bg color: background fill color Basic Example $image = new \\Core\\Image(); $image fit contain( ROOTPATH . \'public/uploads/logo.png\', 400, 300, ROOTPATH . \'public/uploads/logo preview.png\' ); Custom Background Color For JPEG output, a white background is common. $image = new \\Core\\Image(); $image fit contain( ROOTPATH . \'public/uploads/product.png\', 500, 500, ROOTPATH . \'public/uploads/product box.jpg\', [255,255,255] ); For transparent capable output like png or webp, you can provide alpha values when appropriate. $image = new \\Core\\Image(); $image fit contain( ROOTPATH . \'public/uploads/logo.png\', 400, 300, ROOTPATH . \'public/uploads/logo box.webp\', [0,0,0,127] ); When To Use It Use fit contain() when cropping would remove important parts of the image. This is especially useful for: logos product images admin previews document style thumbnails',
