            'search_text' => 'saving and converting formats reference for save_as and convert_to_webp methods. classes image class  the class can save an image into another file and even another format using the destination file extension. save as() method signature: save as(string $filename, string $dest): string this reads an existing image and writes it to a new destination. the output format is determined by the extension of dest. convert jpg to webp $image = new \\core\\image(); $image save as( rootpath . \'public/uploads/photo.jpg\', rootpath . \'public/uploads/photo.webp\' ); convert png to jpg $image = new \\core\\image(); $image save as( rootpath . \'public/uploads/image.png\', rootpath . \'public/uploads/image.jpg\' ); convert to webp() method signature: convert to webp(string $filename, ?string $dest = null): string this is a convenience method for saving an image as webp. $image = new \\core\\image(); $image convert to webp(rootpath . \'public/uploads/photo.jpg\'); if dest is omitted, the method creates a path with the same filename and a .webp extension. convert to custom webp path $image = new \\core\\image(); $image convert to webp( rootpath . \'public/uploads/photo.jpg\', rootpath . \'public/uploads/converted/photo.webp\' ); why convert to webp webp often provides smaller file sizes than jpeg or png at similar visual quality, especially for frontend thumbnails and card images.',
            'plain_text' => 'The class can save an image into another file and even another format using the destination file extension. save as() Method signature: save as(string $filename, string $dest): string This reads an existing image and writes it to a new destination. The output format is determined by the extension of dest. Convert JPG To WEBP $image = new \\Core\\Image(); $image save as( ROOTPATH . \'public/uploads/photo.jpg\', ROOTPATH . \'public/uploads/photo.webp\' ); Convert PNG To JPG $image = new \\Core\\Image(); $image save as( ROOTPATH . \'public/uploads/image.png\', ROOTPATH . \'public/uploads/image.jpg\' ); convert to webp() Method signature: convert to webp(string $filename, ?string $dest = null): string This is a convenience method for saving an image as webp. $image = new \\Core\\Image(); $image convert to webp(ROOTPATH . \'public/uploads/photo.jpg\'); If dest is omitted, the method creates a path with the same filename and a .webp extension. Convert To Custom WEBP Path $image = new \\Core\\Image(); $image convert to webp( ROOTPATH . \'public/uploads/photo.jpg\', ROOTPATH . \'public/uploads/converted/photo.webp\' ); Why Convert To WEBP WEBP often provides smaller file sizes than JPEG or PNG at similar visual quality, especially for frontend thumbnails and card images.',
