            ],
            'search_text' => 'thumbnail generation reference for get_thumbnail, make_thumbnail, make_thumbnail_as, and thumbnail naming. classes image class  the class provides several helpers for creating thumbnail files. get thumbnail() method signature: get thumbnail(string $filename, int $width = 700, int $height = 700, bool $replace = false, string $mode = \'crop\', array $bg color = [255,255,255], ?string $output ext = null): string this generates a thumbnail using the internal naming rules. if a thumbnail already exists and replace is false, the existing file is returned. basic example $image = new \\core\\image(); $thumb = $image get thumbnail(rootpath . \'public/uploads/photo.jpg\', 300, 300); resize mode thumbnail $image = new \\core\\image(); $thumb = $image get thumbnail(rootpath . \'public/uploads/photo.jpg\', 600, 400, true, \'resize\'); contain mode thumbnail $image = new \\core\\image(); $thumb = $image get thumbnail(rootpath . \'public/uploads/logo.png\', 400, 300, true, \'contain\', [255,255,255]); choose output extension $image = new \\core\\image(); $thumb = $image get thumbnail(rootpath . \'public/uploads/photo.jpg\', 300, 300, true, \'crop\', [255,255,255], \'webp\'); make thumbnail() if you want full control over the destination path, use make thumbnail(). $image = new \\core\\image(); $image make thumbnail( rootpath . \'public/uploads/photo.jpg\', rootpath . \'public/uploads/thumbs/photo small.jpg\', 300, 300, \'crop\' ); make thumbnail as() use make thumbnail as() when the thumbnail should be saved in a different format from the source. $image = new \\core\\image(); $image make thumbnail as( rootpath . \'public/uploads/photo.jpg\', rootpath . \'public/uploads/thumbs/photo small.webp\', 300, 300, \'crop\' ); default thumbnail naming readable names typically look like this: photo crop 300x300.jpg photo resize 800x600.jpg photo contain 400x300.webp if use hashed names(true) is enabled, the class uses hashed filenames instead.',
            'plain_text' => 'The class provides several helpers for creating thumbnail files. get thumbnail() Method signature: get thumbnail(string $filename, int $width = 700, int $height = 700, bool $replace = false, string $mode = \'crop\', array $bg color = [255,255,255], ?string $output ext = null): string This generates a thumbnail using the internal naming rules. If a thumbnail already exists and replace is false, the existing file is returned. Basic Example $image = new \\Core\\Image(); $thumb = $image get thumbnail(ROOTPATH . \'public/uploads/photo.jpg\', 300, 300); Resize Mode Thumbnail $image = new \\Core\\Image(); $thumb = $image get thumbnail(ROOTPATH . \'public/uploads/photo.jpg\', 600, 400, true, \'resize\'); Contain Mode Thumbnail $image = new \\Core\\Image(); $thumb = $image get thumbnail(ROOTPATH . \'public/uploads/logo.png\', 400, 300, true, \'contain\', [255,255,255]); Choose Output Extension $image = new \\Core\\Image(); $thumb = $image get thumbnail(ROOTPATH . \'public/uploads/photo.jpg\', 300, 300, true, \'crop\', [255,255,255], \'webp\'); make thumbnail() If you want full control over the destination path, use make thumbnail(). $image = new \\Core\\Image(); $image make thumbnail( ROOTPATH . \'public/uploads/photo.jpg\', ROOTPATH . \'public/uploads/thumbs/photo small.jpg\', 300, 300, \'crop\' ); make thumbnail as() Use make thumbnail as() when the thumbnail should be saved in a different format from the source. $image = new \\Core\\Image(); $image make thumbnail as( ROOTPATH . \'public/uploads/photo.jpg\', ROOTPATH . \'public/uploads/thumbs/photo small.webp\', 300, 300, \'crop\' ); Default Thumbnail Naming Readable names typically look like this: photo crop 300x300.jpg photo resize 800x600.jpg photo contain 400x300.webp If use hashed names(true) is enabled, the class uses hashed filenames instead.',
            'order' => 7,
