            'search_text' => 'processing multiple thumbnails reference for smart_thumbnail and how to generate many versions in one call. classes image class  the smart thumbnail() method generates many thumbnails in one call and returns structured result information for each generated asset. method signature smart thumbnail(string $filename, array $specs = []): array each spec can define: width height mode ext bg color position replace dest example $image = new \\core\\image(); $image set thumbnail dir(rootpath . \'public/uploads/thumbs/\'); $result = $image smart thumbnail(rootpath . \'public/uploads/photo.jpg\', [ [\'width\' = 100, \'height\' = 100, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 300, \'height\' = 300, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 800, \'height\' = 450, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 1200, \'height\' = 630, \'mode\' = \'contain\', \'ext\' = \'jpg\', \'bg color\' = [255,255,255]], ]); returned structure the method returns an array with: top level success items containing one result array per thumbnail error each item contains: success path mime width height size error when to use it this method is ideal when a single upload must produce multiple frontend versions, such as: avatar thumbnail card image medium preview social share image typical pattern $image = new \\core\\image(); $versions = $image smart thumbnail($original, [ [\'width\' = 150, \'height\' = 150, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 400, \'height\' = 250, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 1200, \'height\' = 630, \'mode\' = \'crop\', \'ext\' = \'webp\'], ]);',
            'plain_text' => 'The smart thumbnail() method generates many thumbnails in one call and returns structured result information for each generated asset. Method Signature smart thumbnail(string $filename, array $specs = []): array Each spec can define: width height mode ext bg color position replace dest Example $image = new \\Core\\Image(); $image set thumbnail dir(ROOTPATH . \'public/uploads/thumbs/\'); $result = $image smart thumbnail(ROOTPATH . \'public/uploads/photo.jpg\', [ [\'width\' = 100, \'height\' = 100, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 300, \'height\' = 300, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 800, \'height\' = 450, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 1200, \'height\' = 630, \'mode\' = \'contain\', \'ext\' = \'jpg\', \'bg color\' = [255,255,255]], ]); Returned Structure The method returns an array with: top level success items containing one result array per thumbnail error Each item contains: success path mime width height size error When To Use It This method is ideal when a single upload must produce multiple frontend versions, such as: avatar thumbnail card image medium preview social share image Typical Pattern $image = new \\Core\\Image(); $versions = $image smart thumbnail($original, [ [\'width\' = 150, \'height\' = 150, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 400, \'height\' = 250, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 1200, \'height\' = 630, \'mode\' = \'crop\', \'ext\' = \'webp\'], ]);',
