            ],
            'search_text' => 'structured results and metadata reference for result arrays, get_size, and how to inspect outputs. classes image class  several methods return structured result arrays to make integration easier. result array structure the internal result() helper returns this general shape: success path mime width height size error example using process() $image = new \\core\\image(); $result = $image process(rootpath . \'public/uploads/photo.jpg\', \'crop\', [ \'width\' = 300, \'height\' = 300, \'dest\' = rootpath . \'public/uploads/photo square.jpg\', ]); if($result[\'success\']) { echo $result[\'path\']; echo $result[\'mime\']; } else { echo $result[\'error\']; } get size() method signature: get size(string $filename): object false this returns an object containing: width height mime example $image = new \\core\\image(); $info = $image get size(rootpath . \'public/uploads/photo.jpg\'); if($info) { echo $info width; echo $info height; echo $info mime; } why structured results matter structured arrays make it easier to: pass results to controllers and views store generated file information in the database detect failures without guessing from paths alone build reusable upload pipelines',
            'plain_text' => 'Several methods return structured result arrays to make integration easier. Result Array Structure The internal result() helper returns this general shape: success path mime width height size error Example Using process() $image = new \\Core\\Image(); $result = $image process(ROOTPATH . \'public/uploads/photo.jpg\', \'crop\', [ \'width\' = 300, \'height\' = 300, \'dest\' = ROOTPATH . \'public/uploads/photo square.jpg\', ]); if($result[\'success\']) { echo $result[\'path\']; echo $result[\'mime\']; } else { echo $result[\'error\']; } get size() Method signature: get size(string $filename): object false This returns an object containing: width height mime Example $image = new \\Core\\Image(); $info = $image get size(ROOTPATH . \'public/uploads/photo.jpg\'); if($info) { echo $info width; echo $info height; echo $info mime; } Why Structured Results Matter Structured arrays make it easier to: pass results to controllers and views store generated file information in the database detect failures without guessing from paths alone build reusable upload pipelines',
