            ],
            'search_text' => 'generic processing and output reference for process and output methods, plus output download behavior. classes image class  the class provides a generic process() method and a direct browser output() method. process() method signature: process(string $filename, string $mode = \'resize\', array $options = []): array supported modes: resize crop contain basic resize through process() $image = new \\core\\image(); $result = $image process(rootpath . \'public/uploads/photo.jpg\', \'resize\', [ \'max size\' = 1200, \'dest\' = rootpath . \'public/uploads/photo large.jpg\', ]); basic crop through process() $image = new \\core\\image(); $result = $image process(rootpath . \'public/uploads/photo.jpg\', \'crop\', [ \'width\' = 300, \'height\' = 300, \'position\' = \'top\', \'dest\' = rootpath . \'public/uploads/photo square.jpg\', ]); contain through process() $image = new \\core\\image(); $result = $image process(rootpath . \'public/uploads/logo.png\', \'contain\', [ \'width\' = 400, \'height\' = 300, \'bg color\' = [255,255,255], \'dest\' = rootpath . \'public/uploads/logo box.png\', ]); output() method signature: output(string $filename, bool $exit after = true, ?string $download name = null): bool this sends the image file directly to the browser with the correct headers. display inline $image = new \\core\\image(); $image output(rootpath . \'public/uploads/thumbs/photo.webp\'); force download $image = new \\core\\image(); $image output(rootpath . \'public/uploads/thumbs/photo.webp\', true, \'downloaded photo.webp\'); important note if headers have already been sent, output() will fail. use it before any html output.',
            'plain_text' => 'The class provides a generic process() method and a direct browser output() method. process() Method signature: process(string $filename, string $mode = \'resize\', array $options = []): array Supported modes: resize crop contain Basic Resize Through process() $image = new \\Core\\Image(); $result = $image process(ROOTPATH . \'public/uploads/photo.jpg\', \'resize\', [ \'max size\' = 1200, \'dest\' = ROOTPATH . \'public/uploads/photo large.jpg\', ]); Basic Crop Through process() $image = new \\Core\\Image(); $result = $image process(ROOTPATH . \'public/uploads/photo.jpg\', \'crop\', [ \'width\' = 300, \'height\' = 300, \'position\' = \'top\', \'dest\' = ROOTPATH . \'public/uploads/photo square.jpg\', ]); Contain Through process() $image = new \\Core\\Image(); $result = $image process(ROOTPATH . \'public/uploads/logo.png\', \'contain\', [ \'width\' = 400, \'height\' = 300, \'bg color\' = [255,255,255], \'dest\' = ROOTPATH . \'public/uploads/logo box.png\', ]); output() Method signature: output(string $filename, bool $exit after = true, ?string $download name = null): bool This sends the image file directly to the browser with the correct headers. Display Inline $image = new \\Core\\Image(); $image output(ROOTPATH . \'public/uploads/thumbs/photo.webp\'); Force Download $image = new \\Core\\Image(); $image output(ROOTPATH . \'public/uploads/thumbs/photo.webp\', true, \'downloaded photo.webp\'); Important Note If headers have already been sent, output() will fail. Use it before any HTML output.',
            'order' => 11,
