            ],
            'search_text' => 'utility methods and file management reference for thumbnail deletion, directories, naming, and behavior notes. classes image class  the class includes helpers for managing thumbnail files and destination directories. delete thumbnails() method signature: delete thumbnails(string $filename): void this removes generated thumbnails that match the internal naming pattern for a given source image. $image = new \\core\\image(); $image delete thumbnails(rootpath . \'public/uploads/photo.jpg\'); this is useful when an original image is replaced and old thumbnails should be removed. directory creation when saving images, the class automatically creates missing destination folders where possible. that means code like this works without manually creating the folder first: $image = new \\core\\image(); $image make thumbnail( rootpath . \'public/uploads/photo.jpg\', rootpath . \'public/uploads/thumbs/cards/photo 300x200.jpg\', 300, 200, \'crop\' ); readable vs hashed names readable names are useful during development and debugging. hashed names are useful when: you do not want predictable generated filenames you want shorter names in a dedicated thumbnails folder you want output naming to be derived consistently from settings error property the class exposes an error property for the last encountered issue. $image = new \\core\\image(); $path = $image convert to webp(rootpath . \'public/uploads/test.xyz\'); if(!is file($path)) { echo $image error; } practical advice use readable names during development. move to hashed names later if you need them for privacy or cleaner storage.',
            'plain_text' => 'The class includes helpers for managing thumbnail files and destination directories. delete thumbnails() Method signature: delete thumbnails(string $filename): void This removes generated thumbnails that match the internal naming pattern for a given source image. $image = new \\Core\\Image(); $image delete thumbnails(ROOTPATH . \'public/uploads/photo.jpg\'); This is useful when an original image is replaced and old thumbnails should be removed. Directory Creation When saving images, the class automatically creates missing destination folders where possible. That means code like this works without manually creating the folder first: $image = new \\Core\\Image(); $image make thumbnail( ROOTPATH . \'public/uploads/photo.jpg\', ROOTPATH . \'public/uploads/thumbs/cards/photo 300x200.jpg\', 300, 200, \'crop\' ); Readable vs Hashed Names Readable names are useful during development and debugging. Hashed names are useful when: you do not want predictable generated filenames you want shorter names in a dedicated thumbnails folder you want output naming to be derived consistently from settings Error Property The class exposes an error property for the last encountered issue. $image = new \\Core\\Image(); $path = $image convert to webp(ROOTPATH . \'public/uploads/test.xyz\'); if(!is file($path)) { echo $image error; } Practical Advice Use readable names during development. Move to hashed names later if you need them for privacy or cleaner storage.',
            'order' => 12,
        ],
