            ],
            'search_text' => 'recipe: store upload and generate multiple webp thumbnails a practical workflow for upload storage and multiple generated sizes. classes image class  this recipe stores an uploaded image, keeps the original, and generates several webp thumbnails for frontend use. use case a blog post cover upload where you need: original file small card image medium card image social share image example use \\core\\image; $image = new image(); $image set thumbnail dir(rootpath . \'public/uploads/posts/thumbs/\') set jpeg quality(85) set webp quality(80) set png compression(7) allow upscale(false); $stored = $image from upload( $ files[\'cover\'], rootpath . \'public/uploads/posts/originals/post 123.jpg\' ); if(!$stored[\'success\']) { die($stored[\'error\']); } $thumbs = $image smart thumbnail($stored[\'path\'], [ [\'width\' = 300, \'height\' = 200, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 600, \'height\' = 400, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 1200, \'height\' = 630, \'mode\' = \'crop\', \'ext\' = \'webp\'], ]); if(!$thumbs[\'success\']) { die($thumbs[\'error\']); } why this works well the original is preserved thumbnails are optimized for the frontend webp helps reduce bandwidth all generated files can be tracked from the returned result arrays',
            'plain_text' => 'This recipe stores an uploaded image, keeps the original, and generates several webp thumbnails for frontend use. Use Case A blog post cover upload where you need: original file small card image medium card image social share image Example use \\Core\\Image; $image = new Image(); $image set thumbnail dir(ROOTPATH . \'public/uploads/posts/thumbs/\') set jpeg quality(85) set webp quality(80) set png compression(7) allow upscale(false); $stored = $image from upload( $ FILES[\'cover\'], ROOTPATH . \'public/uploads/posts/originals/post 123.jpg\' ); if(!$stored[\'success\']) { die($stored[\'error\']); } $thumbs = $image smart thumbnail($stored[\'path\'], [ [\'width\' = 300, \'height\' = 200, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 600, \'height\' = 400, \'mode\' = \'crop\', \'ext\' = \'webp\'], [\'width\' = 1200, \'height\' = 630, \'mode\' = \'crop\', \'ext\' = \'webp\'], ]); if(!$thumbs[\'success\']) { die($thumbs[\'error\']); } Why This Works Well the original is preserved thumbnails are optimized for the frontend webp helps reduce bandwidth all generated files can be tracked from the returned result arrays',
