            'search_text' => 'recipe: user avatar upload a common avatar workflow using square crops and cleanup of previous thumbnails. classes image class  this recipe creates a square avatar thumbnail from a user upload. use case a user profile picture upload where the system stores one original image and one or more square crops. example use \\core\\image; $image = new image(); $image set thumbnail dir(rootpath . \'public/uploads/avatars/thumbs/\') set webp quality(80) allow upscale(false); $stored = $image from upload( $ files[\'avatar\'], rootpath . \'public/uploads/avatars/originals/user 45.jpg\' ); if(!$stored[\'success\']) { die($stored[\'error\']); } $image delete thumbnails($stored[\'path\']); $thumbs = $image smart thumbnail($stored[\'path\'], [ [\'width\' = 80, \'height\' = 80, \'mode\' = \'crop\', \'ext\' = \'webp\', \'position\' = \'top\'], [\'width\' = 200, \'height\' = 200, \'mode\' = \'crop\', \'ext\' = \'webp\', \'position\' = \'top\'], [\'width\' = 400, \'height\' = 400, \'mode\' = \'crop\', \'ext\' = \'webp\', \'position\' = \'top\'], ]); why top can help many profile photos place the person\'s face higher in the image. using top instead of center may give a better crop for avatars.',
            'plain_text' => 'This recipe creates a square avatar thumbnail from a user upload. Use Case A user profile picture upload where the system stores one original image and one or more square crops. Example use \\Core\\Image; $image = new Image(); $image set thumbnail dir(ROOTPATH . \'public/uploads/avatars/thumbs/\') set webp quality(80) allow upscale(false); $stored = $image from upload( $ FILES[\'avatar\'], ROOTPATH . \'public/uploads/avatars/originals/user 45.jpg\' ); if(!$stored[\'success\']) { die($stored[\'error\']); } $image delete thumbnails($stored[\'path\']); $thumbs = $image smart thumbnail($stored[\'path\'], [ [\'width\' = 80, \'height\' = 80, \'mode\' = \'crop\', \'ext\' = \'webp\', \'position\' = \'top\'], [\'width\' = 200, \'height\' = 200, \'mode\' = \'crop\', \'ext\' = \'webp\', \'position\' = \'top\'], [\'width\' = 400, \'height\' = 400, \'mode\' = \'crop\', \'ext\' = \'webp\', \'position\' = \'top\'], ]); Why top Can Help Many profile photos place the person\'s face higher in the image. Using top instead of center may give a better crop for avatars.',
