            ],
            'search_text' => 'recipe: product or logo image with contain mode a common workflow when the whole image must stay visible inside a fixed box. classes image class  this recipe is useful for logos, packaging images, and product images where no part of the source should be cropped. use case you want a 500x500 image box for consistent layout, but each source image has a different shape. example use \\core\\image; $image = new image(); $image set jpeg quality(85) set png compression(7) allow upscale(false); $result = $image process(rootpath . \'public/uploads/logo.png\', \'contain\', [ \'width\' = 500, \'height\' = 500, \'bg color\' = [255,255,255], \'dest\' = rootpath . \'public/uploads/logo box.jpg\', ]); if(!$result[\'success\']) { die($result[\'error\']); } transparent box example use \\core\\image; $image = new image(); $result = $image process(rootpath . \'public/uploads/logo.png\', \'contain\', [ \'width\' = 500, \'height\' = 500, \'bg color\' = [0,0,0,127], \'dest\' = rootpath . \'public/uploads/logo box.webp\', ]); why this is useful contain mode keeps the entire image visible and still gives you consistent outer dimensions for the layout.',
            'plain_text' => 'This recipe is useful for logos, packaging images, and product images where no part of the source should be cropped. Use Case You want a 500x500 image box for consistent layout, but each source image has a different shape. Example use \\Core\\Image; $image = new Image(); $image set jpeg quality(85) set png compression(7) allow upscale(false); $result = $image process(ROOTPATH . \'public/uploads/logo.png\', \'contain\', [ \'width\' = 500, \'height\' = 500, \'bg color\' = [255,255,255], \'dest\' = ROOTPATH . \'public/uploads/logo box.jpg\', ]); if(!$result[\'success\']) { die($result[\'error\']); } Transparent Box Example use \\Core\\Image; $image = new Image(); $result = $image process(ROOTPATH . \'public/uploads/logo.png\', \'contain\', [ \'width\' = 500, \'height\' = 500, \'bg color\' = [0,0,0,127], \'dest\' = ROOTPATH . \'public/uploads/logo box.webp\', ]); Why This Is Useful Contain mode keeps the entire image visible and still gives you consistent outer dimensions for the layout.',
            'order' => 15,
        ],
        [
            'id' => 'classes/image-class/recipe-convert-existing-library-images-to-webp',
            'title' => 'Recipe: Convert Existing Library Images to WEBP',
            'description' => 'A batch-style example for converting existing stored images into webp.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Image Class',
