                'practical',
                'tip',
            ],
            'search_text' => 'recipe: convert existing library images to webp a batch-style example for converting existing stored images into webp. classes image class  this recipe shows how to convert existing image files to webp format. use case you already have a library of jpeg or png images and want webp copies for faster frontend delivery. simple example use \\core\\image; $image = new image(); $image set webp quality(80); $webp = $image convert to webp( rootpath . \'public/uploads/gallery/photo1.jpg\', rootpath . \'public/uploads/gallery webp/photo1.webp\' ); if(!is file($webp)) { echo $image error; } loop through multiple files use \\core\\image; $image = new image(); $image set webp quality(80); $files = [ rootpath . \'public/uploads/gallery/photo1.jpg\', rootpath . \'public/uploads/gallery/photo2.jpg\', rootpath . \'public/uploads/gallery/photo3.png\', ]; foreach($files as $file) { $info = pathinfo($file); $dest = rootpath . \'public/uploads/gallery webp/\' . $info[\'filename\'] . \'.webp\'; $image convert to webp($file, $dest); if(!is file($dest)) { echo $image error; } } practical tip keep the originals. use the webp copies only for display delivery unless you are absolutely sure you no longer need the source format.',
            'plain_text' => 'This recipe shows how to convert existing image files to webp format. Use Case You already have a library of JPEG or PNG images and want webp copies for faster frontend delivery. Simple Example use \\Core\\Image; $image = new Image(); $image set webp quality(80); $webp = $image convert to webp( ROOTPATH . \'public/uploads/gallery/photo1.jpg\', ROOTPATH . \'public/uploads/gallery webp/photo1.webp\' ); if(!is file($webp)) { echo $image error; } Loop Through Multiple Files use \\Core\\Image; $image = new Image(); $image set webp quality(80); $files = [ ROOTPATH . \'public/uploads/gallery/photo1.jpg\', ROOTPATH . \'public/uploads/gallery/photo2.jpg\', ROOTPATH . \'public/uploads/gallery/photo3.png\', ]; foreach($files as $file) { $info = pathinfo($file); $dest = ROOTPATH . \'public/uploads/gallery webp/\' . $info[\'filename\'] . \'.webp\'; $image convert to webp($file, $dest); if(!is file($dest)) { echo $image error; } } Practical Tip Keep the originals. Use the webp copies only for display delivery unless you are absolutely sure you no longer need the source format.',
            'order' => 16,
        ],
        [
            'id' => 'classes/pager-class/pager-class-overview',
            'title' => 'Pager Class Overview',
            'description' => 'Introduction to the Pager class, what it does, and when to use it.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Pager Class',
            'subtopic_slug' => 'pager-class',
            'section_slug' => 'pager-class-overview',
            'url' => 'docs/classes/pager-class/pager-class-overview',
            'path' => 'classes/pager-class/001-pager-class-overview.md',
            'headings' => [
            ],
            'keywords' => [
                'pager',
                'class',
                'overview',
                'introduction',
                'does',
                'classes',
            ],
            'search_text' => 'pager class overview introduction to the pager class, what it does, and when to use it. classes pager class  the pager class is thunderphp\'s general purpose pagination utility. it helps you split large datasets into pages, calculate the correct sql offset, generate page links, and render pagination controls in html. use the pager whenever you are listing records such as blog posts, users, products, comments, logs, media items, or any other dataset that should be displayed in chunks instead of all at once. the class is designed to handle three main jobs: determine the current page calculate pagination boundaries generate pagination links and output in most cases, the flow looks like this: 1. create a pager instance 2. pass the total row count if available 3. use limit() and offset() in your sql query 4. display the pagination controls under the results $total rows = 125; $pager = new \\core\\pager(10, 2, $total rows); $rows = $db query("select from posts limit {$pager limit()} offset {$pager offset()}"); foreach($rows as $row){ echo $row title . ""; } $pager display(); this makes sure the database query and the pager stay in sync.',
            'plain_text' => 'The Pager class is ThunderPHP\'s general purpose pagination utility. It helps you split large datasets into pages, calculate the correct SQL offset, generate page links, and render pagination controls in HTML. Use the pager whenever you are listing records such as blog posts, users, products, comments, logs, media items, or any other dataset that should be displayed in chunks instead of all at once. The class is designed to handle three main jobs: determine the current page calculate pagination boundaries generate pagination links and output In most cases, the flow looks like this: 1. create a pager instance 2. pass the total row count if available 3. use limit() and offset() in your SQL query 4. display the pagination controls under the results $total rows = 125; $pager = new \\Core\\Pager(10, 2, $total rows); $rows = $db query("select from posts limit {$pager limit()} offset {$pager offset()}"); foreach($rows as $row){ echo $row title . ""; } $pager display(); This makes sure the database query and the pager stay in sync.',
            'order' => 1,
        ],
        [
            'id' => 'classes/pager-class/constructor-and-basic-setup',
            'title' => 'Constructor and Basic Setup',
            'description' => 'How to instantiate the pager and what each constructor argument means.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Pager Class',
            'subtopic_slug' => 'pager-class',
            'section_slug' => 'constructor-and-basic-setup',
            'url' => 'docs/classes/pager-class/constructor-and-basic-setup',
            'path' => 'classes/pager-class/002-constructor-and-basic-setup.md',
            'headings' => [
            ],
            'keywords' => [
                'constructor',
                'basic',
                'setup',
                'instantiate',
                'pager',
                'each',
                'argument',
                'means',
                'classes',
                'class',
            ],
            'search_text' => 'constructor and basic setup how to instantiate the pager and what each constructor argument means. classes pager class  the pager constructor accepts three arguments: items per page extra page numbers to show around the current page total number of rows signature: $pager = new \\core\\pager($limit, $extras, $total rows); parameters: limit: how many records should be shown per page extras: how many page numbers should appear on each side of the current page total rows: the total number of matching records in the dataset example: $pager = new \\core\\pager(20, 2, 480); in this example: 20 records are shown per page 2 page numbers are shown before and after the current page the dataset contains 480 rows if the third argument is omitted, the pager can still work, but features such as correctly disabling the final navigation buttons are less precise. in normal usage, it is best to provide the total row count. $pager = new \\core\\pager(10, 1); the pager automatically reads the current page from the query string using the page key by default.',
            'plain_text' => 'The Pager constructor accepts three arguments: items per page extra page numbers to show around the current page total number of rows Signature: $pager = new \\Core\\Pager($limit, $extras, $total rows); Parameters: limit: how many records should be shown per page extras: how many page numbers should appear on each side of the current page total rows: the total number of matching records in the dataset Example: $pager = new \\Core\\Pager(20, 2, 480); In this example: 20 records are shown per page 2 page numbers are shown before and after the current page the dataset contains 480 rows If the third argument is omitted, the pager can still work, but features such as correctly disabling the final navigation buttons are less precise. In normal usage, it is best to provide the total row count. $pager = new \\Core\\Pager(10, 1); The pager automatically reads the current page from the query string using the page key by default.',
            'order' => 2,
        ],
        [
            'id' => 'classes/pager-class/how-page-detection-works',
            'title' => 'How Page Detection Works',
            'description' => 'Explanation of how the current page is detected and sanitized.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Pager Class',
            'subtopic_slug' => 'pager-class',
            'section_slug' => 'how-page-detection-works',
            'url' => 'docs/classes/pager-class/how-page-detection-works',
            'path' => 'classes/pager-class/003-how-page-detection-works.md',
            'headings' => [
            ],
            'keywords' => [
                'page',
                'detection',
                'works',
                'explanation',
                'current',
                'detected',
                'sanitized',
                'classes',
                'pager',
                'class',
            ],
            'search_text' => 'how page detection works explanation of how the current page is detected and sanitized. classes pager class  by default, the pager checks the query string for a parameter called page. example url: https://example.com/posts?page=3 in this case, the pager will treat page 3 as the current page. invalid or missing values are sanitized automatically: empty value becomes page 1 page numbers below 1 become page 1 this means the following urls all safely resolve to page 1: ?page= ?page=0 ?page= 9 example: $pager = new \\core\\pager(15, 2, $total rows); echo $pager current page(); this is useful when you need to show the current page number inside the interface or use it in conditional logic. if you want the pager to use another query string key instead of page, you can change it with set page key(). $pager = new \\core\\pager(15, 2, $total rows); $pager set page key(\'p\'); echo $pager current page();',
            'plain_text' => 'By default, the pager checks the query string for a parameter called page. Example URL: https://example.com/posts?page=3 In this case, the pager will treat page 3 as the current page. Invalid or missing values are sanitized automatically: empty value becomes page 1 page numbers below 1 become page 1 This means the following URLs all safely resolve to page 1: ?page= ?page=0 ?page= 9 Example: $pager = new \\Core\\Pager(15, 2, $total rows); echo $pager current page(); This is useful when you need to show the current page number inside the interface or use it in conditional logic. If you want the pager to use another query string key instead of page, you can change it with set page key(). $pager = new \\Core\\Pager(15, 2, $total rows); $pager set page key(\'p\'); echo $pager current page();',
            'order' => 3,
        ],
        [
            'id' => 'classes/pager-class/limit-offset-and-sql-integration',
            'title' => 'Limit, Offset, and SQL Integration',
            'description' => 'How to use the pager with SQL queries and why limit and offset matter.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Pager Class',
            'subtopic_slug' => 'pager-class',
            'section_slug' => 'limit-offset-and-sql-integration',
            'url' => 'docs/classes/pager-class/limit-offset-and-sql-integration',
            'path' => 'classes/pager-class/004-limit-offset-and-sql-integration.md',
            'headings' => [
            ],
            'keywords' => [
                'limit',
                'offset',
                'sql',
                'integration',
                'pager',
                'queries',
                'why',
                'matter',
                'classes',
                'class',
            ],
            'search_text' => 'limit, offset, and sql integration how to use the pager with sql queries and why limit and offset matter. classes pager class  the most important practical use of the pager is generating the correct sql limit and offset values. limit() returns how many rows to fetch offset() returns how many rows to skip example: $total rows = $db get row("select count(id) as num from posts") num ?? 0; $pager = new \\core\\pager(10, 2, $total rows); $rows = $db query("select from posts order by id desc limit {$pager limit()} offset {$pager offset()}"); if the current page is 1 and the limit is 10: limit() returns 10 offset() returns 0 if the current page is 3 and the limit is still 10: limit() returns 10 offset() returns 20 that is why page 3 starts at row 21 in the overall dataset. there are also getter equivalents: get limit() get offset() example: $pager = new \\core\\pager(25, 1, $total rows); $limit = $pager get limit(); $offset = $pager get offset(); $rows = $db query("select from users limit $limit offset $offset"); use whichever naming style you prefer in your project.',
            'plain_text' => 'The most important practical use of the pager is generating the correct SQL limit and offset values. limit() returns how many rows to fetch offset() returns how many rows to skip Example: $total rows = $db get row("select count(id) as num from posts") num ?? 0; $pager = new \\Core\\Pager(10, 2, $total rows); $rows = $db query("select from posts order by id desc limit {$pager limit()} offset {$pager offset()}"); If the current page is 1 and the limit is 10: limit() returns 10 offset() returns 0 If the current page is 3 and the limit is still 10: limit() returns 10 offset() returns 20 That is why page 3 starts at row 21 in the overall dataset. There are also getter equivalents: get limit() get offset() Example: $pager = new \\Core\\Pager(25, 1, $total rows); $limit = $pager get limit(); $offset = $pager get offset(); $rows = $db query("select from users limit $limit offset $offset"); Use whichever naming style you prefer in your project.',
            'order' => 4,
        ],
        [
            'id' => 'classes/pager-class/total-rows-and-total-pages',
            'title' => 'Total Rows and Total Pages',
            'description' => 'Understanding total row count, total pages, and why these values matter.',
