                'class',
            ],
            'search_text' => 'total rows and total pages understanding total row count, total pages, and why these values matter. classes pager class  pagination works best when the pager knows how many total rows exist in the dataset. the total row count allows the class to calculate: total number of pages whether a previous page exists whether a next page exists the correct last page accurate summary text such as showing 21 30 of 145 example: $total rows = $db get row("select count(id) as num from products where published = 1") num ?? 0; $pager = new \\core\\pager(12, 2, $total rows); echo $pager get total rows(); echo $pager get total pages(); if you already created the pager and later obtained the count, you can set it afterward: $pager = new \\core\\pager(12, 2); $total rows = $db get row("select count(id) as num from products where published = 1") num ?? 0; $pager set total rows((int)$total rows); this is useful if your count query and your pager initialization happen in different parts of the controller logic.',
            'plain_text' => 'Pagination works best when the pager knows how many total rows exist in the dataset. The total row count allows the class to calculate: total number of pages whether a previous page exists whether a next page exists the correct last page accurate summary text such as Showing 21 30 of 145 Example: $total rows = $db get row("select count(id) as num from products where published = 1") num ?? 0; $pager = new \\Core\\Pager(12, 2, $total rows); echo $pager get total rows(); echo $pager get total pages(); If you already created the pager and later obtained the count, you can set it afterward: $pager = new \\Core\\Pager(12, 2); $total rows = $db get row("select count(id) as num from products where published = 1") num ?? 0; $pager set total rows((int)$total rows); This is useful if your count query and your pager initialization happen in different parts of the controller logic.',
            'order' => 5,
        ],
        [
            'id' => 'classes/pager-class/navigation-helpers-and-state-checks',
            'title' => 'Navigation Helpers and State Checks',
