                'methods',
                'classes',
                'pager',
                'class',
            ],
            'search_text' => 'navigation helpers and state checks reference for current page, previous page, next page, and page state methods. classes pager class  the pager includes helper methods that let you inspect pagination state without manually calculating anything. common helpers: current page() prev page() next page() has prev() has next() example: $pager = new \\core\\pager(10, 2, 200); echo $pager current page(); echo $pager prev page(); echo $pager next page(); you can also use state checks to conditionally show custom ui: $pager = new \\core\\pager(10, 2, 200); if($pager has prev()){ echo "there is a previous page"; } if($pager has next()){ echo "there is a next page"; } these methods are especially helpful if you are not using the built in display() method and prefer to build your own layout.',
            'plain_text' => 'The pager includes helper methods that let you inspect pagination state without manually calculating anything. Common helpers: current page() prev page() next page() has prev() has next() Example: $pager = new \\Core\\Pager(10, 2, 200); echo $pager current page(); echo $pager prev page(); echo $pager next page(); You can also use state checks to conditionally show custom UI: $pager = new \\Core\\Pager(10, 2, 200); if($pager has prev()){ echo "There is a previous page"; } if($pager has next()){ echo "There is a next page"; } These methods are especially helpful if you are not using the built in display() method and prefer to build your own layout.',
            'order' => 6,
        ],
        [
            'id' => 'classes/pager-class/rendering-pagination-output',
            'title' => 'Rendering Pagination Output',
            'description' => 'How to output the default HTML pager and when render or display should be used.',
