                'html',
                'pager',
                'render',
                'display',
                'classes',
                'class',
            ],
            'search_text' => 'rendering pagination output how to output the default html pager and when render or display should be used. classes pager class  the pager provides two main output methods: display(): directly echoes the html render(): returns the html as a string standard usage: $pager = new \\core\\pager(10, 2, $total rows); $pager display(); if you want the html first, use render(): $pager = new \\core\\pager(10, 2, $total rows); $html = $pager render(); echo \'\'; echo $html; echo \'\'; the class only renders when there is more than one page, unless you explicitly allow rendering for a single page dataset. you can check this with: if($pager should render()){ $pager display(); } this helps keep the interface clean when a list is too small to need pagination.',
            'plain_text' => 'The pager provides two main output methods: display(): directly echoes the HTML render(): returns the HTML as a string Standard usage: $pager = new \\Core\\Pager(10, 2, $total rows); $pager display(); If you want the HTML first, use render(): $pager = new \\Core\\Pager(10, 2, $total rows); $html = $pager render(); echo \'\'; echo $html; echo \'\'; The class only renders when there is more than one page, unless you explicitly allow rendering for a single page dataset. You can check this with: if($pager should render()){ $pager display(); } This helps keep the interface clean when a list is too small to need pagination.',
            'order' => 7,
        ],
        [
            'id' => 'classes/pager-class/styling-labels-and-presets',
            'title' => 'Styling, Labels, and Presets',
