                'pager',
                'class',
            ],
            'search_text' => 'styling, labels, and presets how to customize classes, text labels, and built-in style presets. classes pager class  the pager lets you customize both css classes and visible button text. to customize class names, use set css(): $pager = new \\core\\pager(10, 2, $total rows); $pager set css([ \'wrapper\' = \'my pager wrap\', \'summary\' = \'my pager summary\', \'ul\' = \'my pager list\', \'li\' = \'my pager item\', \'a\' = \'my pager link\', \'active\' = \'is active\', \'disabled\' = \'is disabled\', ]); to customize labels, use set labels(): $pager = new \\core\\pager(10, 2, $total rows); $pager set labels([ \'first\' = \'\', \'last\' = \' \', \'summary\' = \'page {page} of {pages} · showing {from} {to} of {total}\', ]); the pager also supports built in presets: bootstrap bootstrap5 minimal example: $pager = new \\core\\pager(10, 2, $total rows); $pager preset(\'bootstrap\'); presets are useful when you want a quick styling base without manually defining every css class.',
            'plain_text' => 'The pager lets you customize both CSS classes and visible button text. To customize class names, use set css(): $pager = new \\Core\\Pager(10, 2, $total rows); $pager set css([ \'wrapper\' = \'my pager wrap\', \'summary\' = \'my pager summary\', \'ul\' = \'my pager list\', \'li\' = \'my pager item\', \'a\' = \'my pager link\', \'active\' = \'is active\', \'disabled\' = \'is disabled\', ]); To customize labels, use set labels(): $pager = new \\Core\\Pager(10, 2, $total rows); $pager set labels([ \'first\' = \'\', \'last\' = \' \', \'summary\' = \'Page {page} of {pages} · Showing {from} {to} of {total}\', ]); The pager also supports built in presets: bootstrap bootstrap5 minimal Example: $pager = new \\Core\\Pager(10, 2, $total rows); $pager preset(\'bootstrap\'); Presets are useful when you want a quick styling base without manually defining every CSS class.',
