            'search_text' => 'summary text and display options how to show record ranges, control summary output, and handle single-page datasets. classes pager class  the pager can show a summary line describing the visible range of records. example output: showing 21 30 of 145 to get the summary text directly: $pager = new \\core\\pager(10, 2, 145); echo $pager summary text(); related methods include: showing from() showing to() summary text() show summary() is summary enabled() example: $pager = new \\core\\pager(10, 2, 145); echo $pager showing from(); echo $pager showing to(); echo $pager summary text(); to hide the summary: $pager = new \\core\\pager(10, 2, 145); $pager show summary(false); to force the pager to render even when there is only one page: $pager = new \\core\\pager(10, 2, 8); $pager render if single page(true); this is useful if you want a consistent footer layout even for small datasets.',
            'plain_text' => 'The pager can show a summary line describing the visible range of records. Example output: Showing 21 30 of 145 To get the summary text directly: $pager = new \\Core\\Pager(10, 2, 145); echo $pager summary text(); Related methods include: showing from() showing to() summary text() show summary() is summary enabled() Example: $pager = new \\Core\\Pager(10, 2, 145); echo $pager showing from(); echo $pager showing to(); echo $pager summary text(); To hide the summary: $pager = new \\Core\\Pager(10, 2, 145); $pager show summary(false); To force the pager to render even when there is only one page: $pager = new \\Core\\Pager(10, 2, 8); $pager render if single page(true); This is useful if you want a consistent footer layout even for small datasets.',
            'order' => 9,
        ],
