            ],
            'search_text' => 'ellipsis, button visibility, and link structure how the pager controls first, last, previous, next, and ellipsis behavior. classes pager class  the pager can shorten long page lists with ellipsis. example: first previous 1 ... 8 9 10 ... 40 next last this helps keep the ui compact when there are many pages. you can control that behavior with: use ellipsis() show first last() show prev next() example: $pager = new \\core\\pager(10, 2, 900); $pager use ellipsis(true) show first last(true) show prev next(true); to disable ellipsis and only show the calculated numeric window: $pager = new \\core\\pager(10, 2, 900); $pager use ellipsis(false); to hide the first and last buttons: $pager = new \\core\\pager(10, 2, 900); $pager show first last(false); to hide previous and next: $pager = new \\core\\pager(10, 2, 900); $pager show prev next(false); these switches make it easier to fit the pager into different ui styles without rewriting the class.',
            'plain_text' => 'The pager can shorten long page lists with ellipsis. Example: First Previous 1 ... 8 9 10 ... 40 Next Last This helps keep the UI compact when there are many pages. You can control that behavior with: use ellipsis() show first last() show prev next() Example: $pager = new \\Core\\Pager(10, 2, 900); $pager use ellipsis(true) show first last(true) show prev next(true); To disable ellipsis and only show the calculated numeric window: $pager = new \\Core\\Pager(10, 2, 900); $pager use ellipsis(false); To hide the first and last buttons: $pager = new \\Core\\Pager(10, 2, 900); $pager show first last(false); To hide previous and next: $pager = new \\Core\\Pager(10, 2, 900); $pager show prev next(false); These switches make it easier to fit the pager into different UI styles without rewriting the class.',
            'order' => 10,
