                'parameter',
                'force',
                'pager',
                'generate',
                'links',
                'url',
                'classes',
                'class',
            ],
            'search_text' => 'custom query keys and base urls how to use a different page parameter or force the pager to generate links from a custom base url. classes pager class  by default, the pager reads and writes the page number using the page query key. if your route or frontend expects another key, use set page key(): $pager = new \\core\\pager(10, 2, $total rows); $pager set page key(\'p\'); this will make the pager read urls like: ?p=3 if you want to force pagination links to use a specific base url, use set base url(). example: $pager = new \\core\\pager(10, 2, $total rows); $pager set base url(root . \'/admin/users?role=editor&status=active\'); this is useful when: your current route is not based on $ get[\'url\'] you want pagination inside a custom admin panel you want to preserve extra filters in the query string full url example: $pager = new \\core\\pager(10, 2, $total rows); $pager set base url(\'https://example.com/reports/sales?year=2026&region=north\'); the pager will append or update the page value correctly.',
            'plain_text' => 'By default, the pager reads and writes the page number using the page query key. If your route or frontend expects another key, use set page key(): $pager = new \\Core\\Pager(10, 2, $total rows); $pager set page key(\'p\'); This will make the pager read URLs like: ?p=3 If you want to force pagination links to use a specific base URL, use set base url(). Example: $pager = new \\Core\\Pager(10, 2, $total rows); $pager set base url(ROOT . \'/admin/users?role=editor&status=active\'); This is useful when: your current route is not based on $ GET[\'url\'] you want pagination inside a custom admin panel you want to preserve extra filters in the query string Full URL example: $pager = new \\Core\\Pager(10, 2, $total rows); $pager set base url(\'https://example.com/reports/sales?year=2026&region=north\'); The pager will append or update the page value correctly.',
            'order' => 11,
        ],
        [
            'id' => 'classes/pager-class/custom-rendering-with-set-renderer',
            'title' => 'Custom Rendering with set_renderer',
            'description' => 'How to replace the built-in HTML with completely custom markup.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Pager Class',
            'subtopic_slug' => 'pager-class',
