                'replace',
                'built-in',
                'html',
                'completely',
                'markup',
                'classes',
                'pager',
                'class',
            ],
            'search_text' => 'custom rendering with set_renderer how to replace the built-in html with completely custom markup. classes pager class  one of the most useful features of the pager is the ability to replace the default html output with your own markup. use set renderer() to provide a callback. the callback receives: the pagination items array the pager instance example: $pager = new \\core\\pager(10, 2, $total rows); $pager set renderer(function(array $items, \\core\\pager $pager){ $html = \'\'; if($pager is summary enabled()){ $html .= \'\' . $pager summary text() . \'\'; } $html .= \'\'; foreach($items as $item){ if($item[\'type\'] === \'ellipsis\'){ $html .= \'\' . $item[\'label\'] . \'\'; continue; } $active = $item[\'active\'] ? \' is active\' : \'\'; $disabled = $item[\'disabled\'] ? \' is disabled\' : \'\'; if($item[\'disabled\']){ $html .= \'\' . $item[\'label\'] . \'\'; }else{ $html .= \'\' . $item[\'label\'] . \'\'; } } $html .= \'\'; $html .= \'\'; return $html; }); $pager display(); this is the best option when changing button html structure is more important than simply changing css class names.',
            'plain_text' => 'One of the most useful features of the pager is the ability to replace the default HTML output with your own markup. Use set renderer() to provide a callback. The callback receives: the pagination items array the pager instance Example: $pager = new \\Core\\Pager(10, 2, $total rows); $pager set renderer(function(array $items, \\Core\\Pager $pager){ $html = \'\'; if($pager is summary enabled()){ $html .= \'\' . $pager summary text() . \'\'; } $html .= \'\'; foreach($items as $item){ if($item[\'type\'] === \'ellipsis\'){ $html .= \'\' . $item[\'label\'] . \'\'; continue; } $active = $item[\'active\'] ? \' is active\' : \'\'; $disabled = $item[\'disabled\'] ? \' is disabled\' : \'\'; if($item[\'disabled\']){ $html .= \'\' . $item[\'label\'] . \'\'; }else{ $html .= \'\' . $item[\'label\'] . \'\'; } } $html .= \'\'; $html .= \'\'; return $html; }); $pager display(); This is the best option when changing button HTML structure is more important than simply changing CSS class names.',
            'order' => 12,
        ],
        [
            'id' => 'classes/pager-class/practical-recipe-paginating-a-blog-post-list',
            'title' => 'Practical Recipe: Paginating a Blog Post List',
            'description' => 'Recipe for counting posts, querying a single page of results, and showing the pager.',
            'topic' => 'Classes',
