            ],
            'search_text' => 'practical recipe: paginating a blog post list recipe for counting posts, querying a single page of results, and showing the pager. classes pager class  this recipe shows a standard blog listing page. step 1: get the total count. step 2: create the pager. step 3: use limit() and offset() in the query. step 4: display the links. $count row = $db get row("select count(id) as num from posts where published = 1"); $total rows = $count row num ?? 0; $pager = new \\core\\pager(10, 2, (int)$total rows); $rows = $db query(" select from posts where published = 1 order by id desc limit {$pager limit()} offset {$pager offset()} "); if(!empty($rows)){ foreach($rows as $row){ echo \'\' . esc($row title) . \'\'; echo \'\' . esc($row excerpt) . \'\'; } } $pager display(); this is one of the most common real world uses of the class.',
            'plain_text' => 'This recipe shows a standard blog listing page. Step 1: get the total count. Step 2: create the pager. Step 3: use limit() and offset() in the query. Step 4: display the links. $count row = $db get row("select count(id) as num from posts where published = 1"); $total rows = $count row num ?? 0; $pager = new \\Core\\Pager(10, 2, (int)$total rows); $rows = $db query(" select from posts where published = 1 order by id desc limit {$pager limit()} offset {$pager offset()} "); if(!empty($rows)){ foreach($rows as $row){ echo \'\' . esc($row title) . \'\'; echo \'\' . esc($row excerpt) . \'\'; } } $pager display(); This is one of the most common real world uses of the class.',
            'order' => 13,
