            ],
            'search_text' => 'practical recipe: admin table with filters recipe for preserving filters and paginating an admin table using a custom base url. classes pager class  in an admin page, you often want pagination links to preserve filters such as role, status, search, or date range. this is a good case for set base url(). $role = $ get[\'role\'] ?? \'editor\'; $status = $ get[\'status\'] ?? \'active\'; $count row = $db get row(" select count(id) as num from users where role = :role and status = :status ",[ \'role\' = $role, \'status\' = $status, ]); $total rows = $count row num ?? 0; $pager = new \\core\\pager(20, 2, (int)$total rows); $pager set base url(root . \'/admin/users?role=\' . urlencode($role) . \'&status=\' . urlencode($status)); $rows = $db query(" select from users where role = :role and status = :status order by id desc limit {$pager limit()} offset {$pager offset()} ",[ \'role\' = $role, \'status\' = $status, ]); if(!empty($rows)){ foreach($rows as $row){ echo \'\' . esc($row email) . \'\'; } } $pager display(); this keeps the selected filter values in all pagination links.',
            'plain_text' => 'In an admin page, you often want pagination links to preserve filters such as role, status, search, or date range. This is a good case for set base url(). $role = $ GET[\'role\'] ?? \'editor\'; $status = $ GET[\'status\'] ?? \'active\'; $count row = $db get row(" select count(id) as num from users where role = :role and status = :status ",[ \'role\' = $role, \'status\' = $status, ]); $total rows = $count row num ?? 0; $pager = new \\Core\\Pager(20, 2, (int)$total rows); $pager set base url(ROOT . \'/admin/users?role=\' . urlencode($role) . \'&status=\' . urlencode($status)); $rows = $db query(" select from users where role = :role and status = :status order by id desc limit {$pager limit()} offset {$pager offset()} ",[ \'role\' = $role, \'status\' = $status, ]); if(!empty($rows)){ foreach($rows as $row){ echo \'\' . esc($row email) . \'\'; } } $pager display(); This keeps the selected filter values in all pagination links.',
