            ],
            'search_text' => 'practical recipe: minimal pager for custom frontends recipe for using custom labels, summary text, and a simplified style preset. classes pager class  if you want a lighter looking interface, combine a preset with custom labels. $pager = new \\core\\pager(12, 1, 145); $pager preset(\'minimal\') set labels([ \'first\' = \'\', \'last\' = \' \', \'summary\' = \'showing {from} {to} / {total}\', ]); $pager display(); this works well for dashboards, compact cards, media listings, and frontend widgets where full bootstrap markup is not desired. you can go further and hide some controls: $pager = new \\core\\pager(12, 1, 145); $pager preset(\'minimal\') show first last(false) show prev next(true) use ellipsis(true); $pager display(); this gives you a much smaller pager while still keeping navigation clear.',
            'plain_text' => 'If you want a lighter looking interface, combine a preset with custom labels. $pager = new \\Core\\Pager(12, 1, 145); $pager preset(\'minimal\') set labels([ \'first\' = \'\', \'last\' = \' \', \'summary\' = \'Showing {from} {to} / {total}\', ]); $pager display(); This works well for dashboards, compact cards, media listings, and frontend widgets where full Bootstrap markup is not desired. You can go further and hide some controls: $pager = new \\Core\\Pager(12, 1, 145); $pager preset(\'minimal\') show first last(false) show prev next(true) use ellipsis(true); $pager display(); This gives you a much smaller pager while still keeping navigation clear.',
