            'search_text' => 'practical recipe: fully custom button html recipe for replacing the default pagination markup with your own html structure. classes pager class  this recipe is useful when your design system does not use the default ul li a structure. $pager = new \\core\\pager(15, 2, 320); $pager set renderer(function(array $items, \\core\\pager $pager){ $html = \'\'; if($pager is summary enabled()){ $html .= \'\' . $pager summary text() . \'\'; } $html .= \'\'; foreach($items as $item){ if($item[\'type\'] === \'ellipsis\'){ $html .= \'\' . $item[\'label\'] . \'\'; continue; } $class = \'tp pagination btn\'; if($item[\'active\']){ $class .= \' is active\'; } if($item[\'disabled\']){ $class .= \' is disabled\'; $html .= \'\' . $item[\'label\'] . \'\'; }else{ $html .= \'\' . $item[\'label\'] . \'\'; } } $html .= \'\'; $html .= \'\'; return $html; }); $pager display(); this approach gives you full control over the markup while keeping all pagination logic inside the pager class.',
            'plain_text' => 'This recipe is useful when your design system does not use the default ul li a structure. $pager = new \\Core\\Pager(15, 2, 320); $pager set renderer(function(array $items, \\Core\\Pager $pager){ $html = \'\'; if($pager is summary enabled()){ $html .= \'\' . $pager summary text() . \'\'; } $html .= \'\'; foreach($items as $item){ if($item[\'type\'] === \'ellipsis\'){ $html .= \'\' . $item[\'label\'] . \'\'; continue; } $class = \'tp pagination btn\'; if($item[\'active\']){ $class .= \' is active\'; } if($item[\'disabled\']){ $class .= \' is disabled\'; $html .= \'\' . $item[\'label\'] . \'\'; }else{ $html .= \'\' . $item[\'label\'] . \'\'; } } $html .= \'\'; $html .= \'\'; return $html; }); $pager display(); This approach gives you full control over the markup while keeping all pagination logic inside the pager class.',
