        [
            'id' => 'classes/request-class/request-class-overview',
            'title' => 'Request Class Overview',
            'description' => 'Introduction to the Request class, what it does, and the main areas it covers.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'request-class-overview',
            'url' => 'docs/classes/request-class/request-class-overview',
            'path' => 'classes/request-class/001-request-class-overview.md',
            'headings' => [
            ],
            'keywords' => [
                'request',
                'class',
                'overview',
                'introduction',
                'does',
                'main',
                'areas',
                'covers',
                'classes',
            ],
            'search_text' => 'request class overview introduction to the request class, what it does, and the main areas it covers. classes request class  the request class is the central helper for reading incoming http request data and handling uploaded files in one place. it is designed to give you a clean way to work with: request methods such as get and post form input from $ post query string values from $ get uploaded files from $ files request metadata from $ server safe and configurable file uploads this class is especially useful because it keeps your controllers and plugin files cleaner. instead of reading directly from php superglobals everywhere, you can create one request instance and access everything from there. a typical usage example looks like this: $req = new \\\\core\\request(); if($req posted()) { $name = $req post(\'name\'); $email = $req post(\'email\'); } the upload system also supports: single file uploads multiple file uploads using one input like photos[] per field upload rules mime type validation file extension validation optional image verification optional image dimension limits grouped upload results in most cases, the request class should be created inside a controller or plugin controller and then used as needed throughout the request lifecycle.',
            'plain_text' => 'The Request class is the central helper for reading incoming HTTP request data and handling uploaded files in one place. It is designed to give you a clean way to work with: request methods such as GET and POST form input from $ POST query string values from $ GET uploaded files from $ FILES request metadata from $ SERVER safe and configurable file uploads This class is especially useful because it keeps your controllers and plugin files cleaner. Instead of reading directly from PHP superglobals everywhere, you can create one Request instance and access everything from there. A typical usage example looks like this: $req = new \\\\Core\\Request(); if($req posted()) { $name = $req post(\'name\'); $email = $req post(\'email\'); } The upload system also supports: single file uploads multiple file uploads using one input like photos[] per field upload rules MIME type validation file extension validation optional image verification optional image dimension limits grouped upload results In most cases, the Request class should be created inside a controller or plugin controller and then used as needed throughout the request lifecycle.',
            'order' => 1,
        ],
        [
            'id' => 'classes/request-class/getting-the-request-method',
            'title' => 'Getting the Request Method',
            'description' => 'Methods for checking the current HTTP method and common request state helpers.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'getting-the-request-method',
            'url' => 'docs/classes/request-class/getting-the-request-method',
            'path' => 'classes/request-class/002-getting-the-request-method.md',
            'headings' => [
            ],
            'keywords' => [
                'getting',
                'request',
                'method',
                'methods',
                'checking',
                'current',
                'http',
                'common',
                'state',
                'helpers',
                'classes',
                'class',
            ],
            'search_text' => 'getting the request method methods for checking the current http method and common request state helpers. classes request class  use the request method helpers when you want to know how the current page was accessed. the main method is method(), which returns the current request method as an uppercase string. $req = new \\\\core\\request(); echo $req method(); // get, post, put, delete etc the posted() method is a convenience helper that returns true only when the request method is post. $req = new \\\\core\\request(); if($req posted()) { echo "form submitted"; } the is get() method returns true when the current request is a get request. $req = new \\\\core\\request(); if($req is get()) { echo "page loaded normally"; } the is ajax() method checks whether the request was made through ajax by inspecting the http x requested with header. $req = new \\\\core\\request(); if($req is ajax()) { echo "ajax request detected"; } these helpers are useful for separating normal page views from submitted forms or asynchronous requests.',
            'plain_text' => 'Use the request method helpers when you want to know how the current page was accessed. The main method is method(), which returns the current request method as an uppercase string. $req = new \\\\Core\\Request(); echo $req method(); // GET, POST, PUT, DELETE etc The posted() method is a convenience helper that returns true only when the request method is POST. $req = new \\\\Core\\Request(); if($req posted()) { echo "Form submitted"; } The is get() method returns true when the current request is a GET request. $req = new \\\\Core\\Request(); if($req is get()) { echo "Page loaded normally"; } The is ajax() method checks whether the request was made through AJAX by inspecting the HTTP X REQUESTED WITH header. $req = new \\\\Core\\Request(); if($req is ajax()) { echo "AJAX request detected"; } These helpers are useful for separating normal page views from submitted forms or asynchronous requests.',
            'order' => 2,
        ],
        [
            'id' => 'classes/request-class/reading-post-data',
            'title' => 'Reading POST Data',
            'description' => 'How to retrieve posted form values using `post()` and `input()`.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'reading-post-data',
            'url' => 'docs/classes/request-class/reading-post-data',
            'path' => 'classes/request-class/003-reading-post-data.md',
            'headings' => [
