            'keywords' => [
                'reading',
                'post',
                'data',
                'retrieve',
                'posted',
                'form',
                'values',
                'input',
                'classes',
                'request',
                'class',
            ],
            'search_text' => 'reading post data how to retrieve posted form values using `post()` and `input()`. classes request class  use post() when you want to read submitted form values from $ post. if you call it with no key, it returns the whole $ post array. $req = new \\\\core\\request(); $data = $req post(); print r($data); if you pass a key, it returns that value if it exists. $req = new \\\\core\\request(); $username = $req post(\'username\'); you can also pass a default value: $req = new \\\\core\\request(); $country = $req post(\'country\', \'zambia\'); the input() method is simply a convenient alias for reading posted values with a default fallback. $req = new \\\\core\\request(); $email = $req input(\'email\'); $role = $req input(\'role\', \'user\'); one important improvement in this class is that it uses key existence checks instead of empty(). that means values like 0 and \'0\' are not incorrectly treated as missing. example: $req = new \\\\core\\request(); $status = $req post(\'status\', 1); // if the submitted value was \'0\', you still get \'0\' var dump($status); this makes the class much safer for forms where zero is a valid value.',
            'plain_text' => 'Use post() when you want to read submitted form values from $ POST. If you call it with no key, it returns the whole $ POST array. $req = new \\\\Core\\Request(); $data = $req post(); print r($data); If you pass a key, it returns that value if it exists. $req = new \\\\Core\\Request(); $username = $req post(\'username\'); You can also pass a default value: $req = new \\\\Core\\Request(); $country = $req post(\'country\', \'Zambia\'); The input() method is simply a convenient alias for reading posted values with a default fallback. $req = new \\\\Core\\Request(); $email = $req input(\'email\'); $role = $req input(\'role\', \'user\'); One important improvement in this class is that it uses key existence checks instead of empty(). That means values like 0 and \'0\' are not incorrectly treated as missing. Example: $req = new \\\\Core\\Request(); $status = $req post(\'status\', 1); // if the submitted value was \'0\', you still get \'0\' var dump($status); This makes the class much safer for forms where zero is a valid value.',
            'order' => 3,
        ],
        [
            'id' => 'classes/request-class/reading-get-data',
            'title' => 'Reading GET Data',
            'description' => 'How to read query string values using `get()` and work with defaults.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'reading-get-data',
            'url' => 'docs/classes/request-class/reading-get-data',
            'path' => 'classes/request-class/004-reading-get-data.md',
            'headings' => [
            ],
            'keywords' => [
                'reading',
                'get',
                'data',
                'read',
                'query',
                'string',
                'values',
                'work',
                'defaults',
                'classes',
                'request',
                'class',
            ],
            'search_text' => 'reading get data how to read query string values using `get()` and work with defaults. classes request class  use get() when you want to read values from the url query string. with no key, it returns the full $ get array. $req = new \\\\core\\request(); $params = $req get(); print r($params); with a key, it returns one value. $req = new \\\\core\\request(); $page = $req get(\'page\', 1); $search = $req get(\'search\', \'\'); this is useful for: pagination filters search terms sort order category selection example: $req = new \\\\core\\request(); $page = (int)$req get(\'page\', 1); $sort = $req get(\'sort\', \'latest\'); $keyword = trim($req get(\'q\', \'\')); echo $page; echo $sort; echo $keyword; just like post(), this method preserves valid values such as 0 because it checks whether the key exists rather than treating empty values as missing.',
            'plain_text' => 'Use get() when you want to read values from the URL query string. With no key, it returns the full $ GET array. $req = new \\\\Core\\Request(); $params = $req get(); print r($params); With a key, it returns one value. $req = new \\\\Core\\Request(); $page = $req get(\'page\', 1); $search = $req get(\'search\', \'\'); This is useful for: pagination filters search terms sort order category selection Example: $req = new \\\\Core\\Request(); $page = (int)$req get(\'page\', 1); $sort = $req get(\'sort\', \'latest\'); $keyword = trim($req get(\'q\', \'\')); echo $page; echo $sort; echo $keyword; Just like post(), this method preserves valid values such as 0 because it checks whether the key exists rather than treating empty values as missing.',
            'order' => 4,
        ],
        [
            'id' => 'classes/request-class/reading-all-request-data',
            'title' => 'Reading All Request Data',
            'description' => 'How to use `all()` and when to prefer `post()` or `get()` instead.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'reading-all-request-data',
            'url' => 'docs/classes/request-class/reading-all-request-data',
            'path' => 'classes/request-class/005-reading-all-request-data.md',
            'headings' => [
            ],
            'keywords' => [
                'reading',
                'all',
                'request',
                'data',
                'prefer',
                'post',
                'get',
                'instead',
                'classes',
                'class',
            ],
            'search_text' => 'reading all request data how to use `all()` and when to prefer `post()` or `get()` instead. classes request class  the all() method reads from $ request, which usually combines $ get, $ post, and in some environments cookies as well. with no key, it returns the full request data. $req = new \\\\core\\request(); $data = $req all(); print r($data); with a key, it returns one request value: $req = new \\\\core\\request(); $id = $req all(\'id\'); you can also provide a default: $req = new \\\\core\\request(); $tab = $req all(\'tab\', \'general\'); even though all() is available, it is usually better to prefer post() and get() when you know exactly where the value should come from. that keeps your code more explicit and easier to debug. recommended: $req = new \\\\core\\request(); $name = $req post(\'name\'); $page = $req get(\'page\', 1); less explicit: $req = new \\\\core\\request(); $name = $req all(\'name\'); $page = $req all(\'page\', 1); use all() only when you intentionally want to accept the value from either source.',
            'plain_text' => 'The all() method reads from $ REQUEST, which usually combines $ GET, $ POST, and in some environments cookies as well. With no key, it returns the full request data. $req = new \\\\Core\\Request(); $data = $req all(); print r($data); With a key, it returns one request value: $req = new \\\\Core\\Request(); $id = $req all(\'id\'); You can also provide a default: $req = new \\\\Core\\Request(); $tab = $req all(\'tab\', \'general\'); Even though all() is available, it is usually better to prefer post() and get() when you know exactly where the value should come from. That keeps your code more explicit and easier to debug. Recommended: $req = new \\\\Core\\Request(); $name = $req post(\'name\'); $page = $req get(\'page\', 1); Less explicit: $req = new \\\\Core\\Request(); $name = $req all(\'name\'); $page = $req all(\'page\', 1); Use all() only when you intentionally want to accept the value from either source.',
            'order' => 5,
        ],
        [
            'id' => 'classes/request-class/checking-whether-keys-exist',
            'title' => 'Checking Whether Keys Exist',
            'description' => 'Using `has_post()`, `has_get()`, and `has_file()` to check for request input safely.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'checking-whether-keys-exist',
            'url' => 'docs/classes/request-class/checking-whether-keys-exist',
            'path' => 'classes/request-class/006-checking-whether-keys-exist.md',
            'headings' => [
            ],
            'keywords' => [
                'checking',
                'whether',
                'keys',
                'exist',
                'has_post',
                'has_get',
                'has_file',
                'check',
                'request',
                'input',
                'safely',
                'classes',
                'class',
            ],
            'search_text' => 'checking whether keys exist using `has_post()`, `has_get()`, and `has_file()` to check for request input safely. classes request class  sometimes you do not want the actual value yet. you only want to know whether a key exists. the request class provides helper methods for that. use has post() to check whether a post key exists. $req = new \\\\core\\request(); if($req has post(\'email\')) { echo "email field was submitted"; } use has get() to check whether a get key exists. $req = new \\\\core\\request(); if($req has get(\'page\')) { echo "page parameter exists"; } use has file() to check whether a file input contains an uploaded file. $req = new \\\\core\\request(); if($req has file(\'avatar\')) { echo "avatar file was selected"; } this is especially useful for file inputs because not every request containing $ files[\'avatar\'] means that a file was actually chosen. it also works for array style file inputs such as photos[]. $req = new \\\\core\\request(); if($req has file(\'photos\')) { echo "at least one photo exists"; } these helpers make conditions cleaner and reduce low level checks against php superglobals.',
            'plain_text' => 'Sometimes you do not want the actual value yet. You only want to know whether a key exists. The Request class provides helper methods for that. Use has post() to check whether a POST key exists. $req = new \\\\Core\\Request(); if($req has post(\'email\')) { echo "Email field was submitted"; } Use has get() to check whether a GET key exists. $req = new \\\\Core\\Request(); if($req has get(\'page\')) { echo "Page parameter exists"; } Use has file() to check whether a file input contains an uploaded file. $req = new \\\\Core\\Request(); if($req has file(\'avatar\')) { echo "Avatar file was selected"; } This is especially useful for file inputs because not every request containing $ FILES[\'avatar\'] means that a file was actually chosen. It also works for array style file inputs such as photos[]. $req = new \\\\Core\\Request(); if($req has file(\'photos\')) { echo "At least one photo exists"; } These helpers make conditions cleaner and reduce low level checks against PHP superglobals.',
            'order' => 6,
        ],
        [
            'id' => 'classes/request-class/accessing-uploaded-file-data',
            'title' => 'Accessing Uploaded File Data',
            'description' => 'How `files()` works before upload processing and what PHP file arrays look like.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'accessing-uploaded-file-data',
            'url' => 'docs/classes/request-class/accessing-uploaded-file-data',
            'path' => 'classes/request-class/007-accessing-uploaded-file-data.md',
            'headings' => [
            ],
            'keywords' => [
                'accessing',
                'uploaded',
                'file',
                'data',
                'files',
                'works',
                'before',
                'upload',
                'processing',
                'php',
                'arrays',
                'look',
                'like',
                'classes',
                'request',
                'class',
            ],
            'search_text' => 'accessing uploaded file data how `files()` works before upload processing and what php file arrays look like. classes request class  use files() when you want raw access to uploaded file data from $ files. with no key, it returns the entire $ files array. $req = new \\\\core\\request(); print r($req files()); with a key, it returns the raw file entry for that field. $req = new \\\\core\\request(); $avatar = $req files(\'avatar\'); print r($avatar); a normal single upload usually looks like this: array ( [name] = photo.jpg [type] = image/jpeg [tmp name] = /tmp/php12345 [error] = 0 [size] = 245120 ) a multiple upload field like photos[] usually looks like this: array ( [name] = array ( [0] = image1.jpg [1] = image2.jpg ) [type] = array ( [0] = image/jpeg [1] = image/jpeg ) [tmp name] = array ( [0] = /tmp/phpaaa [1] = /tmp/phpbbb ) [error] = array ( [0] = 0 [1] = 0 ) [size] = array ( [0] = 123456 [1] = 654321 ) ) the upload system automatically normalizes both shapes into a single internal structure, so you usually do not need to deal with raw file array complexity yourself unless you specifically want to inspect the original file data.',
            'plain_text' => 'Use files() when you want raw access to uploaded file data from $ FILES. With no key, it returns the entire $ FILES array. $req = new \\\\Core\\Request(); print r($req files()); With a key, it returns the raw file entry for that field. $req = new \\\\Core\\Request(); $avatar = $req files(\'avatar\'); print r($avatar); A normal single upload usually looks like this: Array ( [name] = photo.jpg [type] = image/jpeg [tmp name] = /tmp/php12345 [error] = 0 [size] = 245120 ) A multiple upload field like photos[] usually looks like this: Array ( [name] = Array ( [0] = image1.jpg [1] = image2.jpg ) [type] = Array ( [0] = image/jpeg [1] = image/jpeg ) [tmp name] = Array ( [0] = /tmp/phpAAA [1] = /tmp/phpBBB ) [error] = Array ( [0] = 0 [1] = 0 ) [size] = Array ( [0] = 123456 [1] = 654321 ) ) The upload system automatically normalizes both shapes into a single internal structure, so you usually do not need to deal with raw file array complexity yourself unless you specifically want to inspect the original file data.',
            'order' => 7,
        ],
        [
            'id' => 'classes/request-class/basic-file-uploads',
            'title' => 'Basic File Uploads',
            'description' => 'How to upload single files and multiple files using `upload_files()`.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'basic-file-uploads',
            'url' => 'docs/classes/request-class/basic-file-uploads',
            'path' => 'classes/request-class/008-basic-file-uploads.md',
            'headings' => [
            ],
            'keywords' => [
                'basic',
                'file',
                'uploads',
                'upload',
                'single',
                'files',
                'multiple',
                'upload_files',
                'classes',
                'request',
                'class',
                'one',
                'input',
                'uploading',
                'all',
                'fields',
            ],
            'search_text' => 'basic file uploads how to upload single files and multiple files using `upload_files()`. classes request class  the upload files() method is the main method used to process uploaded files. it supports: a single file input such as avatar multiple files using one field such as photos[] processing all uploaded fields at once single file upload $req = new \\\\core\\request(); $req set upload folder(\'uploads/avatars\') set upload max size(5) set upload file types([\'image/jpeg\', \'image/png\']) set upload extensions([\'jpg\', \'jpeg\', \'png\']); $avatar = $req upload files(\'avatar\'); if($req has upload errors()) { print r($req get upload errors()); } else { echo $avatar; } if one specific field is uploaded and it contains one file, upload files(\'avatar\') returns a string path. multiple files from one input html: php: $req = new \\\\core\\request(); $req set upload folder(\'uploads/gallery\') set upload max size(8) set upload file types([\'image/jpeg\', \'image/png\', \'image/webp\']) set upload extensions([\'jpg\', \'jpeg\', \'png\', \'webp\']); $photos = $req upload files(\'photos\'); if($req has upload errors()) { print r($req get upload errors()); } else { print r($photos); } if the field contains multiple files, the method returns an array of saved paths. uploading all fields $req = new \\\\core\\request(); $result = $req upload files(); print r($result); when no key is passed, the result is grouped by field name. this makes it easier to handle forms that contain several upload fields at once.',
            'plain_text' => 'The upload files() method is the main method used to process uploaded files. It supports: a single file input such as avatar multiple files using one field such as photos[] processing all uploaded fields at once Single file upload $req = new \\\\Core\\Request(); $req set upload folder(\'uploads/avatars\') set upload max size(5) set upload file types([\'image/jpeg\', \'image/png\']) set upload extensions([\'jpg\', \'jpeg\', \'png\']); $avatar = $req upload files(\'avatar\'); if($req has upload errors()) { print r($req get upload errors()); } else { echo $avatar; } If one specific field is uploaded and it contains one file, upload files(\'avatar\') returns a string path. Multiple files from one input HTML: PHP: $req = new \\\\Core\\Request(); $req set upload folder(\'uploads/gallery\') set upload max size(8) set upload file types([\'image/jpeg\', \'image/png\', \'image/webp\']) set upload extensions([\'jpg\', \'jpeg\', \'png\', \'webp\']); $photos = $req upload files(\'photos\'); if($req has upload errors()) { print r($req get upload errors()); } else { print r($photos); } If the field contains multiple files, the method returns an array of saved paths. Uploading all fields $req = new \\\\Core\\Request(); $result = $req upload files(); print r($result); When no key is passed, the result is grouped by field name. This makes it easier to handle forms that contain several upload fields at once.',
            'order' => 8,
        ],
        [
            'id' => 'classes/request-class/using-setter-methods',
            'title' => 'Using Setter Methods',
            'description' => 'Configuring uploads with setter methods.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'using-setter-methods',
            'url' => 'docs/classes/request-class/using-setter-methods',
            'path' => 'classes/request-class/009-using-setter-methods.md',
            'headings' => [
            ],
            'keywords' => [
                'setter',
                'methods',
                'configuring',
                'uploads',
                'classes',
                'request',
                'class',
            ],
            'search_text' => 'using setter methods configuring uploads with setter methods. classes request class  the class includes setter methods so you do not have to mutate upload related properties directly. you can do this: $req = new \\\\core\\request(); $req set upload folder(\'uploads/users\') set upload max size(5) set upload file types([\'image/jpeg\', \'image/png\']) set upload extensions([\'jpg\', \'jpeg\', \'png\']) set file prefix(\'user \') set verify images(true) set image dimensions(150, 150, 3000, 3000); available setter methods include: set upload folder() set upload max size() set upload file types() set upload extensions() set file prefix() set verify images() set image dimensions() set filename callback() set upload rule() these methods return the current object, so they can be chained. this leads to: cleaner calling code less accidental misconfiguration easier to validate values later easier to extend without breaking existing code keeps intent obvious in controllers and plugins this style is especially useful in larger plugins where each upload field may need its own configuration.',
            'plain_text' => 'The class includes setter methods so you do not have to mutate upload related properties directly. You can do this: $req = new \\\\Core\\Request(); $req set upload folder(\'uploads/users\') set upload max size(5) set upload file types([\'image/jpeg\', \'image/png\']) set upload extensions([\'jpg\', \'jpeg\', \'png\']) set file prefix(\'user \') set verify images(true) set image dimensions(150, 150, 3000, 3000); Available setter methods include: set upload folder() set upload max size() set upload file types() set upload extensions() set file prefix() set verify images() set image dimensions() set filename callback() set upload rule() These methods return the current object, so they can be chained. This leads to: cleaner calling code less accidental misconfiguration easier to validate values later easier to extend without breaking existing code keeps intent obvious in controllers and plugins This style is especially useful in larger plugins where each upload field may need its own configuration.',
            'order' => 9,
        ],
        [
            'id' => 'classes/request-class/per-field-upload-rules',
            'title' => 'Per-Field Upload Rules',
            'description' => 'How to define different upload rules for different file inputs.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'per-field-upload-rules',
            'url' => 'docs/classes/request-class/per-field-upload-rules',
            'path' => 'classes/request-class/010-per-field-upload-rules.md',
            'headings' => [
            ],
            'keywords' => [
                'per-field',
                'upload',
                'rules',
                'define',
                'different',
                'file',
                'inputs',
                'classes',
                'request',
                'class',
            ],
            'search_text' => 'per-field upload rules how to define different upload rules for different file inputs. classes request class  real world forms often contain different upload fields with different requirements. for example: avatar should accept only images resume should accept only pdfs gallery should accept multiple images logo should be limited to a specific dimension the set upload rule() method lets you define rules per field. example: $req = new \\\\core\\request(); $req set upload rule(\'avatar\', [ \'folder\' = \'uploads/avatars\', \'max size\' = 5, \'mime types\' = [\'image/jpeg\', \'image/png\', \'image/webp\'], \'extensions\' = [\'jpg\', \'jpeg\', \'png\', \'webp\'], \'verify image\' = true, \'min width\' = 150, \'min height\' = 150, \'max width\' = 3000, \'max height\' = 3000, \'prefix\' = \'avatar \', ]); $req set upload rule(\'resume\', [ \'folder\' = \'uploads/resumes\', \'max size\' = 10, \'mime types\' = [\'application/pdf\'], \'extensions\' = [\'pdf\'], \'prefix\' = \'resume \', ]); supported rule keys are: folder max size mime types extensions verify image min width min height max width max height prefix you can retrieve the rule later using get upload rule(). $rule = $req get upload rule(\'avatar\'); print r($rule); per field rules override the global upload settings for that field. this gives you precise control over each upload input without needing multiple request classes.',
            'plain_text' => 'Real world forms often contain different upload fields with different requirements. For example: avatar should accept only images resume should accept only PDFs gallery should accept multiple images logo should be limited to a specific dimension The set upload rule() method lets you define rules per field. Example: $req = new \\\\Core\\Request(); $req set upload rule(\'avatar\', [ \'folder\' = \'uploads/avatars\', \'max size\' = 5, \'mime types\' = [\'image/jpeg\', \'image/png\', \'image/webp\'], \'extensions\' = [\'jpg\', \'jpeg\', \'png\', \'webp\'], \'verify image\' = true, \'min width\' = 150, \'min height\' = 150, \'max width\' = 3000, \'max height\' = 3000, \'prefix\' = \'avatar \', ]); $req set upload rule(\'resume\', [ \'folder\' = \'uploads/resumes\', \'max size\' = 10, \'mime types\' = [\'application/pdf\'], \'extensions\' = [\'pdf\'], \'prefix\' = \'resume \', ]); Supported rule keys are: folder max size mime types extensions verify image min width min height max width max height prefix You can retrieve the rule later using get upload rule(). $rule = $req get upload rule(\'avatar\'); print r($rule); Per field rules override the global upload settings for that field. This gives you precise control over each upload input without needing multiple request classes.',
            'order' => 10,
        ],
        [
            'id' => 'classes/request-class/validating-file-types-and-extensions',
            'title' => 'Validating File Types and Extensions',
            'description' => 'Why both MIME types and file extensions are checked and how to configure them.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'validating-file-types-and-extensions',
            'url' => 'docs/classes/request-class/validating-file-types-and-extensions',
            'path' => 'classes/request-class/011-validating-file-types-and-extensions.md',
            'headings' => [
            ],
            'keywords' => [
                'validating',
                'file',
                'types',
                'extensions',
                'why',
                'both',
                'mime',
                'checked',
                'configure',
                'them',
                'classes',
                'request',
                'class',
                'type',
                'validation',
                'extension',
            ],
            'search_text' => 'validating file types and extensions why both mime types and file extensions are checked and how to configure them. classes request class  the upload system validates both mime types and file extensions. this matters because file validation should not rely only on one layer. mime type validation the class detects the real mime type from the uploaded temporary file using finfo file() or mime content type(). example global configuration: $req = new \\\\core\\request(); $req set upload file types([ \'image/jpeg\', \'image/png\', \'image/webp\', ]); example per field configuration: $req set upload rule(\'document\', [ \'mime types\' = [\'application/pdf\'], ]); extension validation the class also checks the file extension from the original filename. $req = new \\\\core\\request(); $req set upload extensions([\'jpg\', \'jpeg\', \'png\', \'webp\']); per field: $req set upload rule(\'document\', [ \'extensions\' = [\'pdf\'], ]); why both checks are useful: mime type helps confirm the file content extension helps keep naming and downstream usage consistent checking both makes it harder for a renamed file to bypass validation it reduces surprises when plugins expect certain file types later if you really want to allow everything, you can use any: $req set upload file types([\'any\']); $req set upload extensions([\'any\']); that should be used very carefully, especially for public uploads.',
            'plain_text' => 'The upload system validates both MIME types and file extensions. This matters because file validation should not rely only on one layer. MIME type validation The class detects the real MIME type from the uploaded temporary file using finfo file() or mime content type(). Example global configuration: $req = new \\\\Core\\Request(); $req set upload file types([ \'image/jpeg\', \'image/png\', \'image/webp\', ]); Example per field configuration: $req set upload rule(\'document\', [ \'mime types\' = [\'application/pdf\'], ]); Extension validation The class also checks the file extension from the original filename. $req = new \\\\Core\\Request(); $req set upload extensions([\'jpg\', \'jpeg\', \'png\', \'webp\']); Per field: $req set upload rule(\'document\', [ \'extensions\' = [\'pdf\'], ]); Why both checks are useful: MIME type helps confirm the file content extension helps keep naming and downstream usage consistent checking both makes it harder for a renamed file to bypass validation it reduces surprises when plugins expect certain file types later If you really want to allow everything, you can use any: $req set upload file types([\'any\']); $req set upload extensions([\'any\']); That should be used very carefully, especially for public uploads.',
            'order' => 11,
        ],
        [
            'id' => 'classes/request-class/image-verification-and-dimension-rules',
            'title' => 'Image Verification and Dimension Rules',
            'description' => 'How to verify real images and enforce minimum or maximum dimensions.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
