            'url' => 'docs/classes/request-class/image-verification-and-dimension-rules',
            'path' => 'classes/request-class/012-image-verification-and-dimension-rules.md',
            'headings' => [
            ],
            'keywords' => [
                'image',
                'verification',
                'dimension',
                'rules',
                'verify',
                'real',
                'images',
                'enforce',
                'minimum',
                'maximum',
                'dimensions',
                'classes',
                'request',
                'class',
            ],
            'search_text' => 'image verification and dimension rules how to verify real images and enforce minimum or maximum dimensions. classes request class  when a field is meant to receive an image, it is often useful to verify that the uploaded file is a real image and optionally enforce dimension limits. enable image verification globally: $req = new \\\\core\\request(); $req set verify images(true); set global image dimensions: $req set image dimensions(200, 200, 3000, 3000); that means: minimum width: 200 minimum height: 200 maximum width: 3000 maximum height: 3000 you can also configure image rules per field: $req set upload rule(\'logo\', [ \'folder\' = \'uploads/logos\', \'mime types\' = [\'image/png\', \'image/jpeg\', \'image/webp\'], \'extensions\' = [\'png\', \'jpg\', \'jpeg\', \'webp\'], \'verify image\' = true, \'max width\' = 512, \'max height\' = 512, ]); this is useful for: logos avatars thumbnails gallery images cover art internally, the class uses getimagesize() to confirm the file behaves like a real image. this helps catch cases where a file may have an allowed extension but is not actually a valid image. if a file fails dimension rules, it will not be moved and the error will be available through get upload errors().',
            'plain_text' => 'When a field is meant to receive an image, it is often useful to verify that the uploaded file is a real image and optionally enforce dimension limits. Enable image verification globally: $req = new \\\\Core\\Request(); $req set verify images(true); Set global image dimensions: $req set image dimensions(200, 200, 3000, 3000); That means: minimum width: 200 minimum height: 200 maximum width: 3000 maximum height: 3000 You can also configure image rules per field: $req set upload rule(\'logo\', [ \'folder\' = \'uploads/logos\', \'mime types\' = [\'image/png\', \'image/jpeg\', \'image/webp\'], \'extensions\' = [\'png\', \'jpg\', \'jpeg\', \'webp\'], \'verify image\' = true, \'max width\' = 512, \'max height\' = 512, ]); This is useful for: logos avatars thumbnails gallery images cover art Internally, the class uses getimagesize() to confirm the file behaves like a real image. This helps catch cases where a file may have an allowed extension but is not actually a valid image. If a file fails dimension rules, it will not be moved and the error will be available through get upload errors().',
            'order' => 12,
        ],
        [
            'id' => 'classes/request-class/detailed-upload-results',
            'title' => 'Detailed Upload Results',
            'description' => 'Using `upload_files_detailed()` to get metadata such as MIME type, extension, size, width, and height.',
            'topic' => 'Classes',
