                'class',
            ],
            'search_text' => 'detailed upload results using `upload_files_detailed()` to get metadata such as mime type, extension, size, width, and height. classes request class  sometimes you need more than just the saved file path. you may also want to know: original file name saved path mime type extension file size readable file size text image width and height that is what upload files detailed() is for. example: $req = new \\\\core\\request(); $req set upload rule(\'document\', [ \'folder\' = \'uploads/documents\', \'max size\' = 10, \'mime types\' = [\'application/pdf\'], \'extensions\' = [\'pdf\'], ]); $result = $req upload files detailed(\'document\'); print r($result); a successful detailed result may look like this: array ( [0] = array ( [success] = 1 [field name] = document [original name] = report.pdf [path] = uploads/documents/report a1b2c3d4.pdf [mime type] = application/pdf [extension] = pdf [size] = 245120 [size text] = 239.38 kb ) ) for an image field, width and height may also be included: array ( [0] = array ( [success] = 1 [field name] = avatar [original name] = me.jpg [path] = uploads/avatars/me fedcba12.jpg [mime type] = image/jpeg [extension] = jpg [size] = 105000 [size text] = 102.54 kb [width] = 800 [height] = 800 ) ) this method is ideal when you want to save upload metadata into the database after the file is processed.',
            'plain_text' => 'Sometimes you need more than just the saved file path. You may also want to know: original file name saved path MIME type extension file size readable file size text image width and height That is what upload files detailed() is for. Example: $req = new \\\\Core\\Request(); $req set upload rule(\'document\', [ \'folder\' = \'uploads/documents\', \'max size\' = 10, \'mime types\' = [\'application/pdf\'], \'extensions\' = [\'pdf\'], ]); $result = $req upload files detailed(\'document\'); print r($result); A successful detailed result may look like this: Array ( [0] = Array ( [success] = 1 [field name] = document [original name] = report.pdf [path] = uploads/documents/report a1b2c3d4.pdf [mime type] = application/pdf [extension] = pdf [size] = 245120 [size text] = 239.38 KB ) ) For an image field, width and height may also be included: Array ( [0] = Array ( [success] = 1 [field name] = avatar [original name] = me.jpg [path] = uploads/avatars/me fedcba12.jpg [mime type] = image/jpeg [extension] = jpg [size] = 105000 [size text] = 102.54 KB [width] = 800 [height] = 800 ) ) This method is ideal when you want to save upload metadata into the database after the file is processed.',
            'order' => 13,
        ],
        [
            'id' => 'classes/request-class/upload-errors',
            'title' => 'Upload Errors',
            'description' => 'How upload errors are collected, read, and cleared.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'upload-errors',
            'url' => 'docs/classes/request-class/upload-errors',
            'path' => 'classes/request-class/014-upload-errors.md',
            'headings' => [
            ],
            'keywords' => [
                'upload',
                'errors',
                'collected',
                'read',
                'cleared',
                'classes',
                'request',
                'class',
            ],
            'search_text' => 'upload errors how upload errors are collected, read, and cleared. classes request class  the upload system collects validation and move errors instead of failing silently. use has upload errors() to check whether any errors occurred. $req = new \\\\core\\request(); $req upload files(\'avatar\'); if($req has upload errors()) { print r($req get upload errors()); } use get upload errors() to retrieve all error messages. $errors = $req get upload errors(); print r($errors); use get upload error code() to read the latest upload error code. $code = $req get upload error code(); echo $code; use clear upload errors() when you want to reset the upload state manually. $req clear upload errors(); errors are grouped by field name. example: array ( [avatar] = array ( [0] = invalid file type: image.bmp ) [photos] = array ( [0] = file too large: holiday.jpg [1] = invalid file extension: notes.txt ) ) system level folder problems may be stored under system. array ( [ system] = array ( [0] = upload folder is not writable: uploads/gallery/ ) ) this structure makes it easier to show upload feedback in forms or admin pages.',
            'plain_text' => 'The upload system collects validation and move errors instead of failing silently. Use has upload errors() to check whether any errors occurred. $req = new \\\\Core\\Request(); $req upload files(\'avatar\'); if($req has upload errors()) { print r($req get upload errors()); } Use get upload errors() to retrieve all error messages. $errors = $req get upload errors(); print r($errors); Use get upload error code() to read the latest upload error code. $code = $req get upload error code(); echo $code; Use clear upload errors() when you want to reset the upload state manually. $req clear upload errors(); Errors are grouped by field name. Example: Array ( [avatar] = Array ( [0] = Invalid file type: image.bmp ) [photos] = Array ( [0] = File too large: holiday.jpg [1] = Invalid file extension: notes.txt ) ) System level folder problems may be stored under system. Array ( [ system] = Array ( [0] = Upload folder is not writable: uploads/gallery/ ) ) This structure makes it easier to show upload feedback in forms or admin pages.',
            'order' => 14,
        ],
        [
            'id' => 'classes/request-class/filename-generation-and-security',
            'title' => 'Filename Generation and Security',
            'description' => 'How filenames are sanitized, randomized, and optionally customized with callbacks.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'filename-generation-and-security',
            'url' => 'docs/classes/request-class/filename-generation-and-security',
            'path' => 'classes/request-class/015-filename-generation-and-security.md',
            'headings' => [
            ],
            'keywords' => [
                'filename',
                'generation',
                'security',
                'filenames',
                'sanitized',
                'randomized',
                'optionally',
                'customized',
                'callbacks',
                'classes',
                'request',
                'class',
                'custom',
                'callback',
            ],
            'search_text' => 'filename generation and security how filenames are sanitized, randomized, and optionally customized with callbacks. classes request class  the upload system does not store files under their original names directly. instead, it: sanitizes the base filename preserves the extension adds a random value to reduce collisions and guessing optionally applies a custom prefix optionally allows custom filename generation through a callback example using a prefix: $req = new \\\\core\\request(); $req set file prefix(\'user \'); a file such as my photo.jpg may become something like: uploads/avatars/user my photo a1b2c3d4e5f6g7h8.jpg this is safer than predictable names because it reduces: accidental overwriting easy url guessing information leakage through filenames predictable file enumeration custom filename callback if you need full control, use set filename callback(). $req set filename callback(function($original name, $safe name, $extension, $field name, $file info){ $id = rand(1000,9999); return $field name . \' \' . $id . \'.\' . $extension; }); the callback receives: original name safe base name extension field name file information array use this carefully. a custom callback should still generate safe and unique file names. in most cases, the built in randomized naming is the safest default.',
            'plain_text' => 'The upload system does not store files under their original names directly. Instead, it: sanitizes the base filename preserves the extension adds a random value to reduce collisions and guessing optionally applies a custom prefix optionally allows custom filename generation through a callback Example using a prefix: $req = new \\\\Core\\Request(); $req set file prefix(\'user \'); A file such as My Photo.jpg may become something like: uploads/avatars/user my photo a1b2c3d4e5f6g7h8.jpg This is safer than predictable names because it reduces: accidental overwriting easy URL guessing information leakage through filenames predictable file enumeration Custom filename callback If you need full control, use set filename callback(). $req set filename callback(function($original name, $safe name, $extension, $field name, $file info){ $id = rand(1000,9999); return $field name . \' \' . $id . \'.\' . $extension; }); The callback receives: original name safe base name extension field name file information array Use this carefully. A custom callback should still generate safe and unique file names. In most cases, the built in randomized naming is the safest default.',
            'order' => 15,
        ],
        [
            'id' => 'classes/request-class/reading-server-data-and-headers',
            'title' => 'Reading Server Data and Headers',
            'description' => 'Using `server()`, `header()`, `ip()`, and `uri()` for request metadata.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
