            'url' => 'docs/classes/request-class/reading-server-data-and-headers',
            'path' => 'classes/request-class/016-reading-server-data-and-headers.md',
            'headings' => [
            ],
            'keywords' => [
                'reading',
                'server',
                'data',
                'headers',
                'header',
                'ip',
