                'current',
                'read',
                'one',
                'value',
                'all',
            ],
            'search_text' => 'reading server data and headers using `server()`, `header()`, `ip()`, and `uri()` for request metadata. classes request class  the request class also provides a few helpers for request metadata. get the client ip $req = new \\\\core\\request(); echo $req ip(); get the current request uri $req = new \\\\core\\request(); echo $req uri(); read one server value $req = new \\\\core\\request(); $agent = $req server(\'http user agent\'); echo $agent; read all server data $req = new \\\\core\\request(); print r($req server()); read a request header $req = new \\\\core\\request(); $token = $req header(\'authorization\'); echo $token; this header method converts names like authorization into the corresponding $ server style key internally. these helpers are useful for: logging debugging middleware style checks ajax detection api token handling route diagnostics they help keep your controller code cleaner and reduce direct access to $ server.',
            'plain_text' => 'The Request class also provides a few helpers for request metadata. Get the client IP $req = new \\\\Core\\Request(); echo $req ip(); Get the current request URI $req = new \\\\Core\\Request(); echo $req uri(); Read one server value $req = new \\\\Core\\Request(); $agent = $req server(\'HTTP USER AGENT\'); echo $agent; Read all server data $req = new \\\\Core\\Request(); print r($req server()); Read a request header $req = new \\\\Core\\Request(); $token = $req header(\'Authorization\'); echo $token; This header method converts names like Authorization into the corresponding $ SERVER style key internally. These helpers are useful for: logging debugging middleware style checks AJAX detection API token handling route diagnostics They help keep your controller code cleaner and reduce direct access to $ SERVER.',
            'order' => 16,
        ],
        [
            'id' => 'classes/request-class/practical-recipes',
            'title' => 'Practical Recipes',
            'description' => 'Real-world examples showing how to use the Request class in common plugin scenarios.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'practical-recipes',
            'url' => 'docs/classes/request-class/practical-recipes',
            'path' => 'classes/request-class/017-practical-recipes.md',
            'headings' => [
            ],
            'keywords' => [
                'practical',
                'recipes',
                'real-world',
                'examples',
                'showing',
                'request',
                'class',
                'common',
                'plugin',
                'scenarios',
                'classes',
                'recipe',
                'normal',
                'form',
                'submission',
                'avatar',
                'upload',
                'pdf',
                'document',
                'gallery',
                'save',
                'detailed',
                'metadata',
                'database',
            ],
            'search_text' => 'practical recipes real-world examples showing how to use the request class in common plugin scenarios. classes request class  this section shows common real world usage patterns. recipe 1: normal form submission $req = new \\\\core\\request(); if($req posted()) { $data = [ \'name\' = trim($req post(\'name\')), \'email\' = trim($req post(\'email\')), \'status\' = (int)$req post(\'status\', 1), ]; print r($data); } recipe 2: avatar upload $req = new \\\\core\\request(); $req set upload rule(\'avatar\', [ \'folder\' = \'uploads/avatars\', \'max size\' = 5, \'mime types\' = [\'image/jpeg\', \'image/png\', \'image/webp\'], \'extensions\' = [\'jpg\', \'jpeg\', \'png\', \'webp\'], \'verify image\' = true, \'min width\' = 150, \'min height\' = 150, \'prefix\' = \'avatar \', ]); $avatar = $req upload files(\'avatar\'); if($req has upload errors()) { print r($req get upload errors()); } else { echo $avatar; } recipe 3: pdf document upload $req = new \\\\core\\request(); $req set upload rule(\'manual\', [ \'folder\' = \'uploads/manuals\', \'max size\' = 20, \'mime types\' = [\'application/pdf\'], \'extensions\' = [\'pdf\'], \'prefix\' = \'manual \', ]); $file = $req upload files(\'manual\'); recipe 4: gallery upload $req = new \\\\core\\request(); $req set upload rule(\'photos\', [ \'folder\' = \'uploads/gallery\', \'max size\' = 8, \'mime types\' = [\'image/jpeg\', \'image/png\', \'image/webp\'], \'extensions\' = [\'jpg\', \'jpeg\', \'png\', \'webp\'], \'verify image\' = true, \'prefix\' = \'gallery \', ]); $photos = $req upload files(\'photos\'); print r($photos); recipe 5: save detailed upload metadata to database $req = new \\\\core\\request(); $req set upload rule(\'document\', [ \'folder\' = \'uploads/documents\', \'max size\' = 10, \'mime types\' = [\'application/pdf\'], \'extensions\' = [\'pdf\'], ]); $result = $req upload files detailed(\'document\'); if(!$req has upload errors() && !empty($result[0][\'success\'])) { $file = $result[0]; $data = [ \'original name\' = $file[\'original name\'], \'file path\' = $file[\'path\'], \'mime type\' = $file[\'mime type\'], \'extension\' = $file[\'extension\'], \'file size\' = $file[\'size\'], ]; } these recipes cover the most common use cases you are likely to encounter in thunderphp plugins.',
            'plain_text' => 'This section shows common real world usage patterns. Recipe 1: Normal form submission $req = new \\\\Core\\Request(); if($req posted()) { $data = [ \'name\' = trim($req post(\'name\')), \'email\' = trim($req post(\'email\')), \'status\' = (int)$req post(\'status\', 1), ]; print r($data); } Recipe 2: Avatar upload $req = new \\\\Core\\Request(); $req set upload rule(\'avatar\', [ \'folder\' = \'uploads/avatars\', \'max size\' = 5, \'mime types\' = [\'image/jpeg\', \'image/png\', \'image/webp\'], \'extensions\' = [\'jpg\', \'jpeg\', \'png\', \'webp\'], \'verify image\' = true, \'min width\' = 150, \'min height\' = 150, \'prefix\' = \'avatar \', ]); $avatar = $req upload files(\'avatar\'); if($req has upload errors()) { print r($req get upload errors()); } else { echo $avatar; } Recipe 3: PDF document upload $req = new \\\\Core\\Request(); $req set upload rule(\'manual\', [ \'folder\' = \'uploads/manuals\', \'max size\' = 20, \'mime types\' = [\'application/pdf\'], \'extensions\' = [\'pdf\'], \'prefix\' = \'manual \', ]); $file = $req upload files(\'manual\'); Recipe 4: Gallery upload $req = new \\\\Core\\Request(); $req set upload rule(\'photos\', [ \'folder\' = \'uploads/gallery\', \'max size\' = 8, \'mime types\' = [\'image/jpeg\', \'image/png\', \'image/webp\'], \'extensions\' = [\'jpg\', \'jpeg\', \'png\', \'webp\'], \'verify image\' = true, \'prefix\' = \'gallery \', ]); $photos = $req upload files(\'photos\'); print r($photos); Recipe 5: Save detailed upload metadata to database $req = new \\\\Core\\Request(); $req set upload rule(\'document\', [ \'folder\' = \'uploads/documents\', \'max size\' = 10, \'mime types\' = [\'application/pdf\'], \'extensions\' = [\'pdf\'], ]); $result = $req upload files detailed(\'document\'); if(!$req has upload errors() && !empty($result[0][\'success\'])) { $file = $result[0]; $data = [ \'original name\' = $file[\'original name\'], \'file path\' = $file[\'path\'], \'mime type\' = $file[\'mime type\'], \'extension\' = $file[\'extension\'], \'file size\' = $file[\'size\'], ]; } These recipes cover the most common use cases you are likely to encounter in ThunderPHP plugins.',
            'order' => 17,
        ],
        [
            'id' => 'classes/request-class/best-practices',
            'title' => 'Best Practices',
            'description' => 'Recommended habits for using the Request class safely and cleanly in ThunderPHP plugins.',
            'topic' => 'Classes',
            'topic_slug' => 'classes',
            'subtopic' => 'Request Class',
            'subtopic_slug' => 'request-class',
            'section_slug' => 'best-practices',
            'url' => 'docs/classes/request-class/best-practices',
            'path' => 'classes/request-class/018-best-practices.md',
            'headings' => [
            ],
            'keywords' => [
                'best',
                'practices',
                'recommended',
                'habits',
                'request',
                'class',
                'safely',
                'cleanly',
                'thunderphp',
                'plugins',
                'classes',
                'prefer',
                'over',
                'direct',
                'superglobals',
                'per-field',
                'rules',
                'uploads',
                'validate',
                'images',
                'both',
                'mime',
                'types',
                'extensions',
            ],
            'search_text' => 'best practices recommended habits for using the request class safely and cleanly in thunderphp plugins. classes request class  here are some recommended practices when using the request class. prefer the class over direct superglobals instead of reading from $ post, $ get, $ files, and $ server everywhere, use the request class methods consistently. that keeps your code cleaner and easier to update later. use per field rules for uploads if a form contains different upload fields, do not try to force them through one shared configuration. use set upload rule() so each field has the correct rules. validate images as images if a field is meant for images, enable verify image and set size limits where appropriate. validate both mime types and extensions this gives you more reliable upload validation than checking only one of them. do not allow any unless you truly need it using any for mime types or extensions weakens upload security and should only be used for controlled internal workflows. use detailed results when storing files in the database if you need metadata like file size or mime type, prefer upload files detailed(). avoid publicly exposing sensitive uploads for private documents, consider storing files outside the public web root and serving them through controlled routes later. use randomized filenames do not rely on original filenames or predictable names if the uploads may later be publicly accessible. check for errors every time after any upload attempt, always check has upload errors() before assuming the file was stored successfully. example: $req = new \\\\core\\request(); $file = $req upload files(\'avatar\'); if($req has upload errors()) { message(\'error\', \'the upload failed\'); } else { message(\'success\', \'upload completed successfully\'); } these practices will help keep your plugins more predictable, safer, and easier to maintain.',
            'plain_text' => 'Here are some recommended practices when using the Request class. Prefer the class over direct superglobals Instead of reading from $ POST, $ GET, $ FILES, and $ SERVER everywhere, use the Request class methods consistently. That keeps your code cleaner and easier to update later. Use per field rules for uploads If a form contains different upload fields, do not try to force them through one shared configuration. Use set upload rule() so each field has the correct rules. Validate images as images If a field is meant for images, enable verify image and set size limits where appropriate. Validate both MIME types and extensions This gives you more reliable upload validation than checking only one of them. Do not allow any unless you truly need it Using any for MIME types or extensions weakens upload security and should only be used for controlled internal workflows. Use detailed results when storing files in the database If you need metadata like file size or MIME type, prefer upload files detailed(). Avoid publicly exposing sensitive uploads For private documents, consider storing files outside the public web root and serving them through controlled routes later. Use randomized filenames Do not rely on original filenames or predictable names if the uploads may later be publicly accessible. Check for errors every time After any upload attempt, always check has upload errors() before assuming the file was stored successfully. Example: $req = new \\\\Core\\Request(); $file = $req upload files(\'avatar\'); if($req has upload errors()) { message(\'error\', \'The upload failed\'); } else { message(\'success\', \'Upload completed successfully\'); } These practices will help keep your plugins more predictable, safer, and easier to maintain.',
            'order' => 18,
        ],
        [
            'id' => 'classes/session-class/session-class-overview',
