            'search_text' => 'session class overview introduction to the session class and its purpose. classes session class  the session class provides a structured and convenient way to interact with php sessions in thunderphp. it abstracts direct access to $ session, adds namespacing, and introduces advanced features such as: dot notation for nested data flash messages old input handling authentication helpers array utilities all session data is stored under a single root namespace: $ session[\'thunder\'];',
            'plain_text' => 'The Session class provides a structured and convenient way to interact with PHP sessions in ThunderPHP. It abstracts direct access to $ SESSION, adds namespacing, and introduces advanced features such as: Dot notation for nested data Flash messages Old input handling Authentication helpers Array utilities All session data is stored under a single root namespace: $ SESSION[\'THUNDER\'];',
            'order' => 1,
        ],
