            'search_text' => 'practical recipes real-world usage examples. classes session class  login system if($user){ $session auth($user, true); $session flash(\'success\', \'welcome back!\'); redirect(\'dashboard\'); } flash message display if($msg = $session get flash(\'success\')){ echo "$msg"; } form validation $session set old($ post); $session flash(\'error\', \'validation failed\'); redirect(\'form\'); shopping cart $session push(\'cart.items\', [ \'id\' = 1, \'qty\' = 1 ]); $total = count($session get(\'cart.items\', [])); page view counter $views = $session increment(\'page views\'); role check if(!$session is admin()){ die(\'access denied\'); }',
