        [
            'id' => 'command-line-tool-thunder/getting-started-with-thunder-cli/getting-started-with-thunder-cli',
            'title' => 'Getting Started with Thunder CLI',
            'description' => 'A beginner-friendly introduction to the Thunder CLI tool, what it does, and where it fits in a ThunderPHP project.',
            'topic' => 'Command Line Tool (thunder)',
            'topic_slug' => 'command-line-tool-thunder',
            'subtopic' => 'Getting started with thunder CLI',
            'subtopic_slug' => 'getting-started-with-thunder-cli',
            'section_slug' => 'getting-started-with-thunder-cli',
            'url' => 'docs/command-line-tool-thunder/getting-started-with-thunder-cli/getting-started-with-thunder-cli',
            'path' => 'command-line-tool-thunder/getting-started-with-thunder-cli/001-getting-started-with-thunder-cli.md',
            'headings' => [
            ],
            'keywords' => [
