                'line',
                'welcome',
                'guide',
                'covers',
                'basic',
                'idea',
                'things',
                'go',
            ],
            'search_text' => 'getting started with thunder cli a beginner-friendly introduction to the thunder cli tool, what it does, and where it fits in a thunderphp project. command line tool (thunder) getting started with thunder cli  welcome the thunder cli tool is the command line utility used to scaffold plugin files and manage database migrations in thunderphp. if you are new to thunderphp, think of thunder as the tool that helps you do two big jobs: generate files and folders quickly create and run database migrations safely in the provided implementation, the cli exposes generator commands such as make:plugin, make:model, and make:migration, along with migration commands such as migrate, migrate:rollback, migrate:refresh, and migrate:status. what this guide covers this beginner guide focuses on the most practical workflow: 1. create a plugin 2. generate a migration 3. write the migration 4. run the migration 5. check status 6. roll back if needed the basic idea a common beginner flow looks like this: // create a plugin php thunder make:plugin blog // create a migration inside that plugin php thunder make:migration blog create posts table // run pending migrations for the plugin php thunder migrate blog that is the foundation of the migration system. where things go the cli writes generated files into plugin folders under plugins/. for example: plugins/blog/ plugins/blog/models/ plugins/blog/controllers/ plugins/blog/migrations/ plugins/blog/looks/ so before learning migrations deeply, it helps to understand that thunderphp is plugin first. the cli is designed around that structure.',
            'plain_text' => 'Welcome The thunder CLI tool is the command line utility used to scaffold plugin files and manage database migrations in ThunderPHP. If you are new to ThunderPHP, think of thunder as the tool that helps you do two big jobs: generate files and folders quickly create and run database migrations safely In the provided implementation, the CLI exposes generator commands such as make:plugin, make:model, and make:migration, along with migration commands such as migrate, migrate:rollback, migrate:refresh, and migrate:status. What this guide covers This beginner guide focuses on the most practical workflow: 1. create a plugin 2. generate a migration 3. write the migration 4. run the migration 5. check status 6. roll back if needed The basic idea A common beginner flow looks like this: // Create a plugin php thunder make:plugin blog // Create a migration inside that plugin php thunder make:migration blog create posts table // Run pending migrations for the plugin php thunder migrate blog That is the foundation of the migration system. Where things go The CLI writes generated files into plugin folders under plugins/. For example: plugins/blog/ plugins/blog/models/ plugins/blog/controllers/ plugins/blog/migrations/ plugins/blog/looks/ So before learning migrations deeply, it helps to understand that ThunderPHP is plugin first. The CLI is designed around that structure.',
            'order' => 1,
        ],
        [
            'id' => 'command-line-tool-thunder/getting-started-with-thunder-cli/understanding-the-main-cli-commands',
            'title' => 'Understanding the Main CLI Commands',
            'description' => 'A simple overview of the most important Thunder commands a beginner will use first.',
            'topic' => 'Command Line Tool (thunder)',
            'topic_slug' => 'command-line-tool-thunder',
            'subtopic' => 'Getting started with thunder CLI',
            'subtopic_slug' => 'getting-started-with-thunder-cli',
            'section_slug' => 'understanding-the-main-cli-commands',
            'url' => 'docs/command-line-tool-thunder/getting-started-with-thunder-cli/understanding-the-main-cli-commands',
            'path' => 'command-line-tool-thunder/getting-started-with-thunder-cli/002-understanding-the-main-cli-commands.md',
            'headings' => [
