                'help',
                'good',
                'habit',
            ],
            'search_text' => 'understanding the main cli commands a simple overview of the most important thunder commands a beginner will use first. command line tool (thunder) getting started with thunder cli  the commands you will use most often when starting out, you do not need every command immediately. the most useful beginner commands are: php thunder help php thunder make:plugin php thunder make:model php thunder make:migration php thunder migrate php thunder migrate:status [plugin all] php thunder migrate:rollback php thunder migrate:refresh [filename] php thunder list:plugins what each one does help shows available commands make:plugin creates a plugin skeleton make:model creates a model stub inside a plugin make:migration creates a migration file inside a plugin migrate runs pending migrations migrate:status shows which migrations have run and which are still pending migrate:rollback reverses the latest migration batch migrate:refresh performs a rollback and then re runs the migration list:plugins shows installed plugins start with help if you forget command syntax, use: php thunder help this prints the built in help screen and is the easiest way to confirm argument order before doing anything destructive. a good habit a safe beginner habit is: php thunder migrate:status blog before and after every migration run. that makes it easy to see what changed.',
            'plain_text' => 'The commands you will use most often When starting out, you do not need every command immediately. The most useful beginner commands are: php thunder help php thunder make:plugin php thunder make:model php thunder make:migration php thunder migrate php thunder migrate:status [plugin all] php thunder migrate:rollback php thunder migrate:refresh [filename] php thunder list:plugins What each one does help shows available commands make:plugin creates a plugin skeleton make:model creates a model stub inside a plugin make:migration creates a migration file inside a plugin migrate runs pending migrations migrate:status shows which migrations have run and which are still pending migrate:rollback reverses the latest migration batch migrate:refresh performs a rollback and then re runs the migration list:plugins shows installed plugins Start with help If you forget command syntax, use: php thunder help This prints the built in help screen and is the easiest way to confirm argument order before doing anything destructive. A good habit A safe beginner habit is: php thunder migrate:status blog before and after every migration run. That makes it easy to see what changed.',
            'order' => 2,
        ],
