            'search_text' => 'creating your first plugin step-by-step beginner walkthrough for creating a new plugin with the thunder cli. command line tool (thunder) getting started with thunder cli  step 1: create the plugin the first command most beginners use is make:plugin. php thunder make:plugin blog this creates a new plugin folder with the expected thunderphp structure. what gets created the cli creates the base folder and common subfolders such as: plugins/blog/controllers/ plugins/blog/models/ plugins/blog/migrations/ plugins/blog/looks/main/ plugins/blog/looks/main/assets/css/ plugins/blog/looks/main/assets/js/ plugins/blog/looks/main/assets/fonts/ plugins/blog/looks/main/assets/images/ it also attempts to copy stub files like config.json, plugin starter files, css, javascript, and basic view files. if the plugin already exists if the folder already exists, the cli will stop unless you pass force: php thunder make:plugin blog force use force carefully. it is best used when you intentionally want to replace scaffold files. what to check next after creating the plugin, check the folder structure and confirm the plugin was created where you expected. a practical next step is to generate the model and migration you need for the plugin.',
            'plain_text' => 'Step 1: create the plugin The first command most beginners use is make:plugin. php thunder make:plugin blog This creates a new plugin folder with the expected ThunderPHP structure. What gets created The CLI creates the base folder and common subfolders such as: plugins/blog/controllers/ plugins/blog/models/ plugins/blog/migrations/ plugins/blog/looks/main/ plugins/blog/looks/main/assets/css/ plugins/blog/looks/main/assets/js/ plugins/blog/looks/main/assets/fonts/ plugins/blog/looks/main/assets/images/ It also attempts to copy stub files like config.json, plugin starter files, CSS, JavaScript, and basic view files. If the plugin already exists If the folder already exists, the CLI will stop unless you pass force: php thunder make:plugin blog force Use force carefully. It is best used when you intentionally want to replace scaffold files. What to check next After creating the plugin, check the folder structure and confirm the plugin was created where you expected. A practical next step is to generate the model and migration you need for the plugin.',
            'order' => 3,
        ],
