                'up',
            ],
            'search_text' => 'creating your first migration file how to generate a migration file, understand the filename, and know what the generated stub contains. command line tool (thunder) getting started with thunder cli  step 2: create a migration once your plugin exists, create a migration file inside it: php thunder make:migration blog create posts table where the file goes the file is created in: plugins/blog/migrations/ how the filename is built thunder prefixes the migration name with a timestamp, producing a filename like this: 2026 04 21 123456 create posts table.php this matters because migration files are sorted and run in filename order. what the generated stub contains the migration stub uses the migration namespace and creates a class that extends the base migration class. it includes two required methods: public function up() { // apply schema changes } public function down() { // reverse schema changes } why up() and down() matter up() is for applying the migration down() is for reversing it a good beginner rule is simple: whatever you create in up(), make sure down() can undo it cleanly.',
            'plain_text' => 'Step 2: create a migration Once your plugin exists, create a migration file inside it: php thunder make:migration blog create posts table Where the file goes The file is created in: plugins/blog/migrations/ How the filename is built Thunder prefixes the migration name with a timestamp, producing a filename like this: 2026 04 21 123456 create posts table.php This matters because migration files are sorted and run in filename order. What the generated stub contains The migration stub uses the Migration namespace and creates a class that extends the base Migration class. It includes two required methods: public function up() { // apply schema changes } public function down() { // reverse schema changes } Why up() and down() matter up() is for applying the migration down() is for reversing it A good beginner rule is simple: whatever you create in up(), make sure down() can undo it cleanly.',
