                'file',
            ],
            'search_text' => 'running migrations how to execute pending migrations for one plugin or all plugins, and what thunder does behind the scenes. command line tool (thunder) getting started with thunder cli  step 4: run the migration to run pending migrations for one plugin: php thunder migrate blog to run pending migrations across every plugin: php thunder migrate all what thunder does internally when you run migrate, thunder: 1. ensures the migration tracking table exists 2. resolves the target plugin folder or all plugin folders 3. loads migration files from each plugin\'s migrations/ folder 4. sorts them by filename 5. skips any migration already recorded as run 6. loads the class and executes up() 7. records the migration in the tracking table running a single migration file you can also target a specific filename if needed: php thunder migrate blog 2026 04 21 123456 create posts table.php that only runs the specified migration if it has not already been tracked as run. practical beginner tip after every migration run, immediately check status: php thunder migrate:status blog that confirms whether the migration was recorded successfully.',
            'plain_text' => 'Step 4: run the migration To run pending migrations for one plugin: php thunder migrate blog To run pending migrations across every plugin: php thunder migrate all What Thunder does internally When you run migrate, Thunder: 1. ensures the migration tracking table exists 2. resolves the target plugin folder or all plugin folders 3. loads migration files from each plugin\'s migrations/ folder 4. sorts them by filename 5. skips any migration already recorded as run 6. loads the class and executes up() 7. records the migration in the tracking table Running a single migration file You can also target a specific filename if needed: php thunder migrate blog 2026 04 21 123456 create posts table.php That only runs the specified migration if it has not already been tracked as run. Practical beginner tip After every migration run, immediately check status: php thunder migrate:status blog That confirms whether the migration was recorded successfully.',
