            ],
            'search_text' => 'checking migration status how to read migration status output and understand the difference between pending and ran migrations. command line tool (thunder) getting started with thunder cli  step 5: check status use the status command to see whether migrations are pending or already executed. php thunder migrate:status blog or for everything: php thunder migrate:status all what you will see thunder prints each migration file and labels it as one of these: [ran] [pending] for ran migrations, it also shows useful metadata such as: batch number run timestamp why this matters this gives you a quick answer to questions like: did my migration actually run? which file is still pending? what batch was this migration part of? a common workflow php thunder migrate:status blog php thunder migrate blog php thunder migrate:status blog this before and after pattern is a very good habit while learning.',
            'plain_text' => 'Step 5: check status Use the status command to see whether migrations are pending or already executed. php thunder migrate:status blog Or for everything: php thunder migrate:status all What you will see Thunder prints each migration file and labels it as one of these: [RAN] [PENDING] For ran migrations, it also shows useful metadata such as: batch number run timestamp Why this matters This gives you a quick answer to questions like: did my migration actually run? which file is still pending? what batch was this migration part of? A common workflow php thunder migrate:status blog php thunder migrate blog php thunder migrate:status blog This before and after pattern is a very good habit while learning.',
