                'needed',
            ],
            'search_text' => 'rolling back and refreshing migrations a beginner explanation of rollback batches, refresh behavior, and how to test schema changes safely. command line tool (thunder) getting started with thunder cli  step 6: roll back changes when needed if you need to undo the latest migration batch, use: php thunder migrate:rollback blog or for all plugins: php thunder migrate:rollback all important concept: rollback uses batches thunder records each migration run in a batch. a rollback does not usually undo every migration ever made. it undoes the latest batch. that means if you run three migrations together in one migrate command, they usually belong to one batch and may be rolled back together. refresh command thunder also supports: php thunder migrate:refresh blog this performs: 1. rollback 2. migrate again this is useful while developing and testing a migration repeatedly. when refresh is helpful use migrate:refresh when: you just edited the migration logic you want to rebuild the same table from scratch you are still in development and not protecting production data yet beginner warning be careful with rollback and refresh on real systems. if a migration drops a table in down(), your data may be lost.',
            'plain_text' => 'Step 6: roll back changes when needed If you need to undo the latest migration batch, use: php thunder migrate:rollback blog Or for all plugins: php thunder migrate:rollback all Important concept: rollback uses batches Thunder records each migration run in a batch. A rollback does not usually undo every migration ever made. It undoes the latest batch. That means if you run three migrations together in one migrate command, they usually belong to one batch and may be rolled back together. Refresh command Thunder also supports: php thunder migrate:refresh blog This performs: 1. rollback 2. migrate again This is useful while developing and testing a migration repeatedly. When refresh is helpful Use migrate:refresh when: you just edited the migration logic you want to rebuild the same table from scratch you are still in development and not protecting production data yet Beginner warning Be careful with rollback and refresh on real systems. If a migration drops a table in down(), your data may be lost.',
            'order' => 8,
        ],
