                'good',
                'beginner',
                'cases',
            ],
            'search_text' => 'seeding data in a migration how to add starter rows during a migration using adddata and insert. command line tool (thunder) getting started with thunder cli  adding starter data thunder migrations can also insert predefined rows. this is useful for things like: a default admin record starter settings default status values seed categories the migration class lets you queue rows with adddata() and then insert them with insert(). example: public function up() { $this addcolumn(\'id int unsigned auto increment\'); $this addcolumn(\'title varchar(100) null\'); $this addprimarykey(\'id\'); $this createtable(\'post statuses\'); $this adddata([ \'title\' = \'draft\' ]); $this adddata([ \'title\' = \'published\' ]); $this insert(\'post statuses\'); } how it works every adddata() call adds one row to an internal queue insert() loops through the queued rows and inserts them after insertion, the data queue is cleared good beginner use cases seeding is best for data that should exist immediately after the migration succeeds.',
            'plain_text' => 'Adding starter data Thunder migrations can also insert predefined rows. This is useful for things like: a default admin record starter settings default status values seed categories The migration class lets you queue rows with addData() and then insert them with insert(). Example: public function up() { $this addColumn(\'id int unsigned auto increment\'); $this addColumn(\'title varchar(100) null\'); $this addPrimaryKey(\'id\'); $this createTable(\'post statuses\'); $this addData([ \'title\' = \'draft\' ]); $this addData([ \'title\' = \'published\' ]); $this insert(\'post statuses\'); } How it works every addData() call adds one row to an internal queue insert() loops through the queued rows and inserts them after insertion, the data queue is cleared Good beginner use cases Seeding is best for data that should exist immediately after the migration succeeds.',
            'order' => 10,
        ],
        [
