                'reminder',
            ],
            'search_text' => 'altering existing tables a simple introduction to add, modify, rename, and drop operations for existing tables. command line tool (thunder) getting started with thunder cli  migrations are not only for new tables thunder\'s base migration class also includes helpers for altering existing tables. available methods include: addcolumntotable() modifycolumn() renamecolumn() dropcolumn() addforeignkeytotable() dropforeignkey() addindextotable() adduniqueindextotable() dropindex() example: add a new column public function up() { $this addcolumntotable(\'posts\', \'excerpt text null\'); } public function down() { $this dropcolumn(\'posts\', \'excerpt\'); } example: rename a column public function up() { $this renamecolumn(\'posts\', \'body\', \'content\', \'content text null\'); } beginner reminder when changing existing tables, make sure your down() method really reverses the same change where possible.',
            'plain_text' => 'Migrations are not only for new tables Thunder\'s base Migration class also includes helpers for altering existing tables. Available methods include: addColumnToTable() modifyColumn() renameColumn() dropColumn() addForeignKeyToTable() dropForeignKey() addIndexToTable() addUniqueIndexToTable() dropIndex() Example: add a new column public function up() { $this addColumnToTable(\'posts\', \'excerpt text null\'); } public function down() { $this dropColumn(\'posts\', \'excerpt\'); } Example: rename a column public function up() { $this renameColumn(\'posts\', \'body\', \'content\', \'content text null\'); } Beginner reminder When changing existing tables, make sure your down() method really reverses the same change where possible.',
            'order' => 11,
        ],
        [
            'id' => 'command-line-tool-thunder/getting-started-with-thunder-cli/how-thunder-tracks-migrations',
