                'numbers',
            ],
            'search_text' => 'how thunder tracks migrations a beginner explanation of the migration tracker table, batches, plugin scoping, and why this system matters. command line tool (thunder) getting started with thunder cli  why a tracker table exists thunder stores executed migration history in a database table named thunder migrations. this table tracks values such as: plugin id migration filename batch checksum run timestamp why this is important without tracking, thunder would not know: whether a migration already ran which batch should be rolled back which plugin a migration belongs to plugin scoping a migration is identified using both: plugin id migration name that means different plugins can safely have migrations with similar names, because thunder tracks them per plugin. batch numbers when you run migrations, thunder assigns a batch number. later, rollback uses that batch information to decide what to reverse. checksum thunder also stores a checksum of the migration file when it logs a run. this is useful metadata for auditing and future improvement, even if you are not yet using it for enforcement. beginner summary the migration tracker is the memory of the migration system. it tells thunder what happened before so that future commands can behave correctly.',
            'plain_text' => 'Why a tracker table exists Thunder stores executed migration history in a database table named thunder migrations. This table tracks values such as: plugin id migration filename batch checksum run timestamp Why this is important Without tracking, Thunder would not know: whether a migration already ran which batch should be rolled back which plugin a migration belongs to Plugin scoping A migration is identified using both: plugin id migration name That means different plugins can safely have migrations with similar names, because Thunder tracks them per plugin. Batch numbers When you run migrations, Thunder assigns a batch number. Later, rollback uses that batch information to decide what to reverse. Checksum Thunder also stores a checksum of the migration file when it logs a run. This is useful metadata for auditing and future improvement, even if you are not yet using it for enforcement. Beginner summary The migration tracker is the memory of the migration system. It tells Thunder what happened before so that future commands can behave correctly.',
