            'search_text' => 'a full beginner workflow example a complete practical example showing plugin creation, migration creation, running, status checking, and rollback. command line tool (thunder) getting started with thunder cli  putting it all together here is a simple beginner workflow for a new plugin named blog. 1. create the plugin php thunder make:plugin blog 2. create the migration php thunder make:migration blog create posts table 3. edit the generated migration file',
