        [
            'id' => 'command-line-tool-thunder/getting-started-with-thunder-cli/beginner-tips-and-common-mistakes',
            'title' => 'Beginner Tips and Common Mistakes',
            'description' => 'Practical advice to help beginners avoid the most common migration mistakes.',
            'topic' => 'Command Line Tool (thunder)',
            'topic_slug' => 'command-line-tool-thunder',
            'subtopic' => 'Getting started with thunder CLI',
            'subtopic_slug' => 'getting-started-with-thunder-cli',
            'section_slug' => 'beginner-tips-and-common-mistakes',
            'url' => 'docs/command-line-tool-thunder/getting-started-with-thunder-cli/beginner-tips-and-common-mistakes',
            'path' => 'command-line-tool-thunder/getting-started-with-thunder-cli/014-beginner-tips-and-common-mistakes.md',
            'headings' => [
            ],
            'keywords' => [
                'beginner',
                'tips',
