            'search_text' => 'thunder cli recipes overview a quick recipe-based guide for the most common thunder cli and migration tasks. command line tool (thunder) thunder cli recipes  this page is a practical companion to the full thunder cli and migration reference. it focuses on short, copy pasteable tasks you will perform often while working on plugins and database changes. these recipes assume you are running the cli tool through the thunder command and that your plugin lives inside the plugins/ folder. the recipes here are based on the thunder cli command list, the migration runner, the migration sample file, the migration tracker, and the base migration class. use this page when you want to quickly remember: what command to run what file gets created what to put inside the migration what happens when you migrate, rollback, refresh, or check status',
            'plain_text' => 'This page is a practical companion to the full Thunder CLI and Migration reference. It focuses on short, copy pasteable tasks you will perform often while working on plugins and database changes. These recipes assume you are running the CLI tool through the thunder command and that your plugin lives inside the plugins/ folder. The recipes here are based on the Thunder CLI command list, the migration runner, the migration sample file, the migration tracker, and the base Migration class. Use this page when you want to quickly remember: what command to run what file gets created what to put inside the migration what happens when you migrate, rollback, refresh, or check status',
