            'search_text' => 'create a migration file generate a timestamped migration file inside a plugin migrations folder. command line tool (thunder) thunder cli recipes  use this when you want to create a new migration file for a plugin. php thunder make:migration blog create posts table thunder creates the file inside the plugin\'s migrations/ folder using a timestamped filename. example output filename: plugins/blog/migrations/2026 04 21 103015 create posts table.php this timestamp prefix is important because migrations are sorted and executed in filename order. a good naming style is: create posts table add status to posts add author foreign key create comments table',
            'plain_text' => 'Use this when you want to create a new migration file for a plugin. php thunder make:migration blog create posts table Thunder creates the file inside the plugin\'s migrations/ folder using a timestamped filename. Example output filename: plugins/blog/migrations/2026 04 21 103015 create posts table.php This timestamp prefix is important because migrations are sorted and executed in filename order. A good naming style is: create posts table add status to posts add author foreign key create comments table',
