            'search_text' => 'rollback the latest migration batch undo the most recent migration batch by running down() on the latest logged files. command line tool (thunder) thunder cli recipes  use this when you want to undo the most recent migration batch. for one plugin: php thunder migrate:rollback blog for all plugins: php thunder migrate:rollback all important behavior: rollback does not remove every migration ever run it only targets the latest batch thunder resolves the files from the tracker table and runs down() on them migrations are processed in reverse order during rollback this is why writing a correct down() method matters.',
            'plain_text' => 'Use this when you want to undo the most recent migration batch. For one plugin: php thunder migrate:rollback blog For all plugins: php thunder migrate:rollback all Important behavior: rollback does not remove every migration ever run it only targets the latest batch Thunder resolves the files from the tracker table and runs down() on them migrations are processed in reverse order during rollback This is why writing a correct down() method matters.',
