            'search_text' => 'refresh a plugin migration set rollback the latest batch and then run migrate again for the plugin. command line tool (thunder) thunder cli recipes  use this when you want to rebuild the latest migration state for a plugin. php thunder migrate:refresh blog you can also target a specific file: php thunder migrate:refresh blog 2026 04 21 103015 create posts table.php this command effectively performs: php thunder migrate:rollback blog php thunder migrate blog this is useful during development when you are still adjusting the schema and want to quickly rerun the latest migration set.',
