            'id' => 'command-line-tool-thunder/thunder-cli-recipes/complete-everyday-workflow',
            'title' => 'Complete Everyday Workflow',
            'description' => 'A practical start-to-finish workflow for creating, checking, running, and rolling back migrations.',
            'topic' => 'Command Line Tool (thunder)',
            'topic_slug' => 'command-line-tool-thunder',
            'subtopic' => 'Thunder CLI Recipes',
