                'tool',
                'thunder',
                'cli',
                'recipes',
            ],
            'search_text' => 'complete everyday workflow a practical start-to-finish workflow for creating, checking, running, and rolling back migrations. command line tool (thunder) thunder cli recipes  this is a simple real world workflow you can follow during plugin development. create a plugin: php thunder make:plugin blog create a migration: php thunder make:migration blog create posts table edit the migration file and write up() and down(). check current status: php thunder migrate:status blog run pending migrations: php thunder migrate blog confirm they were logged: php thunder migrate:status blog if you need to undo the latest batch: php thunder migrate:rollback blog if you want to quickly rebuild the latest set while developing: php thunder migrate:refresh blog a safe habit is: create a new migration for every schema change never edit an old migration that already ran in shared environments always write a meaningful down() method use migrate:status before risky operations',
            'plain_text' => 'This is a simple real world workflow you can follow during plugin development. Create a plugin: php thunder make:plugin blog Create a migration: php thunder make:migration blog create posts table Edit the migration file and write up() and down(). Check current status: php thunder migrate:status blog Run pending migrations: php thunder migrate blog Confirm they were logged: php thunder migrate:status blog If you need to undo the latest batch: php thunder migrate:rollback blog If you want to quickly rebuild the latest set while developing: php thunder migrate:refresh blog A safe habit is: create a new migration for every schema change never edit an old migration that already ran in shared environments always write a meaningful down() method use migrate:status before risky operations',
            'order' => 18,
        ],
        [
            'id' => 'command-line-tool-thunder/thunder-cli-usage-and-commands/thunder-cli-overview',
            'title' => 'Thunder CLI Overview',
            'description' => 'Introduction to the Thunder CLI tool, its purpose, and the main command groups available in version 1.0.0.',
            'topic' => 'Command Line Tool (thunder)',
            'topic_slug' => 'command-line-tool-thunder',
            'subtopic' => 'Thunder CLI usage and commands',
            'subtopic_slug' => 'thunder-cli-usage-and-commands',
            'section_slug' => 'thunder-cli-overview',
            'url' => 'docs/command-line-tool-thunder/thunder-cli-usage-and-commands/thunder-cli-overview',
            'path' => 'command-line-tool-thunder/thunder-cli-usage-and-commands/001-thunder-cli-overview.md',
            'headings' => [
            ],
            'keywords' => [
                'thunder',
                'cli',
                'overview',
                'introduction',
                'tool',
                'purpose',
                'main',
                'command',
                'groups',
                'available',
                'version',
                'line',
                'usage',
                'commands',
                'dispatched',
                'typical',
                'flow',
                'assumes',
            ],
            'search_text' => 'thunder cli overview introduction to the thunder cli tool, its purpose, and the main command groups available in version 1.0.0. command line tool (thunder) thunder cli usage and commands  overview the thunder cli tool is the command line companion for thunderphp. it is responsible for scaffolding plugin files, generating boilerplate classes, validating plugin structure, and running database migrations. in the provided implementation, the cli is represented by the thunder\\thunder class and reports itself as version 1.0.0. it groups its features into three broad areas: generators such as make:plugin, make:model, and make:migration migration commands such as migrate, migrate:rollback, and migrate:status information and maintenance commands such as help, list:plugins, and validate main command groups the cli help output shows these major groups: generators migration info that means the tool is designed to support both project scaffolding and database lifecycle management from one place. how commands are dispatched the thunder cli class uses separate methods to handle different command families: help() displays command usage make() handles file and plugin generation list() prints installed plugin information validate() checks plugin structure and required metadata migrate() dispatches migration related actions this structure makes the cli easy to extend later because each family of commands has its own entry point. typical usage flow a common real world flow looks like this: // 1. create a plugin php thunder make:plugin blog // 2. create a model php thunder make:model blog post // 3. create a migration php thunder make:migration blog create posts table // 4. run migrations php thunder migrate blog // 5. check status php thunder migrate:status blog what the cli assumes the implementation assumes a plugin based directory structure rooted around the plugins/ folder. most generated files are placed inside plugin folders such as: plugins/blog/controllers/ plugins/blog/models/ plugins/blog/migrations/ plugins/blog/looks/ because of that, the cli is tightly integrated with the thunderphp plugin architecture rather than being a generic framework agnostic generator.',
            'plain_text' => 'Overview The thunder CLI tool is the command line companion for ThunderPHP. It is responsible for scaffolding plugin files, generating boilerplate classes, validating plugin structure, and running database migrations. In the provided implementation, the CLI is represented by the Thunder\\Thunder class and reports itself as version 1.0.0. It groups its features into three broad areas: generators such as make:plugin, make:model, and make:migration migration commands such as migrate, migrate:rollback, and migrate:status information and maintenance commands such as help, list:plugins, and validate Main command groups The CLI help output shows these major groups: Generators Migration Info That means the tool is designed to support both project scaffolding and database lifecycle management from one place. How commands are dispatched The Thunder CLI class uses separate methods to handle different command families: help() displays command usage make() handles file and plugin generation list() prints installed plugin information validate() checks plugin structure and required metadata migrate() dispatches migration related actions This structure makes the CLI easy to extend later because each family of commands has its own entry point. Typical usage flow A common real world flow looks like this: // 1. Create a plugin php thunder make:plugin blog // 2. Create a model php thunder make:model blog post // 3. Create a migration php thunder make:migration blog create posts table // 4. Run migrations php thunder migrate blog // 5. Check status php thunder migrate:status blog What the CLI assumes The implementation assumes a plugin based directory structure rooted around the plugins/ folder. Most generated files are placed inside plugin folders such as: plugins/blog/controllers/ plugins/blog/models/ plugins/blog/migrations/ plugins/blog/looks/ Because of that, the CLI is tightly integrated with the ThunderPHP plugin architecture rather than being a generic framework agnostic generator.',
            'order' => 1,
        ],
        [
            'id' => 'command-line-tool-thunder/thunder-cli-usage-and-commands/help-command',
            'title' => 'help Command',
            'description' => 'Reference for the help command and the built-in command list displayed by the Thunder CLI.',
            'topic' => 'Command Line Tool (thunder)',
            'topic_slug' => 'command-line-tool-thunder',
            'subtopic' => 'Thunder CLI usage and commands',
            'subtopic_slug' => 'thunder-cli-usage-and-commands',
            'section_slug' => 'help-command',
            'url' => 'docs/command-line-tool-thunder/thunder-cli-usage-and-commands/help-command',
            'path' => 'command-line-tool-thunder/thunder-cli-usage-and-commands/002-help-command.md',
            'headings' => [
            ],
            'keywords' => [
                'help',
                'command',
                'reference',
                'built-in',
                'list',
                'displayed',
                'thunder',
                'cli',
                'line',
                'tool',
                'usage',
                'commands',
                'purpose',
                'displays',
                'output',
                'styled',
                'practical',
                'note',
            ],
            'search_text' => 'help command reference for the help command and the built-in command list displayed by the thunder cli. command line tool (thunder) thunder cli usage and commands  purpose the help command prints the available thunder cli commands grouped by purpose. it is the main discovery tool for anyone using the cli for the first time. usage php thunder help what it displays the help screen includes: generator commands migration commands informational commands the command list currently includes: make:plugin [ force] make:controller make:model make:migration make:pager make:view help migrate [filename] migrate:rollback migrate:refresh [filename] migrate:status [plugin all] list:plugins how the output is styled the cli uses ansi escape codes internally to color text output. that means: headings are highlighted success and failure states are easier to distinguish command names are visually separated from descriptions this is a usability feature only. it does not affect how commands behave. when to use it use help when: learning the cli confirming argument order checking whether a command exists reviewing migration command syntax before running database changes practical note because the help output is manually defined, it reflects the current cli implementation exactly. if you add custom thunder commands later, update the help screen too so the documentation and the cli stay aligned.',
            'plain_text' => 'Purpose The help command prints the available Thunder CLI commands grouped by purpose. It is the main discovery tool for anyone using the CLI for the first time. Usage php thunder help What it displays The help screen includes: generator commands migration commands informational commands The command list currently includes: make:plugin [ force] make:controller make:model make:migration make:pager make:view help migrate [filename] migrate:rollback migrate:refresh [filename] migrate:status [plugin all] list:plugins How the output is styled The CLI uses ANSI escape codes internally to color text output. That means: headings are highlighted success and failure states are easier to distinguish command names are visually separated from descriptions This is a usability feature only. It does not affect how commands behave. When to use it Use help when: learning the CLI confirming argument order checking whether a command exists reviewing migration command syntax before running database changes Practical note Because the help output is manually defined, it reflects the current CLI implementation exactly. If you add custom Thunder commands later, update the help screen too so the documentation and the CLI stay aligned.',
            'order' => 2,
        ],
        [
            'id' => 'command-line-tool-thunder/thunder-cli-usage-and-commands/make-plugin',
            'title' => 'make:plugin',
            'description' => 'How to generate a new plugin skeleton with Thunder, including folder structure, stubs, and the force overwrite option.',
            'topic' => 'Command Line Tool (thunder)',
            'topic_slug' => 'command-line-tool-thunder',
            'subtopic' => 'Thunder CLI usage and commands',
            'subtopic_slug' => 'thunder-cli-usage-and-commands',
            'section_slug' => 'make-plugin',
            'url' => 'docs/command-line-tool-thunder/thunder-cli-usage-and-commands/make-plugin',
            'path' => 'command-line-tool-thunder/thunder-cli-usage-and-commands/003-make-plugin.md',
            'headings' => [
            ],
            'keywords' => [
                'make',
                'plugin',
                'generate',
                'new',
                'skeleton',
                'thunder',
                'including',
                'folder',
