                'cli',
                'usage',
                'commands',
                'purpose',
                'gets',
                'created',
                'starter',
                'files',
            ],
            'search_text' => 'make:plugin how to generate a new plugin skeleton with thunder, including folder structure, stubs, and the force overwrite option. command line tool (thunder) thunder cli usage and commands  purpose the make:plugin command creates a new plugin folder with the standard thunderphp structure and starter files. usage php thunder make:plugin blog to overwrite an existing plugin folder: php thunder make:plugin blog force what gets created the command creates the plugin base directory and common subfolders, including: plugins/blog/ plugins/blog/controllers/ plugins/blog/models/ plugins/blog/migrations/ plugins/blog/looks/ plugins/blog/looks/main/ plugins/blog/looks/main/assets/css/ plugins/blog/looks/main/assets/js/ plugins/blog/looks/main/assets/fonts/ plugins/blog/looks/main/assets/images/ starter files the command also attempts to copy sample stub files into the plugin. these include starter files for things like: plugin.php config.json look.json starter css starter javascript starter home view starter controller placeholder replacement when stub files are copied, the cli replaces placeholders such as: {namespace} this allows generated code to match the plugin\'s namespace automatically. for example, a plugin id like basic user becomes a namespace like: basicuser force mode if the target plugin already exists: without force, the cli stops and warns you with force, it continues and overwrites scaffold files practical recipe // create a new plugin called school fees php thunder make:plugin school fees // then add a model php thunder make:model school fees invoice // then add a migration php thunder make:migration school fees create invoices table important note make:plugin creates the folder structure and starter files, but it does not register routes, run migrations, or seed data automatically. those steps still depend on your plugin code and migration execution.',
            'plain_text' => 'Purpose The make:plugin command creates a new plugin folder with the standard ThunderPHP structure and starter files. Usage php thunder make:plugin blog To overwrite an existing plugin folder: php thunder make:plugin blog force What gets created The command creates the plugin base directory and common subfolders, including: plugins/blog/ plugins/blog/controllers/ plugins/blog/models/ plugins/blog/migrations/ plugins/blog/looks/ plugins/blog/looks/main/ plugins/blog/looks/main/assets/css/ plugins/blog/looks/main/assets/js/ plugins/blog/looks/main/assets/fonts/ plugins/blog/looks/main/assets/images/ Starter files The command also attempts to copy sample stub files into the plugin. These include starter files for things like: plugin.php config.json look.json starter CSS starter JavaScript starter home view starter controller Placeholder replacement When stub files are copied, the CLI replaces placeholders such as: {NAMESPACE} This allows generated code to match the plugin\'s namespace automatically. For example, a plugin id like basic user becomes a namespace like: BasicUser Force mode If the target plugin already exists: without force, the CLI stops and warns you with force, it continues and overwrites scaffold files Practical recipe // Create a new plugin called school fees php thunder make:plugin school fees // Then add a model php thunder make:model school fees invoice // Then add a migration php thunder make:migration school fees create invoices table Important note make:plugin creates the folder structure and starter files, but it does not register routes, run migrations, or seed data automatically. Those steps still depend on your plugin code and migration execution.',
            'order' => 3,
        ],
        [
            'id' => 'command-line-tool-thunder/thunder-cli-usage-and-commands/file-generators',
            'title' => 'File Generators',
            'description' => 'Reference for generator commands that create controllers, models, views, migrations, pagers, and validators.',
            'topic' => 'Command Line Tool (thunder)',
            'topic_slug' => 'command-line-tool-thunder',
            'subtopic' => 'Thunder CLI usage and commands',
