                'behavior',
                'controller',
                'generation',
            ],
            'search_text' => 'file generators reference for generator commands that create controllers, models, views, migrations, pagers, and validators. command line tool (thunder) thunder cli usage and commands  overview thunder provides a family of make: commands for generating files inside a plugin. these commands use stub templates and write the generated files into the correct plugin folders. available generator commands php thunder make:controller php thunder make:model php thunder make:migration php thunder make:pager php thunder make:validator php thunder make:view general behavior all generator commands: require a plugin name require a file or class name create missing folders if necessary use sample stub files when available controller generation php thunder make:controller blog admin/posts this allows nested paths. if the name contains folders, thunder creates the subfolder first, then writes the controller file there. model generation php thunder make:model blog post model files are automatically uppercased on the first letter: plugins/blog/models/post.php migration generation php thunder make:migration blog create posts table migration filenames are timestamp prefixed automatically: plugins/blog/migrations/2026 04 21 153000 create posts table.php this is important because migration execution order is based on filename sorting. view generation php thunder make:view blog frontend/post list views can also be placed inside nested folders when the name includes a path. how class names are built the cli sanitizes the provided name before generating classes. it: removes unsupported characters converts hyphens to underscores uppercases the first letter so a name like: user profile becomes a class name like: user profile practical recipe // generate a full starting set for a plugin php thunder make:controller shop products php thunder make:model shop product php thunder make:migration shop create products table php thunder make:view shop admin/products important limitation these commands generate files only. they do not automatically wire the files into plugin hooks or routes. after generation, you still need to connect the code to your plugin\'s runtime behavior.',
            'plain_text' => 'Overview Thunder provides a family of make: commands for generating files inside a plugin. These commands use stub templates and write the generated files into the correct plugin folders. Available generator commands php thunder make:controller php thunder make:model php thunder make:migration php thunder make:pager php thunder make:validator php thunder make:view General behavior All generator commands: require a plugin name require a file or class name create missing folders if necessary use sample stub files when available Controller generation php thunder make:controller blog admin/posts This allows nested paths. If the name contains folders, Thunder creates the subfolder first, then writes the controller file there. Model generation php thunder make:model blog post Model files are automatically uppercased on the first letter: plugins/blog/models/Post.php Migration generation php thunder make:migration blog create posts table Migration filenames are timestamp prefixed automatically: plugins/blog/migrations/2026 04 21 153000 create posts table.php This is important because migration execution order is based on filename sorting. View generation php thunder make:view blog frontend/post list Views can also be placed inside nested folders when the name includes a path. How class names are built The CLI sanitizes the provided name before generating classes. It: removes unsupported characters converts hyphens to underscores uppercases the first letter So a name like: user profile becomes a class name like: User profile Practical recipe // Generate a full starting set for a plugin php thunder make:controller shop products php thunder make:model shop product php thunder make:migration shop create products table php thunder make:view shop admin/products Important limitation These commands generate files only. They do not automatically wire the files into plugin hooks or routes. After generation, you still need to connect the code to your plugin\'s runtime behavior.',
            'order' => 4,
        ],
        [
            'id' => 'command-line-tool-thunder/thunder-cli-usage-and-commands/list-plugins-and-validate',
