            'search_text' => 'list:plugins and validate how to inspect installed plugins and validate plugin metadata using thunder cli commands. command line tool (thunder) thunder cli usage and commands  list:plugins the list:plugins command scans the plugins/ folder and displays metadata for installed plugins. usage php thunder list:plugins what it reads for each plugin folder, the command looks for: plugins/{plugin}/config.json if the file exists and contains valid json, the cli prints values such as: plugin name plugin id author version active status when this is useful use list:plugins when: checking whether a plugin exists reviewing plugin metadata quickly confirming active or inactive status debugging plugin installation issues validate the validate command checks plugin structure at a basic metadata level. usage php thunder validate what it checks a plugin is considered valid only if: config.json exists config.json contains valid json required fields are present the required fields are: name id routes version what the report looks like the cli prints one result per plugin: ✅ plugin name — valid ❌ plugin name — missing config.json ❌ plugin name — malformed json ❌ plugin name — missing fields: routes, version it then prints a summary count of valid and invalid plugins. practical recipe run this after manually creating or copying plugins: php thunder validate php thunder list:plugins this gives you both a structural report and a readable metadata summary. important note validate checks the plugin manifest only. it does not validate controller code, migrations, database schema, or hook registration.',
            'plain_text' => 'list:plugins The list:plugins command scans the plugins/ folder and displays metadata for installed plugins. Usage php thunder list:plugins What it reads For each plugin folder, the command looks for: plugins/{plugin}/config.json If the file exists and contains valid JSON, the CLI prints values such as: plugin name plugin id author version active status When this is useful Use list:plugins when: checking whether a plugin exists reviewing plugin metadata quickly confirming active or inactive status debugging plugin installation issues validate The validate command checks plugin structure at a basic metadata level. Usage php thunder validate What it checks A plugin is considered valid only if: config.json exists config.json contains valid JSON required fields are present The required fields are: name id routes version What the report looks like The CLI prints one result per plugin: ✅ plugin name — valid ❌ plugin name — missing config.json ❌ plugin name — malformed JSON ❌ plugin name — missing fields: routes, version It then prints a summary count of valid and invalid plugins. Practical recipe Run this after manually creating or copying plugins: php thunder validate php thunder list:plugins This gives you both a structural report and a readable metadata summary. Important note validate checks the plugin manifest only. It does not validate controller code, migrations, database schema, or hook registration.',
            'order' => 5,
        ],
