            ],
            'search_text' => 'migration commands reference for migrate, rollback, refresh, and status commands exposed by the thunder cli. command line tool (thunder) thunder cli usage and commands  overview thunder exposes migration commands through the migrate() command dispatcher. these commands operate on one plugin or all plugins. available commands php thunder migrate [filename] php thunder migrate:rollback php thunder migrate:refresh [filename] php thunder migrate:status [plugin all] migrate runs pending migrations. php thunder migrate blog run all plugins: php thunder migrate all run one specific migration file if it is still pending: php thunder migrate blog 2026 04 21 153000 create posts table.php migrate:rollback rolls back the latest migration batch. php thunder migrate:rollback blog or for all plugins: php thunder migrate:rollback all migrate:refresh performs a rollback followed by a migrate. php thunder migrate:refresh blog this is useful during development when rebuilding a plugin schema repeatedly. migrate:status shows which migration files have already run and which are still pending. php thunder migrate:status blog php thunder migrate:status all how status labels work the status output marks migrations as: [ran] [pending] for ran migrations, it also shows: batch number ran timestamp practical workflow // create the migration file php thunder make:migration blog create posts table // run it php thunder migrate blog // confirm it ran php thunder migrate:status blog // roll it back if needed php thunder migrate:rollback blog important behavior a migration file is skipped during migrate if thunder already logged it as having run. that protects you from re running the same migration accidentally unless you remove its record through rollback.',
            'plain_text' => 'Overview Thunder exposes migration commands through the migrate() command dispatcher. These commands operate on one plugin or all plugins. Available commands php thunder migrate [filename] php thunder migrate:rollback php thunder migrate:refresh [filename] php thunder migrate:status [plugin all] migrate Runs pending migrations. php thunder migrate blog Run all plugins: php thunder migrate all Run one specific migration file if it is still pending: php thunder migrate blog 2026 04 21 153000 create posts table.php migrate:rollback Rolls back the latest migration batch. php thunder migrate:rollback blog Or for all plugins: php thunder migrate:rollback all migrate:refresh Performs a rollback followed by a migrate. php thunder migrate:refresh blog This is useful during development when rebuilding a plugin schema repeatedly. migrate:status Shows which migration files have already run and which are still pending. php thunder migrate:status blog php thunder migrate:status all How status labels work The status output marks migrations as: [RAN] [PENDING] For ran migrations, it also shows: batch number ran timestamp Practical workflow // Create the migration file php thunder make:migration blog create posts table // Run it php thunder migrate blog // Confirm it ran php thunder migrate:status blog // Roll it back if needed php thunder migrate:rollback blog Important behavior A migration file is skipped during migrate if Thunder already logged it as having run. That protects you from re running the same migration accidentally unless you remove its record through rollback.',
            'order' => 6,
        ],
        [
            'id' => 'database-migrations/migrations-overview/migration-system-overview',
            'title' => 'Migration System Overview',
            'description' => 'Introduction to Thunder migrations, how migration classes are structured, and how the schema builder workflow operates.',
            'topic' => 'Database Migrations',
            'topic_slug' => 'database-migrations',
            'subtopic' => 'Migrations Overview',
            'subtopic_slug' => 'migrations-overview',
            'section_slug' => 'migration-system-overview',
            'url' => 'docs/database-migrations/migrations-overview/migration-system-overview',
            'path' => 'database-migrations/migrations-overview/007-migration-system-overview.md',
            'headings' => [
            ],
            'keywords' => [
                'migration',
                'system',
                'overview',
                'introduction',
                'thunder',
                'migrations',
                'classes',
                'structured',
                'schema',
                'builder',
                'workflow',
                'operates',
                'database',
                'basic',
                'structure',
                'uses',
                'why',
                'timestamp',
                'prefix',
                'matters',
                'namespace',
                'requirement',
                'builder-based',
                'design',
            ],
            'search_text' => 'migration system overview introduction to thunder migrations, how migration classes are structured, and how the schema builder workflow operates. database migrations migrations overview  overview thunder migrations are php classes used to define database schema changes in code. each migration class extends the base migration class and usually contains two methods: up() for applying the change down() for reversing the change basic structure a generated migration follows this general pattern: namespace migration; class create posts table extends migration { public function up() { $this addcolumn(\'id int unsigned auto increment\'); $this addprimarykey(\'id\'); $this createtable(\'posts\'); } public function down() { $this droptable(\'posts\'); } } how thunder uses migrations when you run: php thunder migrate blog thunder: 1. finds the plugin\'s migration files 2. sorts them by filename 3. resolves the migration class name from the filename 4. instantiates the class 5. calls up() 6. logs the migration in the migration tracker when rolling back, thunder calls down() and removes the migration record from the tracker. why the timestamp prefix matters migration filenames are generated with a timestamp prefix such as: 2026 04 21 153000 create posts table.php that naming strategy gives you deterministic execution order. earlier files run first. namespace requirement thunder resolves migration classes under the migration namespace. that means your migration file must define classes like: namespace migration; if the class is missing or the namespace is wrong, thunder cannot resolve and execute the migration. builder based design the migration class is not a raw sql runner only. it works like a schema builder. you usually queue definitions first: $this addcolumn(...) $this addkey(...) $this addprimarykey(...) and then execute the final table creation: $this createtable(\'my table\'); this separation makes migrations easier to read and maintain.',
            'plain_text' => 'Overview Thunder migrations are PHP classes used to define database schema changes in code. Each migration class extends the base Migration class and usually contains two methods: up() for applying the change down() for reversing the change Basic structure A generated migration follows this general pattern: namespace Migration; class Create posts table extends Migration { public function up() { $this addColumn(\'id int unsigned auto increment\'); $this addPrimaryKey(\'id\'); $this createTable(\'posts\'); } public function down() { $this dropTable(\'posts\'); } } How Thunder uses migrations When you run: php thunder migrate blog Thunder: 1. finds the plugin\'s migration files 2. sorts them by filename 3. resolves the migration class name from the filename 4. instantiates the class 5. calls up() 6. logs the migration in the migration tracker When rolling back, Thunder calls down() and removes the migration record from the tracker. Why the timestamp prefix matters Migration filenames are generated with a timestamp prefix such as: 2026 04 21 153000 create posts table.php That naming strategy gives you deterministic execution order. Earlier files run first. Namespace requirement Thunder resolves migration classes under the Migration namespace. That means your migration file must define classes like: namespace Migration; If the class is missing or the namespace is wrong, Thunder cannot resolve and execute the migration. Builder based design The Migration class is not a raw SQL runner only. It works like a schema builder. You usually queue definitions first: $this addColumn(...) $this addKey(...) $this addPrimaryKey(...) and then execute the final table creation: $this createTable(\'my table\'); This separation makes migrations easier to read and maintain.',
            'order' => 7,
        ],
        [
            'id' => 'database-migrations/migrations-overview/creating-migration-files',
            'title' => 'Creating Migration Files',
            'description' => 'How migration files are generated, named, located, and resolved into executable classes.',
            'topic' => 'Database Migrations',
            'topic_slug' => 'database-migrations',
            'subtopic' => 'Migrations Overview',
            'subtopic_slug' => 'migrations-overview',
            'section_slug' => 'creating-migration-files',
            'url' => 'docs/database-migrations/migrations-overview/creating-migration-files',
            'path' => 'database-migrations/migrations-overview/008-creating-migration-files.md',
            'headings' => [
            ],
            'keywords' => [
                'creating',
                'migration',
