                'required',
                'namespace',
                'example',
            ],
            'search_text' => 'creating migration files how migration files are generated, named, located, and resolved into executable classes. database migrations migrations overview  generating a migration use the thunder cli to create a migration file: php thunder make:migration blog create posts table where the file is created the file is placed in the plugin\'s migrations folder: plugins/blog/migrations/ automatic filename format thunder prefixes migration files with the current date and time: yyyy mm dd his name.php example: 2026 04 21 153000 create posts table.php this is important because thunder later sorts migration files alphabetically, which also makes them run in chronological order. how class names are derived thunder strips the timestamp prefix and converts the remaining name into a class name. it also: removes unsupported characters converts hyphens to underscores uppercases the first letter so this file: 2026 04 21 153000 create posts table.php maps to a class name like: \\migration\\create posts table required namespace your migration class must live in the migration namespace: namespace migration; example generated migration namespace migration; class create posts table extends migration { public function up() { $this addcolumn(\'id int unsigned auto increment\'); $this addprimarykey(\'id\'); $this createtable(\'posts\'); } public function down() { $this droptable(\'posts\'); } } important rule the file name and the class name must remain compatible with thunder\'s resolver. if you rename one carelessly without the other, thunder may fail to load the migration. practical tip use descriptive migration names that explain the schema change clearly, such as: create users table add status to orders create post comments table add foreign key to invoices this makes migration history much easier to understand later.',
            'plain_text' => 'Generating a migration Use the Thunder CLI to create a migration file: php thunder make:migration blog create posts table Where the file is created The file is placed in the plugin\'s migrations folder: plugins/blog/migrations/ Automatic filename format Thunder prefixes migration files with the current date and time: YYYY MM DD His name.php Example: 2026 04 21 153000 create posts table.php This is important because Thunder later sorts migration files alphabetically, which also makes them run in chronological order. How class names are derived Thunder strips the timestamp prefix and converts the remaining name into a class name. It also: removes unsupported characters converts hyphens to underscores uppercases the first letter So this file: 2026 04 21 153000 create posts table.php maps to a class name like: \\Migration\\Create posts table Required namespace Your migration class must live in the Migration namespace: namespace Migration; Example generated migration namespace Migration; class Create posts table extends Migration { public function up() { $this addColumn(\'id int unsigned auto increment\'); $this addPrimaryKey(\'id\'); $this createTable(\'posts\'); } public function down() { $this dropTable(\'posts\'); } } Important rule The file name and the class name must remain compatible with Thunder\'s resolver. If you rename one carelessly without the other, Thunder may fail to load the migration. Practical tip Use descriptive migration names that explain the schema change clearly, such as: create users table add status to orders create post comments table add foreign key to invoices This makes migration history much easier to understand later.',
            'order' => 8,
        ],
        [
            'id' => 'database-migrations/migrations-overview/the-up-and-down-methods',
            'title' => 'The up() and down() Methods',
            'description' => 'Reference for the purpose and expected behavior of up and down methods in Thunder migrations.',
            'topic' => 'Database Migrations',
            'topic_slug' => 'database-migrations',
            'subtopic' => 'Migrations Overview',
            'subtopic_slug' => 'migrations-overview',
            'section_slug' => 'the-up-and-down-methods',
            'url' => 'docs/database-migrations/migrations-overview/the-up-and-down-methods',
            'path' => 'database-migrations/migrations-overview/009-the-up-and-down-methods.md',
            'headings' => [
            ],
            'keywords' => [
                'up',
                'down',
                'methods',
                'reference',
                'purpose',
                'expected',
                'behavior',
                'thunder',
                'migrations',
                'database',
                'overview',
                'best',
                'practice',
                'perfect',
                'reversal',
                'possible',
                'practical',
                'recipe',
            ],
            'search_text' => 'the up() and down() methods reference for the purpose and expected behavior of up and down methods in thunder migrations. database migrations migrations overview  purpose every migration should define two core methods: up() applies the schema change down() reverses it together, these methods make migrations reversible. up() use up() to create or modify database structures. examples of things you may do in up(): create a table add columns add indexes add foreign keys insert seed data example: public function up() { $this addcolumn(\'id int unsigned auto increment\'); $this addcolumn(\'title varchar(255) not null\'); $this addprimarykey(\'id\'); $this createtable(\'posts\'); } down() use down() to undo what up() did. example: public function down() { $this droptable(\'posts\'); } if up() added a column to an existing table, then down() should normally drop that same column. example: public function up() { $this addcolumntotable(\'posts\', \'status varchar(50) default "draft"\'); } public function down() { $this dropcolumn(\'posts\', \'status\'); } best practice keep down() accurate. a migration system is much more useful when rollbacks truly reverse the change. when perfect reversal is not possible sometimes destructive changes are difficult to restore exactly. for example, if up() drops a column with data in it, down() cannot realistically recover the lost data. in those cases: document the limitation in comments avoid destructive schema changes unless necessary back up data first in production environments practical recipe public function up() { $this addcolumntotable(\'users\', \'phone varchar(30) null\'); $this addindextotable(\'users\', \'phone\', \'idx users phone\'); } public function down() { $this dropindex(\'users\', \'idx users phone\'); $this dropcolumn(\'users\', \'phone\'); } this gives you a clean reversible migration.',
            'plain_text' => 'Purpose Every migration should define two core methods: up() applies the schema change down() reverses it Together, these methods make migrations reversible. up() Use up() to create or modify database structures. Examples of things you may do in up(): create a table add columns add indexes add foreign keys insert seed data Example: public function up() { $this addColumn(\'id int unsigned auto increment\'); $this addColumn(\'title varchar(255) not null\'); $this addPrimaryKey(\'id\'); $this createTable(\'posts\'); } down() Use down() to undo what up() did. Example: public function down() { $this dropTable(\'posts\'); } If up() added a column to an existing table, then down() should normally drop that same column. Example: public function up() { $this addColumnToTable(\'posts\', \'status varchar(50) default "draft"\'); } public function down() { $this dropColumn(\'posts\', \'status\'); } Best practice Keep down() accurate. A migration system is much more useful when rollbacks truly reverse the change. When perfect reversal is not possible Sometimes destructive changes are difficult to restore exactly. For example, if up() drops a column with data in it, down() cannot realistically recover the lost data. In those cases: document the limitation in comments avoid destructive schema changes unless necessary back up data first in production environments Practical recipe public function up() { $this addColumnToTable(\'users\', \'phone varchar(30) null\'); $this addIndexToTable(\'users\', \'phone\', \'idx users phone\'); } public function down() { $this dropIndex(\'users\', \'idx users phone\'); $this dropColumn(\'users\', \'phone\'); } This gives you a clean reversible migration.',
            'order' => 9,
        ],
        [
            'id' => 'database-migrations/migrations-overview/table-builder-methods',
            'title' => 'Table Builder Methods',
            'description' => 'Comprehensive reference for createTable, addColumn, addKey, addPrimaryKey, addUniqueKey, addFullTextKey, and table settings.',
            'topic' => 'Database Migrations',
            'topic_slug' => 'database-migrations',
            'subtopic' => 'Migrations Overview',
            'subtopic_slug' => 'migrations-overview',
            'section_slug' => 'table-builder-methods',
            'url' => 'docs/database-migrations/migrations-overview/table-builder-methods',
            'path' => 'database-migrations/migrations-overview/010-table-builder-methods.md',
            'headings' => [
            ],
            'keywords' => [
                'table',
                'builder',
                'methods',
                'comprehensive',
                'reference',
                'createtable',
                'addcolumn',
                'addkey',
                'addprimarykey',
                'adduniquekey',
                'addfulltextkey',
                'settings',
                'database',
                'migrations',
                'overview',
                'string',
                'bool',
                'column',
                'void',
                'array',
                'primarykey',
                'name',
                'key',
                'complete',
            ],
            'search_text' => 'table builder methods comprehensive reference for createtable, addcolumn, addkey, addprimarykey, adduniquekey, addfulltextkey, and table settings. database migrations migrations overview  overview the base migration class provides a queue based builder for constructing new tables. you define columns, indexes, and constraints first, then call createtable() once. createtable(string $table): bool creates the table using the definitions you have already added. $this createtable(\'posts\'); if no columns were added first, table creation fails. addcolumn(string $column): void adds a raw sql column definition to the queue. $this addcolumn(\'id int unsigned auto increment\'); $this addcolumn(\'title varchar(255) not null\'); $this addcolumn(\'content text null\'); because this method accepts raw sql fragments, you have full flexibility, but you must provide valid sql syntax yourself. addprimarykey(string array $primarykey, string $name = \'\'): void adds a primary key definition. single column example: $this addprimarykey(\'id\'); composite example: $this addprimarykey([\'school id\', \'year\', \'term\']); optional named constraint: $this addprimarykey(\'id\', \'pk posts id\'); addkey(string array $key, string $name = \'\'): void adds a normal index. $this addkey(\'date created\'); $this addkey(\'user id\', \'idx posts user id\'); $this addkey([\'school id\', \'year\'], \'idx school year\'); adduniquekey(string array $key, string $name = \'\'): void adds a unique index. $this adduniquekey(\'slug\', \'uniq posts slug\'); $this adduniquekey([\'school id\', \'code\'], \'uniq school code\'); addfulltextkey(string array $key, string $name = \'\'): void adds a fulltext index. $this addfulltextkey(\'body\'); $this addfulltextkey([\'title\', \'body\'], \'ft posts search\'); use this when your storage engine and database version support fulltext indexing for the target columns. table settings you can customize the table engine, charset, and collation before creation. $this addengine(\'innodb\'); $this addcharset(\'utf8mb4\'); $this addcollate(\'utf8mb4 general ci\'); these settings affect the generated create table statement. complete example public function up() { $this addcolumn(\'id int unsigned auto increment\'); $this addcolumn(\'user id int unsigned default 0\'); $this addcolumn(\'title varchar(255) not null\'); $this addcolumn(\'slug varchar(150) not null\'); $this addcolumn(\'body text null\'); $this addcolumn(\'date created datetime default null\'); $this addprimarykey(\'id\'); $this addkey(\'user id\', \'idx posts user id\'); $this adduniquekey(\'slug\', \'uniq posts slug\'); $this addfulltextkey([\'title\', \'body\'], \'ft posts search\'); $this addengine(\'innodb\'); $this addcharset(\'utf8mb4\'); $this addcollate(\'utf8mb4 general ci\'); $this createtable(\'posts\'); } important note the builder state is reset after a successful createtable(). that prevents definitions from leaking into the next table build inside the same migration.',
            'plain_text' => 'Overview The base Migration class provides a queue based builder for constructing new tables. You define columns, indexes, and constraints first, then call createTable() once. createTable(string $table): bool Creates the table using the definitions you have already added. $this createTable(\'posts\'); If no columns were added first, table creation fails. addColumn(string $column): void Adds a raw SQL column definition to the queue. $this addColumn(\'id int unsigned auto increment\'); $this addColumn(\'title varchar(255) not null\'); $this addColumn(\'content text null\'); Because this method accepts raw SQL fragments, you have full flexibility, but you must provide valid SQL syntax yourself. addPrimaryKey(string array $primaryKey, string $name = \'\'): void Adds a primary key definition. Single column example: $this addPrimaryKey(\'id\'); Composite example: $this addPrimaryKey([\'school id\', \'year\', \'term\']); Optional named constraint: $this addPrimaryKey(\'id\', \'pk posts id\'); addKey(string array $key, string $name = \'\'): void Adds a normal index. $this addKey(\'date created\'); $this addKey(\'user id\', \'idx posts user id\'); $this addKey([\'school id\', \'year\'], \'idx school year\'); addUniqueKey(string array $key, string $name = \'\'): void Adds a unique index. $this addUniqueKey(\'slug\', \'uniq posts slug\'); $this addUniqueKey([\'school id\', \'code\'], \'uniq school code\'); addFullTextKey(string array $key, string $name = \'\'): void Adds a fulltext index. $this addFullTextKey(\'body\'); $this addFullTextKey([\'title\', \'body\'], \'ft posts search\'); Use this when your storage engine and database version support fulltext indexing for the target columns. Table settings You can customize the table engine, charset, and collation before creation. $this addEngine(\'InnoDB\'); $this addCharset(\'utf8mb4\'); $this addCollate(\'utf8mb4 general ci\'); These settings affect the generated CREATE TABLE statement. Complete example public function up() { $this addColumn(\'id int unsigned auto increment\'); $this addColumn(\'user id int unsigned default 0\'); $this addColumn(\'title varchar(255) not null\'); $this addColumn(\'slug varchar(150) not null\'); $this addColumn(\'body text null\'); $this addColumn(\'date created datetime default null\'); $this addPrimaryKey(\'id\'); $this addKey(\'user id\', \'idx posts user id\'); $this addUniqueKey(\'slug\', \'uniq posts slug\'); $this addFullTextKey([\'title\', \'body\'], \'ft posts search\'); $this addEngine(\'InnoDB\'); $this addCharset(\'utf8mb4\'); $this addCollate(\'utf8mb4 general ci\'); $this createTable(\'posts\'); } Important note The builder state is reset after a successful createTable(). That prevents definitions from leaking into the next table build inside the same migration.',
            'order' => 10,
        ],
        [
            'id' => 'database-migrations/migrations-overview/foreign-keys-and-constraints',
