            'search_text' => 'foreign keys and constraints how to define foreign keys during table creation and how to add or remove them on existing tables. database migrations migrations overview  foreign keys during table creation use addforeignkey() before createtable() when building a new table. method signature $this addforeignkey( column: \'user id\', reftable: \'users\', refcolumn: \'id\', ondelete: \'cascade\', onupdate: \'cascade\', name: \'fk posts user id\' ); parameters column is the local column reftable is the referenced table refcolumn is the referenced column, defaulting to id ondelete controls delete behavior onupdate controls update behavior name optionally names the constraint example public function up() { $this addcolumn(\'id int unsigned auto increment\'); $this addcolumn(\'user id int unsigned not null\'); $this addcolumn(\'title varchar(255) not null\'); $this addprimarykey(\'id\'); $this addkey(\'user id\', \'idx posts user id\'); $this addforeignkey( column: \'user id\', reftable: \'users\', refcolumn: \'id\', ondelete: \'cascade\', onupdate: \'cascade\', name: \'fk posts user id\' ); $this createtable(\'posts\'); } adding a foreign key to an existing table use addforeignkeytotable() when the table already exists. $this addforeignkeytotable( \'posts\', \'user id\', \'users\', \'id\', \'cascade\', \'cascade\', \'fk posts user id\' ); dropping a foreign key use dropforeignkey() with the constraint name: $this dropforeignkey(\'posts\', \'fk posts user id\'); best practices ensure the referenced table exists first ensure the column types match add an index on the foreign key column where appropriate prefer explicit constraint names in production projects practical rollback recipe public function up() { $this addforeignkeytotable( \'invoices\', \'user id\', \'users\', \'id\', \'cascade\', \'cascade\', \'fk invoices user id\' ); } public function down() { $this dropforeignkey(\'invoices\', \'fk invoices user id\'); }',
            'plain_text' => 'Foreign keys during table creation Use addForeignKey() before createTable() when building a new table. Method signature $this addForeignKey( column: \'user id\', refTable: \'users\', refColumn: \'id\', onDelete: \'CASCADE\', onUpdate: \'CASCADE\', name: \'fk posts user id\' ); Parameters column is the local column refTable is the referenced table refColumn is the referenced column, defaulting to id onDelete controls delete behavior onUpdate controls update behavior name optionally names the constraint Example public function up() { $this addColumn(\'id int unsigned auto increment\'); $this addColumn(\'user id int unsigned not null\'); $this addColumn(\'title varchar(255) not null\'); $this addPrimaryKey(\'id\'); $this addKey(\'user id\', \'idx posts user id\'); $this addForeignKey( column: \'user id\', refTable: \'users\', refColumn: \'id\', onDelete: \'CASCADE\', onUpdate: \'CASCADE\', name: \'fk posts user id\' ); $this createTable(\'posts\'); } Adding a foreign key to an existing table Use addForeignKeyToTable() when the table already exists. $this addForeignKeyToTable( \'posts\', \'user id\', \'users\', \'id\', \'CASCADE\', \'CASCADE\', \'fk posts user id\' ); Dropping a foreign key Use dropForeignKey() with the constraint name: $this dropForeignKey(\'posts\', \'fk posts user id\'); Best practices ensure the referenced table exists first ensure the column types match add an index on the foreign key column where appropriate prefer explicit constraint names in production projects Practical rollback recipe public function up() { $this addForeignKeyToTable( \'invoices\', \'user id\', \'users\', \'id\', \'CASCADE\', \'CASCADE\', \'fk invoices user id\' ); } public function down() { $this dropForeignKey(\'invoices\', \'fk invoices user id\'); }',
            'order' => 11,
        ],
