            'search_text' => 'altering existing tables reference for schema changes on existing tables, including adding, modifying, renaming, and dropping columns and indexes. database migrations migrations overview  overview thunder migrations are not limited to creating new tables. the base migration class also includes helper methods for altering existing tables. addcolumntotable(string $table, string $columnsql): bool adds a new column to an existing table. $this addcolumntotable(\'users\', \'phone varchar(30) null\'); modifycolumn(string $table, string $columnsql): bool changes the definition of an existing column. $this modifycolumn(\'users\', \'phone varchar(50) null\'); use this when adjusting length, nullability, defaults, or data type. renamecolumn(string $table, string $oldname, string $newname, string $newdefinition): bool renames a column and defines its new structure at the same time. $this renamecolumn( \'users\', \'fullname\', \'display name\', \'display name varchar(255) not null\' ); dropcolumn(string $table, string $column): bool removes a column from an existing table. $this dropcolumn(\'users\', \'phone\'); addindextotable(string $table, string array $columns, string $name = \'\'): bool adds a regular index to an existing table. $this addindextotable(\'users\', \'email\', \'idx users email\'); $this addindextotable(\'results\', [\'school id\', \'year\'], \'idx results school year\'); adduniqueindextotable(string $table, string array $columns, string $name = \'\'): bool adds a unique index to an existing table. $this adduniqueindextotable(\'users\', \'email\', \'uniq users email\'); dropindex(string $table, string $name): bool drops an existing index by name. $this dropindex(\'users\', \'idx users email\'); practical example public function up() { $this addcolumntotable(\'posts\', \'status varchar(50) default "draft"\'); $this addindextotable(\'posts\', \'status\', \'idx posts status\'); } public function down() { $this dropindex(\'posts\', \'idx posts status\'); $this dropcolumn(\'posts\', \'status\'); } best practice when altering existing tables: add indexes after the target columns exist drop indexes before dropping their columns in rollbacks keep up() and down() symmetrical whenever possible',
            'plain_text' => 'Overview Thunder migrations are not limited to creating new tables. The base Migration class also includes helper methods for altering existing tables. addColumnToTable(string $table, string $columnSql): bool Adds a new column to an existing table. $this addColumnToTable(\'users\', \'phone varchar(30) null\'); modifyColumn(string $table, string $columnSql): bool Changes the definition of an existing column. $this modifyColumn(\'users\', \'phone varchar(50) null\'); Use this when adjusting length, nullability, defaults, or data type. renameColumn(string $table, string $oldName, string $newName, string $newDefinition): bool Renames a column and defines its new structure at the same time. $this renameColumn( \'users\', \'fullname\', \'display name\', \'display name varchar(255) not null\' ); dropColumn(string $table, string $column): bool Removes a column from an existing table. $this dropColumn(\'users\', \'phone\'); addIndexToTable(string $table, string array $columns, string $name = \'\'): bool Adds a regular index to an existing table. $this addIndexToTable(\'users\', \'email\', \'idx users email\'); $this addIndexToTable(\'results\', [\'school id\', \'year\'], \'idx results school year\'); addUniqueIndexToTable(string $table, string array $columns, string $name = \'\'): bool Adds a unique index to an existing table. $this addUniqueIndexToTable(\'users\', \'email\', \'uniq users email\'); dropIndex(string $table, string $name): bool Drops an existing index by name. $this dropIndex(\'users\', \'idx users email\'); Practical example public function up() { $this addColumnToTable(\'posts\', \'status varchar(50) default "draft"\'); $this addIndexToTable(\'posts\', \'status\', \'idx posts status\'); } public function down() { $this dropIndex(\'posts\', \'idx posts status\'); $this dropColumn(\'posts\', \'status\'); } Best practice When altering existing tables: add indexes after the target columns exist drop indexes before dropping their columns in rollbacks keep up() and down() symmetrical whenever possible',
            'order' => 12,
        ],
        [
            'id' => 'database-migrations/migrations-overview/seeding-data-in-migrations',
            'title' => 'Seeding Data in Migrations',
            'description' => 'How to queue and insert seed data using addData and insert within Thunder migrations.',
            'topic' => 'Database Migrations',
            'topic_slug' => 'database-migrations',
