                'rows',
                'internally',
                'best',
                'cases',
                'caution',
                'rollback',
                'note',
            ],
            'search_text' => 'seeding data in migrations how to queue and insert seed data using adddata and insert within thunder migrations. database migrations migrations overview  overview thunder migrations can also insert seed data. this is useful for default records such as: admin accounts default settings permission rows fixed lookup data methods used adddata(array $data): void insert(string $table): bool how it works you call adddata() once for each row you want to queue, then call insert() to write them to the table. example public function up() { $this addcolumn(\'id int unsigned auto increment\'); $this addcolumn(\'name varchar(255) not null\'); $this addcolumn(\'email varchar(255) not null\'); $this addprimarykey(\'id\'); $this createtable(\'admins\'); $this adddata([ \'name\' = \'main admin\', \'email\' = \'admin@example.com\', ]); $this insert(\'admins\'); } multiple rows $this adddata([ \'name\' = \'admin\', \'email\' = \'admin@example.com\', ]); $this adddata([ \'name\' = \'editor\', \'email\' = \'editor@example.com\', ]); $this insert(\'admins\'); how insert works internally for each queued row, thunder: 1. extracts the column names 2. builds a parameterized insert into query 3. binds the row values 4. executes the insert this makes seed inserts cleaner than writing raw sql manually each time. best use cases use migration seeding for data that must exist for the plugin to function correctly, such as: a seeded admin role default plugin settings required permission definitions caution avoid using migrations for large bulk imports. migrations are best for schema changes and small essential seed data, not for massive content loading. rollback note if you seed data in up(), think about whether down() should also delete it. in many simple cases, dropping the table is enough. but when adding data to existing tables, consider how to remove it safely in the rollback.',
            'plain_text' => 'Overview Thunder migrations can also insert seed data. This is useful for default records such as: admin accounts default settings permission rows fixed lookup data Methods used addData(array $data): void insert(string $table): bool How it works You call addData() once for each row you want to queue, then call insert() to write them to the table. Example public function up() { $this addColumn(\'id int unsigned auto increment\'); $this addColumn(\'name varchar(255) not null\'); $this addColumn(\'email varchar(255) not null\'); $this addPrimaryKey(\'id\'); $this createTable(\'admins\'); $this addData([ \'name\' = \'Main Admin\', \'email\' = \'admin@example.com\', ]); $this insert(\'admins\'); } Multiple rows $this addData([ \'name\' = \'Admin\', \'email\' = \'admin@example.com\', ]); $this addData([ \'name\' = \'Editor\', \'email\' = \'editor@example.com\', ]); $this insert(\'admins\'); How insert works internally For each queued row, Thunder: 1. extracts the column names 2. builds a parameterized INSERT INTO query 3. binds the row values 4. executes the insert This makes seed inserts cleaner than writing raw SQL manually each time. Best use cases Use migration seeding for data that must exist for the plugin to function correctly, such as: a seeded admin role default plugin settings required permission definitions Caution Avoid using migrations for large bulk imports. Migrations are best for schema changes and small essential seed data, not for massive content loading. Rollback note If you seed data in up(), think about whether down() should also delete it. In many simple cases, dropping the table is enough. But when adding data to existing tables, consider how to remove it safely in the rollback.',
            'order' => 13,
        ],
        [
            'id' => 'database-migrations/migrations-overview/batch-tracking-and-rollbacks',
            'title' => 'Batch Tracking and Rollbacks',
            'description' => 'Detailed explanation of migration batches, rollback behavior, refresh behavior, and status reporting.',
            'topic' => 'Database Migrations',
            'topic_slug' => 'database-migrations',
            'subtopic' => 'Migrations Overview',
