                'example',
                'best',
                'practice',
            ],
            'search_text' => 'batch tracking and rollbacks detailed explanation of migration batches, rollback behavior, refresh behavior, and status reporting. database migrations migrations overview  overview thunder tracks migrations in batches. a batch represents one migration run operation. this makes rollback behavior predictable. what is a batch whenever thunder runs pending migrations in up mode, it asks the migration tracker for the next batch number. every migration that runs during that command is recorded under that same batch. example: php thunder migrate blog if the next batch is 3, all migrations executed in that command are logged with batch 3. why batches matter rollback is batch based. when you run: php thunder migrate:rollback blog thunder does not roll back every migration ever run. it rolls back only the latest batch for that plugin. for all, it rolls back the latest global batch returned by the tracker. rollback order during rollback, thunder reverses file order using descending sorting. this is important because schema teardown usually needs the most recent changes undone first. refresh behavior migrate:refresh is implemented as: 1. rollback 2. migrate so it destroys the latest batch and immediately rebuilds it. php thunder migrate:refresh blog this is especially useful during plugin development. status reporting migrate:status compares migration files on disk with records in the migration tracker table. it then prints either: [ran] [pending] for ran migrations, thunder shows metadata such as: batch number run timestamp practical example suppose the blog plugin has these migration files: 2026 04 21 100000 create posts table.php 2026 04 21 101000 add status to posts.php 2026 04 21 102000 create comments table.php if you run: php thunder migrate blog all three may be logged in the same batch, for example batch 5. running: php thunder migrate:rollback blog will attempt to roll back those migrations in reverse order. best practice treat each migration run as a logical unit. if you add several related migration files and run them together, they will typically belong to one rollback batch.',
            'plain_text' => 'Overview Thunder tracks migrations in batches. A batch represents one migration run operation. This makes rollback behavior predictable. What is a batch Whenever Thunder runs pending migrations in up mode, it asks the migration tracker for the next batch number. Every migration that runs during that command is recorded under that same batch. Example: php thunder migrate blog If the next batch is 3, all migrations executed in that command are logged with batch 3. Why batches matter Rollback is batch based. When you run: php thunder migrate:rollback blog Thunder does not roll back every migration ever run. It rolls back only the latest batch for that plugin. For all, it rolls back the latest global batch returned by the tracker. Rollback order During rollback, Thunder reverses file order using descending sorting. This is important because schema teardown usually needs the most recent changes undone first. Refresh behavior migrate:refresh is implemented as: 1. rollback 2. migrate So it destroys the latest batch and immediately rebuilds it. php thunder migrate:refresh blog This is especially useful during plugin development. Status reporting migrate:status compares migration files on disk with records in the migration tracker table. It then prints either: [RAN] [PENDING] For ran migrations, Thunder shows metadata such as: batch number run timestamp Practical example Suppose the blog plugin has these migration files: 2026 04 21 100000 create posts table.php 2026 04 21 101000 add status to posts.php 2026 04 21 102000 create comments table.php If you run: php thunder migrate blog all three may be logged in the same batch, for example batch 5. Running: php thunder migrate:rollback blog will attempt to roll back those migrations in reverse order. Best practice Treat each migration run as a logical unit. If you add several related migration files and run them together, they will typically belong to one rollback batch.',
            'order' => 14,
        ],
        [
            'id' => 'database-migrations/migrations-overview/migrationtracker-class',
            'title' => 'MigrationTracker Class',
            'description' => 'Reference for the migration tracker table and the methods that record, query, and remove migration runs.',
            'topic' => 'Database Migrations',
