            ],
            'search_text' => 'migrationtracker class reference for the migration tracker table and the methods that record, query, and remove migration runs. database migrations migrations overview  overview thunder uses a dedicated migrationtracker class to record which migrations have already run. this class extends thunder\\database and stores migration history in the thunder migrations table. tracked fields the tracker table includes: id plugin id migration name batch checksum ran at it also defines a unique key across: (plugin id, migration name) this means the same migration file name cannot be recorded twice for the same plugin. ensuretable(): void creates the tracker table if it does not already exist. thunder calls this before migration operations so the tracker is always available. hasrun(string $pluginid, string $migrationname): bool checks whether a migration has already been executed for a given plugin. thunder uses this to skip already ran migrations during migrate. logrun(string $pluginid, string $migrationname, int $batch, string $checksum = \'\'): bool stores a completed migration run in the tracker. this happens after a successful up() call. removerun(string $pluginid, string $migrationname): bool deletes the migration record after a successful rollback. this happens after a successful down() call. getnextbatch(): int returns the next available batch number by reading the current maximum batch and adding 1. getlastbatchmigrations(?string $pluginid = null): array returns migrations from the latest batch, either: for one plugin, or globally when no plugin is provided this is the core method used to decide what gets rolled back. allruns(?string $pluginid = null): array returns all tracked migration runs, optionally filtered by plugin. this powers migrate:status. why the tracker matters without the tracker, thunder would have no reliable way to know: which migrations are pending which migrations are already applied which migrations belong to the latest rollback batch',
            'plain_text' => 'Overview Thunder uses a dedicated MigrationTracker class to record which migrations have already run. This class extends Thunder\\Database and stores migration history in the thunder migrations table. Tracked fields The tracker table includes: id plugin id migration name batch checksum ran at It also defines a unique key across: (plugin id, migration name) This means the same migration file name cannot be recorded twice for the same plugin. ensureTable(): void Creates the tracker table if it does not already exist. Thunder calls this before migration operations so the tracker is always available. hasRun(string $pluginId, string $migrationName): bool Checks whether a migration has already been executed for a given plugin. Thunder uses this to skip already ran migrations during migrate. logRun(string $pluginId, string $migrationName, int $batch, string $checksum = \'\'): bool Stores a completed migration run in the tracker. This happens after a successful up() call. removeRun(string $pluginId, string $migrationName): bool Deletes the migration record after a successful rollback. This happens after a successful down() call. getNextBatch(): int Returns the next available batch number by reading the current maximum batch and adding 1. getLastBatchMigrations(?string $pluginId = null): array Returns migrations from the latest batch, either: for one plugin, or globally when no plugin is provided This is the core method used to decide what gets rolled back. allRuns(?string $pluginId = null): array Returns all tracked migration runs, optionally filtered by plugin. This powers migrate:status. Why the tracker matters Without the tracker, Thunder would have no reliable way to know: which migrations are pending which migrations are already applied which migrations belong to the latest rollback batch',
            'order' => 15,
        ],
        [
            'id' => 'database-migrations/migrations-overview/checksums-pending-detection-and-status',
            'title' => 'Checksums, Pending Detection, and Status',
            'description' => 'How Thunder detects pending migrations, uses checksums, and compares disk files against tracker records.',
            'topic' => 'Database Migrations',
            'topic_slug' => 'database-migrations',
            'subtopic' => 'Migrations Overview',
            'subtopic_slug' => 'migrations-overview',
            'section_slug' => 'checksums-pending-detection-and-status',
            'url' => 'docs/database-migrations/migrations-overview/checksums-pending-detection-and-status',
            'path' => 'database-migrations/migrations-overview/016-checksums-pending-detection-and-status.md',
            'headings' => [
            ],
            'keywords' => [
                'checksums',
                'pending',
                'detection',
                'status',
                'thunder',
                'detects',
                'migrations',
                'uses',
                'compares',
                'disk',
                'files',
                'against',
                'tracker',
                'records',
                'database',
                'overview',
                'already-ran',
                'checksum',
                'useful',
                'reporting',
                'behavior',
                'practical',
                'interpretation',
                'best',
            ],
            'search_text' => 'checksums, pending detection, and status how thunder detects pending migrations, uses checksums, and compares disk files against tracker records. database migrations migrations overview  pending detection thunder determines whether a migration is pending by comparing the migration files on disk against the migration tracker records. if a migration file exists in the plugin\'s migrations/ folder but no matching tracker record exists for that plugin and file name, the migration is treated as pending. already ran detection before running a migration in up mode, thunder checks: $tracker hasrun($pluginid, $migrationname) if the migration is already tracked, thunder skips it. this prevents accidental duplicate execution. checksums when thunder logs a migration run, it stores a sha 256 checksum of the migration file: hash file(\'sha256\', $file) this gives each migration record a fingerprint of the file contents at the time it ran. what the checksum is useful for in the current implementation, the checksum is stored but not actively enforced during migration or status checks. even so, it is valuable because it lays the groundwork for future features such as: detecting edited migration files after execution warning when a previously ran migration has changed auditing migration history more reliably status reporting behavior migrate:status scans the migration folder, sorts all .php files, and compares them with tracked runs. for each file, it prints either: [ran] [pending] for ran files, thunder also prints the batch number and run timestamp. practical interpretation if a file appears as [pending], one of these is usually true: it has never been run its tracker row was removed during rollback the tracker table was reset or lost the plugin id or file name changed best practice do not edit old migration files after they have run in shared environments. instead, create a new migration file for the next change. that keeps your migration history stable and your checksum records meaningful.',
            'plain_text' => 'Pending detection Thunder determines whether a migration is pending by comparing the migration files on disk against the migration tracker records. If a migration file exists in the plugin\'s migrations/ folder but no matching tracker record exists for that plugin and file name, the migration is treated as pending. Already ran detection Before running a migration in up mode, Thunder checks: $tracker hasRun($pluginId, $migrationName) If the migration is already tracked, Thunder skips it. This prevents accidental duplicate execution. Checksums When Thunder logs a migration run, it stores a SHA 256 checksum of the migration file: hash file(\'sha256\', $file) This gives each migration record a fingerprint of the file contents at the time it ran. What the checksum is useful for In the current implementation, the checksum is stored but not actively enforced during migration or status checks. Even so, it is valuable because it lays the groundwork for future features such as: detecting edited migration files after execution warning when a previously ran migration has changed auditing migration history more reliably Status reporting behavior migrate:status scans the migration folder, sorts all .php files, and compares them with tracked runs. For each file, it prints either: [RAN] [PENDING] For ran files, Thunder also prints the batch number and run timestamp. Practical interpretation If a file appears as [PENDING], one of these is usually true: it has never been run its tracker row was removed during rollback the tracker table was reset or lost the plugin id or file name changed Best practice Do not edit old migration files after they have run in shared environments. Instead, create a new migration file for the next change. That keeps your migration history stable and your checksum records meaningful.',
            'order' => 16,
        ],
