            'search_text' => 'practical recipes real-world migration recipes for creating tables, adding indexes, adding foreign keys, and evolving schema safely. database migrations migrations overview  recipe 1: create a standard content table namespace migration; class create posts table extends migration { public function up() { $this addcolumn(\'id int unsigned auto increment\'); $this addcolumn(\'user id int unsigned not null\'); $this addcolumn(\'title varchar(255) not null\'); $this addcolumn(\'slug varchar(150) not null\'); $this addcolumn(\'body text null\'); $this addcolumn(\'deleted tinyint(1) unsigned default 0\'); $this addcolumn(\'date created datetime default null\'); $this addcolumn(\'date updated datetime default null\'); $this addprimarykey(\'id\'); $this addkey(\'user id\', \'idx posts user id\'); $this adduniquekey(\'slug\', \'uniq posts slug\'); $this addforeignkey( column: \'user id\', reftable: \'users\', refcolumn: \'id\', ondelete: \'cascade\', onupdate: \'cascade\', name: \'fk posts user id\' ); $this createtable(\'posts\'); } public function down() { $this droptable(\'posts\'); } } recipe 2: add a column to an existing table public function up() { $this addcolumntotable(\'posts\', \'status varchar(50) default "draft"\'); $this addindextotable(\'posts\', \'status\', \'idx posts status\'); } public function down() { $this dropindex(\'posts\', \'idx posts status\'); $this dropcolumn(\'posts\', \'status\'); } recipe 3: seed a default admin record public function up() { $this addcolumn(\'id int unsigned auto increment\'); $this addcolumn(\'username varchar(100) not null\'); $this addcolumn(\'email varchar(255) not null\'); $this addprimarykey(\'id\'); $this createtable(\'admins\'); $this adddata([ \'username\' = \'admin\', \'email\' = \'admin@example.com\', ]); $this insert(\'admins\'); } public function down() { $this droptable(\'admins\'); } recipe 4: rename and redefine a column public function up() { $this renamecolumn( \'users\', \'fullname\', \'display name\', \'display name varchar(255) not null\' ); } public function down() { $this renamecolumn( \'users\', \'display name\', \'fullname\', \'fullname varchar(255) not null\' ); } recipe 5: development refresh loop // create the migration php thunder make:migration blog create posts table // run it php thunder migrate blog // adjust migration during early development only // then rebuild latest batch php thunder migrate:refresh blog use refresh only when you understand that it rolls back the latest batch and runs it again.',
            'plain_text' => 'Recipe 1: Create a standard content table namespace Migration; class Create posts table extends Migration { public function up() { $this addColumn(\'id int unsigned auto increment\'); $this addColumn(\'user id int unsigned not null\'); $this addColumn(\'title varchar(255) not null\'); $this addColumn(\'slug varchar(150) not null\'); $this addColumn(\'body text null\'); $this addColumn(\'deleted tinyint(1) unsigned default 0\'); $this addColumn(\'date created datetime default null\'); $this addColumn(\'date updated datetime default null\'); $this addPrimaryKey(\'id\'); $this addKey(\'user id\', \'idx posts user id\'); $this addUniqueKey(\'slug\', \'uniq posts slug\'); $this addForeignKey( column: \'user id\', refTable: \'users\', refColumn: \'id\', onDelete: \'CASCADE\', onUpdate: \'CASCADE\', name: \'fk posts user id\' ); $this createTable(\'posts\'); } public function down() { $this dropTable(\'posts\'); } } Recipe 2: Add a column to an existing table public function up() { $this addColumnToTable(\'posts\', \'status varchar(50) default "draft"\'); $this addIndexToTable(\'posts\', \'status\', \'idx posts status\'); } public function down() { $this dropIndex(\'posts\', \'idx posts status\'); $this dropColumn(\'posts\', \'status\'); } Recipe 3: Seed a default admin record public function up() { $this addColumn(\'id int unsigned auto increment\'); $this addColumn(\'username varchar(100) not null\'); $this addColumn(\'email varchar(255) not null\'); $this addPrimaryKey(\'id\'); $this createTable(\'admins\'); $this addData([ \'username\' = \'admin\', \'email\' = \'admin@example.com\', ]); $this insert(\'admins\'); } public function down() { $this dropTable(\'admins\'); } Recipe 4: Rename and redefine a column public function up() { $this renameColumn( \'users\', \'fullname\', \'display name\', \'display name varchar(255) not null\' ); } public function down() { $this renameColumn( \'users\', \'display name\', \'fullname\', \'fullname varchar(255) not null\' ); } Recipe 5: Development refresh loop // Create the migration php thunder make:migration blog create posts table // Run it php thunder migrate blog // Adjust migration during early development only // Then rebuild latest batch php thunder migrate:refresh blog Use refresh only when you understand that it rolls back the latest batch and runs it again.',
            'order' => 17,
        ],
        [
            'id' => 'database-migrations/migrations-overview/best-practices-and-caveats',
            'title' => 'Best Practices and Caveats',
            'description' => 'Recommended usage patterns, naming conventions, safety guidance, and caveats specific to the current Thunder migration implementation.',
            'topic' => 'Database Migrations',
            'topic_slug' => 'database-migrations',
            'subtopic' => 'Migrations Overview',
            'subtopic_slug' => 'migrations-overview',
            'section_slug' => 'best-practices-and-caveats',
            'url' => 'docs/database-migrations/migrations-overview/best-practices-and-caveats',
            'path' => 'database-migrations/migrations-overview/018-best-practices-and-caveats.md',
            'headings' => [
            ],
            'keywords' => [
                'best',
                'practices',
                'caveats',
                'recommended',
                'usage',
                'patterns',
                'naming',
                'conventions',
                'safety',
                'guidance',
                'specific',
                'current',
                'thunder',
                'migration',
                'implementation',
                'database',
                'migrations',
                'overview',
                'clear',
                'names',
                'prefer',
                'new',
                'over',
                'editing',
            ],
            'search_text' => 'best practices and caveats recommended usage patterns, naming conventions, safety guidance, and caveats specific to the current thunder migration implementation. database migrations migrations overview  use clear migration names choose file names that describe the schema action clearly: create users table add status to orders create school fees table add foreign key to results this makes status output and migration history far easier to read. prefer new migrations over editing old ones once a migration has run in a shared environment, avoid editing it. create a new migration for the next change instead. that keeps migration history stable and avoids confusion around tracker checksums. keep up() and down() symmetrical a good rollback depends on down() truly reversing up(). examples: if up() adds an index, down() should drop it if up() adds a column, down() should remove it if up() adds a foreign key, down() should drop that foreign key be careful with destructive changes dropping columns or tables can destroy data permanently. even though thunder makes this easy, production usage should still follow safe database practices such as: backups before schema changes testing migrations on staging first reviewing rollback consequences carefully remember that addcolumn uses raw sql fragments methods like addcolumn() are flexible because they accept raw sql, but they also rely on you to write correct sql syntax. thunder does not abstract every sql detail for you. understand batch based rollback migrate:rollback does not mean "undo everything." it means "undo the latest tracked batch." plan your migration runs with that in mind. tracker table is part of the system do not casually delete rows from thunder migrations unless you understand the consequences. that table controls: pending detection rollback scope migration history use explicit names for important indexes and constraints thunder can generate some names automatically for altered table indexes and foreign keys, but explicit names are easier to maintain, debug, and drop later. development vs production mindset during development, migrate:refresh is convenient. in production, prefer disciplined forward only migrations unless rollback is genuinely required and thoroughly tested.',
            'plain_text' => 'Use clear migration names Choose file names that describe the schema action clearly: create users table add status to orders create school fees table add foreign key to results This makes status output and migration history far easier to read. Prefer new migrations over editing old ones Once a migration has run in a shared environment, avoid editing it. Create a new migration for the next change instead. That keeps migration history stable and avoids confusion around tracker checksums. Keep up() and down() symmetrical A good rollback depends on down() truly reversing up(). Examples: if up() adds an index, down() should drop it if up() adds a column, down() should remove it if up() adds a foreign key, down() should drop that foreign key Be careful with destructive changes Dropping columns or tables can destroy data permanently. Even though Thunder makes this easy, production usage should still follow safe database practices such as: backups before schema changes testing migrations on staging first reviewing rollback consequences carefully Remember that addColumn uses raw SQL fragments Methods like addColumn() are flexible because they accept raw SQL, but they also rely on you to write correct SQL syntax. Thunder does not abstract every SQL detail for you. Understand batch based rollback migrate:rollback does not mean "undo everything." It means "undo the latest tracked batch." Plan your migration runs with that in mind. Tracker table is part of the system Do not casually delete rows from thunder migrations unless you understand the consequences. That table controls: pending detection rollback scope migration history Use explicit names for important indexes and constraints Thunder can generate some names automatically for altered table indexes and foreign keys, but explicit names are easier to maintain, debug, and drop later. Development vs production mindset During development, migrate:refresh is convenient. In production, prefer disciplined forward only migrations unless rollback is genuinely required and thoroughly tested.',
            'order' => 18,
        ],
