            ],
            'search_text' => 'thunderphp functions reference overview of the public helper functions available to plugins and how they fit into the thunderphp plugin lifecycle. functions thunderphp functions list  purpose this reference documents the public helper functions exposed by thunderphp for plugin development. it is based on the provided functions.php file and the plugin architecture notes. these helpers mainly cover: url and path handling plugin context and shared state hooks and routing roles and permissions forms and csrf messages, dates, images, and debugging how to read this reference use these functions inside your plugin files, views, controllers, and hook callbacks. functions that depend on plugin context such as plugin id(), plugin path(), current look(), and set value() are aware of the current plugin. functions like app() operate at application scope and are shared between plugins. common expectations plugin metadata comes from config.json. the currently executing plugin is tracked through the app context. route names come from config.json route definitions. hook callbacks are usually registered in plugin.php. quick example set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', ]); add action(\'controller\', function() { if(page() == \'admin\' && user can(\'edit posts\')) { // controller logic } });',
            'plain_text' => 'Purpose This reference documents the public helper functions exposed by ThunderPHP for plugin development. It is based on the provided functions.php file and the plugin architecture notes. These helpers mainly cover: URL and path handling plugin context and shared state hooks and routing roles and permissions forms and CSRF messages, dates, images, and debugging How to read this reference Use these functions inside your plugin files, views, controllers, and hook callbacks. Functions that depend on plugin context such as plugin id(), plugin path(), current look(), and set value() are aware of the current plugin. Functions like APP() operate at application scope and are shared between plugins. Common expectations Plugin metadata comes from config.json. The currently executing plugin is tracked through the app context. Route names come from config.json route definitions. Hook callbacks are usually registered in plugin.php. Quick example set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', ]); add action(\'controller\', function() { if(page() == \'admin\' && user can(\'edit posts\')) { // controller logic } });',
            'order' => 1,
