            ],
            'search_text' => 'url and http helpers functions for reading the current url, generating internal links, and working with url segments. functions thunderphp functions list  functions covered current url() base url() split url() url() page() redirect() current url() returns the full current url, including protocol, host, path, and query string. $link = current url(); useful for refresh links, return urls, or debugging. base url(string $path = \'\') prepends the application root url to a relative path. echo base url(\'admin/users\'); echo base url(\'assets/images/logo.png\'); split url(string $url) splits a url string into path segments. $parts = split url(\'/blog/post/hello world\'); // [\'blog\', \'post\', \'hello world\'] this is mostly a low level helper and is usually more useful internally than in plugin code. url(string $key = \'\') returns url segments prepared by the framework. echo url(0); // first segment echo url(1); // second segment if no key is supplied, it returns the full url segment array. $segments = url(); page() shortcut for url(0). if(page() == \'admin\') { // admin area } redirect(string $url) redirects to an internal path under root. redirect(\'admin/posts\'); because it sends a location header and stops execution, call it before any output is sent. recipe: redirect back to a plugin page $vars = get value(); redirect($vars[\'admin route\'] . \'/\' . $vars[\'plugin route\']);',
            'plain_text' => 'Functions covered current url() base url() split url() URL() page() redirect() current url() Returns the full current URL, including protocol, host, path, and query string. $link = current url(); Useful for refresh links, return URLs, or debugging. base url(string $path = \'\') Prepends the application root URL to a relative path. echo base url(\'admin/users\'); echo base url(\'assets/images/logo.png\'); split url(string $url) Splits a URL string into path segments. $parts = split url(\'/blog/post/hello world\'); // [\'blog\', \'post\', \'hello world\'] This is mostly a low level helper and is usually more useful internally than in plugin code. URL(string $key = \'\') Returns URL segments prepared by the framework. echo URL(0); // first segment echo URL(1); // second segment If no key is supplied, it returns the full URL segment array. $segments = URL(); page() Shortcut for URL(0). if(page() == \'admin\') { // admin area } redirect(string $url) Redirects to an internal path under ROOT. redirect(\'admin/posts\'); Because it sends a Location header and stops execution, call it before any output is sent. Recipe: redirect back to a plugin page $vars = get value(); redirect($vars[\'admin route\'] . \'/\' . $vars[\'plugin route\']);',
            'order' => 2,
        ],
        [
            'id' => 'functions/thunderphp-functions-list/plugin-context-and-request-scoped-state',
            'title' => 'Plugin Context and Request-Scoped State',
            'description' => 'Helpers for reading the current plugin context and passing data around during the current request.',
            'topic' => 'Functions',
