                'key',
                'mixed',
                'value',
                'important',
                'behavior',
            ],
            'search_text' => 'plugin context and request-scoped state helpers for reading the current plugin context and passing data around during the current request. functions thunderphp functions list  functions covered set value() get value() plugin id() get context() set value(string array $key, mixed $value = \'\') stores data in a plugin isolated request scoped store. this behaves like a plugin local global variable for the current page load. set value(\'title\', \'blog posts\'); set value(\'admin route\', \'admin\'); you can also set many values at once. set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', \'tables\' = [ \'posts\' = \'bb posts\', \'tags\' = \'bb tags\', ], ]); important behavior values are isolated per plugin. that prevents one plugin from overwriting another plugin\'s temporary values. get value(string $key = \'\') retrieves values previously stored with set value(). echo get value(\'title\'); if called with no key, it returns all values for the current plugin. $vars = get value(); plugin id() returns the current plugin id from its config.json. echo plugin id(); this is useful when building dynamic hook names. $hook = plugin id() . \' main content\'; get context() returns the full current plugin context object. $ctx = get context(); echo $ctx id ?? \'\'; echo $ctx look ?? \'main\'; echo $ctx path ?? \'\'; typical values in context include plugin id, filesystem path, http path, and selected look. recipe: initialize plugin runtime values set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', \'posts table\' = \'bb posts\', ]); recipe: use context to inspect the active look $ctx = get context(); $look = $ctx look ?? \'main\';',
            'plain_text' => 'Functions covered set value() get value() plugin id() get context() set value(string array $key, mixed $value = \'\') Stores data in a plugin isolated request scoped store. This behaves like a plugin local global variable for the current page load. set value(\'title\', \'Blog Posts\'); set value(\'admin route\', \'admin\'); You can also set many values at once. set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', \'tables\' = [ \'posts\' = \'bb posts\', \'tags\' = \'bb tags\', ], ]); Important behavior Values are isolated per plugin. That prevents one plugin from overwriting another plugin\'s temporary values. get value(string $key = \'\') Retrieves values previously stored with set value(). echo get value(\'title\'); If called with no key, it returns all values for the current plugin. $vars = get value(); plugin id() Returns the current plugin id from its config.json. echo plugin id(); This is useful when building dynamic hook names. $hook = plugin id() . \' main content\'; get context() Returns the full current plugin context object. $ctx = get context(); echo $ctx id ?? \'\'; echo $ctx look ?? \'main\'; echo $ctx path ?? \'\'; Typical values in context include plugin id, filesystem path, HTTP path, and selected look. Recipe: initialize plugin runtime values set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', \'posts table\' = \'bb posts\', ]); Recipe: use context to inspect the active look $ctx = get context(); $look = $ctx look ?? \'main\';',
            'order' => 3,
        ],
        [
            'id' => 'functions/thunderphp-functions-list/application-wide-state-with-app-and-app-set',
            'title' => 'Application-Wide State with APP and APP_SET',
            'description' => 'How to read shared application data using `APP()` and a proposed complementary setter for writing to the shared `$APP` store.',
            'topic' => 'Functions',
            'topic_slug' => 'functions',
            'subtopic' => 'ThunderPHP Functions List',
            'subtopic_slug' => 'thunderphp-functions-list',
            'section_slug' => 'application-wide-state-with-app-and-app-set',
            'url' => 'docs/functions/thunderphp-functions-list/application-wide-state-with-app-and-app-set',
            'path' => 'functions/thunderphp-functions-list/004-application-wide-state-with-app-and-app-set.md',
            'headings' => [
            ],
            'keywords' => [
                'application-wide',
                'state',
                'app',
                'app_set',
                'read',
                'shared',
                'application',
                'data',
                'proposed',
                'complementary',
                'setter',
                'writing',
                'store',
                'functions',
                'thunderphp',
                'list',
                'covered',
                'string',
                'key',
                'companion',
                'writer',
                'copy-paste',
                'implementation',
                'examples',
            ],
            'search_text' => 'application-wide state with app and app_set how to read shared application data using `app()` and a proposed complementary setter for writing to the shared `$app` store. functions thunderphp functions list  functions covered app() proposed app set() app(string $key = \'\') reads application level values from the shared $app store. unlike set value() and get value(), this data is not isolated per plugin. $all = app(); $plugins = app(\'plugins\'); $url = app(\'url\'); this is useful for framework level shared state such as loaded plugins, url segments, matched routes, and app context. when to use app() use app() when you need shared framework state that is intentionally global across plugins. use set value() and get value() when the data is temporary and should be isolated to the current plugin. proposed companion writer: app set() a natural opposite of app() is a helper that writes to the shared $app variable. this is useful when you want a small, consistent helper instead of writing to the global directly. copy paste implementation function app set(string array $key, mixed $value = \'\'): bool { global $app; if(is array($key)) { foreach($key as $k = $v) { $app[$k] = $v; } return true; } $app[$key] = $value; return true; } examples app set(\'route handled\', true); app set([ \'custom debug\' = true, \'feature x\' = \'enabled\', ]); suggested usage notes use this sparingly because it writes into global shared application state. prefer plugin isolated set value() for plugin local runtime data. prefer app set() only for true application level flags or values that are meant to be shared across plugins. optional nested key version if you want dot notation like app set(\'config.debug\', true), that should be implemented as a separate helper rather than changing the basic version. recipe: mark a request wide flag app set(\'my custom flag\', true); if(app(\'my custom flag\')) { // do something once per request }',
            'plain_text' => 'Functions covered APP() proposed APP SET() APP(string $key = \'\') Reads application level values from the shared $APP store. Unlike set value() and get value(), this data is not isolated per plugin. $all = APP(); $plugins = APP(\'plugins\'); $url = APP(\'URL\'); This is useful for framework level shared state such as loaded plugins, URL segments, matched routes, and app context. When to use APP() Use APP() when you need shared framework state that is intentionally global across plugins. Use set value() and get value() when the data is temporary and should be isolated to the current plugin. Proposed companion writer: APP SET() A natural opposite of APP() is a helper that writes to the shared $APP variable. This is useful when you want a small, consistent helper instead of writing to the global directly. Copy paste implementation function APP SET(string array $key, mixed $value = \'\'): bool { global $APP; if(is array($key)) { foreach($key as $k = $v) { $APP[$k] = $v; } return true; } $APP[$key] = $value; return true; } Examples APP SET(\'route handled\', true); APP SET([ \'custom debug\' = true, \'feature x\' = \'enabled\', ]); Suggested usage notes Use this sparingly because it writes into global shared application state. Prefer plugin isolated set value() for plugin local runtime data. Prefer APP SET() only for true application level flags or values that are meant to be shared across plugins. Optional nested key version If you want dot notation like APP SET(\'config.debug\', true), that should be implemented as a separate helper rather than changing the basic version. Recipe: mark a request wide flag APP SET(\'my custom flag\', true); if(APP(\'my custom flag\')) { // do something once per request }',
            'order' => 4,
        ],
        [
            'id' => 'functions/thunderphp-functions-list/plugin-discovery-and-compatibility-helpers',
