            ],
            'search_text' => 'plugin discovery and compatibility helpers functions for checking whether plugins exist and for inspecting missing or outdated dependencies. functions thunderphp functions list  functions covered plugin exists() missing plugins() outdated plugins() show plugins() plugin exists(string $plugin id) checks whether an active plugin exists by its plugin id. it returns either the plugin\'s config.json object or false. $plugin = plugin exists(\'basic admin\'); if($plugin) { echo $plugin name; } this is useful when integrating with optional dependencies. missing plugins() returns an array describing plugins requested as dependencies but not currently available. $missing = missing plugins(); this is useful for diagnostics, installer pages, or admin warnings. outdated plugins() returns an array of plugins that are incompatible with the current core version. $old = outdated plugins(); show plugins() displays loaded plugin names using the debugging helper dd(). show plugins(); because it prints directly, it is best used only during development. recipe: warn when an optional dependency is not installed $plugin = plugin exists(\'basic admin\'); if(!$plugin) { message(\'fail\', \'basic admin plugin is required for this feature\'); }',
            'plain_text' => 'Functions covered plugin exists() missing plugins() outdated plugins() show plugins() plugin exists(string $plugin id) Checks whether an active plugin exists by its plugin id. It returns either the plugin\'s config.json object or false. $plugin = plugin exists(\'basic admin\'); if($plugin) { echo $plugin name; } This is useful when integrating with optional dependencies. missing plugins() Returns an array describing plugins requested as dependencies but not currently available. $missing = missing plugins(); This is useful for diagnostics, installer pages, or admin warnings. outdated plugins() Returns an array of plugins that are incompatible with the current core version. $old = outdated plugins(); show plugins() Displays loaded plugin names using the debugging helper dd(). show plugins(); Because it prints directly, it is best used only during development. Recipe: warn when an optional dependency is not installed $plugin = plugin exists(\'basic admin\'); if(!$plugin) { message(\'fail\', \'Basic Admin plugin is required for this feature\'); }',
            'order' => 5,
        ],
        [
