            ],
            'search_text' => 'routes and route parameters functions for checking route matches, reading the current route name, and accessing named route parameters. functions thunderphp functions list  functions covered is route() get route name() get param() thunderphp supports named routes defined in config.json. hook callbacks may optionally be bound to a specific route name. is route(string $route = \'\') checks whether the current plugin matched a particular named route. if(is route(\'post.view\')) { // post details page } if no route is supplied, the function returns true. this makes route restricted action and filter handlers easier to reuse. get route name() returns the current matched route name for the current plugin. $route = get route name(); useful for debugging or when one callback serves multiple routes. get param(string $key = \'\') returns a named route parameter extracted from a route pattern like /post/{slug}. $slug = get param(\'slug\'); $id = get param(\'id\'); example route definition { "method":"get", "pattern":"/post/{slug}", "name":"post.view" } recipe: load a record from a route slug add action(\'controller\', function() { if(!is route(\'post.view\')) { return; } $slug = get param(\'slug\'); // use $slug to load the post }, 10, \'post.view\'); recipe: reuse one callback on more than one route add action(\'controller\', function() { $route = get route name(); if($route == \'post.add\') { // add logic } if($route == \'post.edit\') { // edit logic } });',
            'plain_text' => 'Functions covered is route() get route name() get param() ThunderPHP supports named routes defined in config.json. Hook callbacks may optionally be bound to a specific route name. is route(string $route = \'\') Checks whether the current plugin matched a particular named route. if(is route(\'post.view\')) { // post details page } If no route is supplied, the function returns true. This makes route restricted action and filter handlers easier to reuse. get route name() Returns the current matched route name for the current plugin. $route = get route name(); Useful for debugging or when one callback serves multiple routes. get param(string $key = \'\') Returns a named route parameter extracted from a route pattern like /post/{slug}. $slug = get param(\'slug\'); $id = get param(\'id\'); Example route definition { "method":"GET", "pattern":"/post/{slug}", "name":"post.view" } Recipe: load a record from a route slug add action(\'controller\', function() { if(!is route(\'post.view\')) { return; } $slug = get param(\'slug\'); // use $slug to load the post }, 10, \'post.view\'); Recipe: reuse one callback on more than one route add action(\'controller\', function() { $route = get route name(); if($route == \'post.add\') { // add logic } if($route == \'post.edit\') { // edit logic } });',
            'order' => 6,
        ],
        [
            'id' => 'functions/thunderphp-functions-list/hook-system-actions-and-filters',
            'title' => 'Hook System: Actions and Filters',
            'description' => 'Reference for registering callbacks with `add_action()` and `add_filter()` and executing them with `do_action()` and `do_filter()`.',
            'topic' => 'Functions',
            'topic_slug' => 'functions',
            'subtopic' => 'ThunderPHP Functions List',
            'subtopic_slug' => 'thunderphp-functions-list',
            'section_slug' => 'hook-system-actions-and-filters',
            'url' => 'docs/functions/thunderphp-functions-list/hook-system-actions-and-filters',
            'path' => 'functions/thunderphp-functions-list/007-hook-system-actions-and-filters.md',
            'headings' => [
            ],
            'keywords' => [
                'hook',
                'system',
                'actions',
                'filters',
                'reference',
                'registering',
                'callbacks',
                'add_action',
                'add_filter',
                'executing',
                'them',
                'do_action',
                'do_filter',
                'functions',
                'thunderphp',
                'list',
                'covered',
                'vs',
                'string',
                'mixed',
                'func',
                'int',
                'priority',
                'route',
            ],
            'search_text' => 'hook system: actions and filters reference for registering callbacks with `add_action()` and `add_filter()` and executing them with `do_action()` and `do_filter()`. functions thunderphp functions list  functions covered add action() do action() add filter() do filter() the hook system is the core of plugin communication in thunderphp. actions vs filters actions run code. filters receive data, modify it, and return it. add action(string $hook, mixed $func, int $priority = 10, string $route = \'\') registers a callback to run when the named action hook is fired. add action(\'controller\', function() { // controller logic }); you can also bind it to a named route. add action(\'controller\', function() { // only on this route }, 10, \'post.edit\'); do action(string $hook, array $data = []) executes all callbacks registered for the named action hook. do action(\'before view\'); do action(\'view\'); do action(\'after view\'); callbacks are executed in ascending priority order. lower numbers run earlier. add filter(string $hook, mixed $func, int $priority = 10, string $route = \'\') registers a callback that receives and returns data. add filter(\'user roles\', function($roles) { $roles[] = \'editor\'; return $roles; }); do filter(string $hook, mixed $data = \'\') runs all callbacks for the named filter hook and returns the final modified data. $data = do filter(\'my hook\', $data); priority behavior if a priority is already used, the function internally increments until it finds an empty slot. that means every callback is preserved. context behavior when callbacks run, thunderphp temporarily switches app context to the plugin that registered the callback, then restores the previous context afterward. this is what lets helpers like plugin id() and current look() continue to work correctly inside hooks. recipe: add admin menu links add filter(\'basic admin before admin links\', function($links) { $vars = get value(); $obj = (object)[]; $obj title = \'blog\'; $obj link = root . \'/\' . $vars[\'admin route\'] . \'/\' . $vars[\'plugin route\']; $obj icon = \'fa solid fa file lines\'; $obj parent = 0; $links[] = $obj; return $links; }); recipe: route specific view callback add action(\'view\', function() { include current look(\'frontend/post view.php\'); }, 10, \'post.view\'); common mistake a filter must return data. add filter(\'user roles\', function($roles) { $roles[] = \'admin\'; return $roles; });',
            'plain_text' => 'Functions covered add action() do action() add filter() do filter() The hook system is the core of plugin communication in ThunderPHP. Actions vs filters Actions run code. Filters receive data, modify it, and return it. add action(string $hook, mixed $func, int $priority = 10, string $route = \'\') Registers a callback to run when the named action hook is fired. add action(\'controller\', function() { // controller logic }); You can also bind it to a named route. add action(\'controller\', function() { // only on this route }, 10, \'post.edit\'); do action(string $hook, array $data = []) Executes all callbacks registered for the named action hook. do action(\'before view\'); do action(\'view\'); do action(\'after view\'); Callbacks are executed in ascending priority order. Lower numbers run earlier. add filter(string $hook, mixed $func, int $priority = 10, string $route = \'\') Registers a callback that receives and returns data. add filter(\'user roles\', function($roles) { $roles[] = \'editor\'; return $roles; }); do filter(string $hook, mixed $data = \'\') Runs all callbacks for the named filter hook and returns the final modified data. $data = do filter(\'my hook\', $data); Priority behavior If a priority is already used, the function internally increments until it finds an empty slot. That means every callback is preserved. Context behavior When callbacks run, ThunderPHP temporarily switches app context to the plugin that registered the callback, then restores the previous context afterward. This is what lets helpers like plugin id() and current look() continue to work correctly inside hooks. Recipe: add admin menu links add filter(\'basic admin before admin links\', function($links) { $vars = get value(); $obj = (object)[]; $obj title = \'Blog\'; $obj link = ROOT . \'/\' . $vars[\'admin route\'] . \'/\' . $vars[\'plugin route\']; $obj icon = \'fa solid fa file lines\'; $obj parent = 0; $links[] = $obj; return $links; }); Recipe: route specific view callback add action(\'view\', function() { include current look(\'frontend/post view.php\'); }, 10, \'post.view\'); Common mistake A filter must return data. add filter(\'user roles\', function($roles) { $roles[] = \'admin\'; return $roles; });',
            'order' => 7,
        ],
