            ],
            'search_text' => 'look and path helpers helpers for building filesystem and http paths to plugin files, views, and assets. functions thunderphp functions list  functions covered current look() current look http() plugin path() plugin http path() class path() current look(string $path) builds a filesystem path inside the current look folder of the current plugin. include current look(\'frontend/home.php\'); include current look(\'admin/form.php\'); this is the preferred way to include view files from the active look. current look http(string $path) builds a public http path inside the current look folder. echo current look http(\'assets/css/style.css\'); echo current look http(\'assets/js/app.js\'); use this for css, javascript, images, and other public look assets. plugin path(string $path = \'\') builds a filesystem path relative to the current plugin folder. require plugin path(\'controllers/admin/posts.php\'); this is useful for php includes outside the look system. plugin http path(string $path = \'\') builds a public http path relative to the current plugin folder. echo plugin http path(\'assets/images/logo.png\'); echo plugin http path(\'looks/main/assets/css/admin.css\'); class path(string $folder, string $class name) builds the path to a class file from another plugin\'s models folder. require once class path(\'basic blog\', \'post\'); this should be a fallback, not the first choice. prefer hooks for cross plugin integration where possible. recipe: include the current look header include current look(\'frontend/header.php\'); recipe: load plugin specific css',
            'plain_text' => 'Functions covered current look() current look http() plugin path() plugin http path() class path() current look(string $path) Builds a filesystem path inside the current look folder of the current plugin. include current look(\'frontend/home.php\'); include current look(\'admin/form.php\'); This is the preferred way to include view files from the active look. current look http(string $path) Builds a public HTTP path inside the current look folder. echo current look http(\'assets/css/style.css\'); echo current look http(\'assets/js/app.js\'); Use this for CSS, JavaScript, images, and other public look assets. plugin path(string $path = \'\') Builds a filesystem path relative to the current plugin folder. require plugin path(\'controllers/admin/posts.php\'); This is useful for PHP includes outside the look system. plugin http path(string $path = \'\') Builds a public HTTP path relative to the current plugin folder. echo plugin http path(\'assets/images/logo.png\'); echo plugin http path(\'looks/main/assets/css/admin.css\'); class path(string $folder, string $class name) Builds the path to a class file from another plugin\'s models folder. require once class path(\'basic blog\', \'Post\'); This should be a fallback, not the first choice. Prefer hooks for cross plugin integration where possible. Recipe: include the current look header include current look(\'frontend/header.php\'); Recipe: load plugin specific CSS',
            'order' => 8,
        ],
