                'admin',
                'page',
            ],
            'search_text' => 'roles and permissions helpers for resolving current user roles and permissions and enforcing access in controllers and views. functions thunderphp functions list  functions covered user roles() contains role() user can() thunderphp separates roles from permissions. roles are broad labels such as admin, editor, or user. permissions are specific capabilities such as edit post or delete post. user roles() returns all roles for the current user. the user roles filter is evaluated once and cached for the rest of the request. $roles = user roles(); typical role registration: add filter(\'user roles\', function($roles) { $ses = new \\core\\session; if($ses is logged in()) { $roles[] = \'user\'; } return $roles; }); contains role(string $role) checks whether the current user has a role. comparison is case insensitive. if(contains role(\'admin\')) { // admin only } user can(?string $permission) checks whether the current user has a permission. if(user can(\'edit post\')) { // allow editing } special built in checks: user can(\'logged in\') user can(\'not logged in\') admin users automatically pass all permission checks because the helper returns true when admin is present in the role list. the permission list is loaded from the user permissions filter and cached for the request. add filter(\'user permissions\', function($permissions) { $permissions[] = \'view posts\'; $permissions[] = \'edit post\'; return $permissions; }); the special permission all grants universal permission access. recipe: protect an admin page add action(\'controller\', function() { if(!user can(\'edit post\')) { message(\'fail\', \'you do not have permission to edit posts\'); redirect(\'admin\'); } }, 10, \'post.edit\'); recipe: hide a button in a view',
            'plain_text' => 'Functions covered user roles() contains role() user can() ThunderPHP separates roles from permissions. Roles are broad labels such as admin, editor, or user. Permissions are specific capabilities such as edit post or delete post. user roles() Returns all roles for the current user. The user roles filter is evaluated once and cached for the rest of the request. $roles = user roles(); Typical role registration: add filter(\'user roles\', function($roles) { $ses = new \\Core\\Session; if($ses is logged in()) { $roles[] = \'user\'; } return $roles; }); contains role(string $role) Checks whether the current user has a role. Comparison is case insensitive. if(contains role(\'admin\')) { // admin only } user can(?string $permission) Checks whether the current user has a permission. if(user can(\'edit post\')) { // allow editing } Special built in checks: user can(\'logged in\') user can(\'not logged in\') Admin users automatically pass all permission checks because the helper returns true when admin is present in the role list. The permission list is loaded from the user permissions filter and cached for the request. add filter(\'user permissions\', function($permissions) { $permissions[] = \'view posts\'; $permissions[] = \'edit post\'; return $permissions; }); The special permission all grants universal permission access. Recipe: protect an admin page add action(\'controller\', function() { if(!user can(\'edit post\')) { message(\'fail\', \'You do not have permission to edit posts\'); redirect(\'admin\'); } }, 10, \'post.edit\'); Recipe: hide a button in a view',
            'order' => 9,
