            'search_text' => 'csrf protection reference for generating and verifying csrf tokens using `csrf()` and `csrf_verify()`. functions thunderphp functions list  functions covered csrf() csrf verify() csrf tokens protect forms from cross site request forgery. csrf($seskey = \'csrf\', $hours = 1, $return input = true) creates a token and stores it in session. by default it returns a full hidden input element. save you can also request the raw token string. $token = csrf(\'csrf\', 1, false); token lifetime the token remains valid for the configured number of hours. csrf verify($post, $seskey = \'csrf\') verifies a token submitted by a form. if(!csrf verify($ post)) { message(\'fail\', \'invalid csrf token\'); } verified tokens are removed after successful use, which makes them one time tokens. using a custom session key if(!csrf verify($ post, \'delete csrf\')) { message(\'fail\', \'invalid delete request\'); } recipe: csrf safe delete form',
            'plain_text' => 'Functions covered csrf() csrf verify() CSRF tokens protect forms from cross site request forgery. csrf($sesKey = \'csrf\', $hours = 1, $return input = true) Creates a token and stores it in session. By default it returns a full hidden input element. Save You can also request the raw token string. $token = csrf(\'csrf\', 1, false); Token lifetime The token remains valid for the configured number of hours. csrf verify($post, $sesKey = \'csrf\') Verifies a token submitted by a form. if(!csrf verify($ POST)) { message(\'fail\', \'Invalid CSRF token\'); } Verified tokens are removed after successful use, which makes them one time tokens. Using a custom session key if(!csrf verify($ POST, \'delete csrf\')) { message(\'fail\', \'Invalid delete request\'); } Recipe: CSRF safe delete form',
