            'search_text' => 'output, images, dates, and messages general-purpose helpers for escaping output, formatting dates, loading placeholder images, flashing messages, and debugging. functions thunderphp functions list  functions covered esc() get image() get date() message() dd() esc(?string $str) escapes special html characters using htmlspecialchars(). use this whenever displaying user controlled text in html. get image(?string $path = \'\', string $type = \'post\') returns an image url if the file exists, otherwise returns a placeholder image.',
