            ],
            'search_text' => 'practical recipes common real-world patterns using the helper functions together in controllers, views, and plugin bootstrap code. functions thunderphp functions list  recipe 1: basic plugin bootstrap values set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', \'posts table\' = \'bb posts\', ]); this gives the rest of your plugin a predictable place to read route and table names. recipe 2: add an admin sidebar link add filter(\'basic admin before admin links\', function($links) { $vars = get value(); $obj = (object)[]; $obj title = \'blog\'; $obj link = root . \'/\' . $vars[\'admin route\'] . \'/\' . $vars[\'plugin route\']; $obj icon = \'fa solid fa file lines\'; $obj parent = 0; $links[] = $obj; return $links; }); recipe 3: restrict a controller action by permission add action(\'controller\', function() { if(!user can(\'edit post\')) { message(\'fail\', \'you do not have permission to do that\'); redirect(\'admin\'); } }, 10, \'post.edit\'); recipe 4: render a route specific view add action(\'view\', function() { include current look(\'frontend/post view.php\'); }, 10, \'post.view\'); recipe 5: use route parameters add action(\'controller\', function() { $slug = get param(\'slug\'); if(empty($slug)) { redirect(\'\'); } // load record by slug }, 10, \'post.view\'); recipe 6: sticky form with csrf and flash messages',
            'plain_text' => 'Recipe 1: Basic plugin bootstrap values set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', \'posts table\' = \'bb posts\', ]); This gives the rest of your plugin a predictable place to read route and table names. Recipe 2: Add an admin sidebar link add filter(\'basic admin before admin links\', function($links) { $vars = get value(); $obj = (object)[]; $obj title = \'Blog\'; $obj link = ROOT . \'/\' . $vars[\'admin route\'] . \'/\' . $vars[\'plugin route\']; $obj icon = \'fa solid fa file lines\'; $obj parent = 0; $links[] = $obj; return $links; }); Recipe 3: Restrict a controller action by permission add action(\'controller\', function() { if(!user can(\'edit post\')) { message(\'fail\', \'You do not have permission to do that\'); redirect(\'admin\'); } }, 10, \'post.edit\'); Recipe 4: Render a route specific view add action(\'view\', function() { include current look(\'frontend/post view.php\'); }, 10, \'post.view\'); Recipe 5: Use route parameters add action(\'controller\', function() { $slug = get param(\'slug\'); if(empty($slug)) { redirect(\'\'); } // load record by slug }, 10, \'post.view\'); Recipe 6: Sticky form with CSRF and flash messages',
