            'search_text' => 'reference summary compact summary table of the documented helper functions and their primary purpose. functions thunderphp functions list  request and url current url() — get the full current url base url() — build internal urls from root split url() — split a url into segments url() — read a url segment or all segments page() — shortcut for url(0) redirect() — redirect to an internal path plugin context and state set value() — store plugin isolated request data get value() — retrieve plugin isolated request data plugin id() — current plugin id get context() — current plugin context object application wide state app() — read shared application state app set() — proposed helper to write shared application state routes and hooks is route() — test current matched route get route name() — current matched route name get param() — named route parameter add action() — register action callback do action() — execute action callbacks add filter() — register filter callback do filter() — execute filter callbacks paths and views current look() — filesystem path inside current look current look http() — http path inside current look plugin path() — filesystem path inside current plugin plugin http path() — http path inside current plugin class path() — path to another plugin model class plugins and compatibility plugin exists() — detect an active plugin by id missing plugins() — list missing dependencies outdated plugins() — list core incompatible plugins show plugins() — debug loaded plugin names roles and permissions user roles() — current roles contains role() — role check user can() — permission check forms and csrf old value() — sticky value for inputs old select() — sticky selected option old checked() — sticky checked state csrf() — generate token or hidden field csrf verify() — verify submitted token utility helpers get image() — image path with placeholder fallback esc() — escape html get date() — human readable date message() — flash messaging dd() — debug dump',
            'plain_text' => 'Request and URL current url() — get the full current URL base url() — build internal URLs from ROOT split url() — split a URL into segments URL() — read a URL segment or all segments page() — shortcut for URL(0) redirect() — redirect to an internal path Plugin context and state set value() — store plugin isolated request data get value() — retrieve plugin isolated request data plugin id() — current plugin id get context() — current plugin context object Application wide state APP() — read shared application state APP SET() — proposed helper to write shared application state Routes and hooks is route() — test current matched route get route name() — current matched route name get param() — named route parameter add action() — register action callback do action() — execute action callbacks add filter() — register filter callback do filter() — execute filter callbacks Paths and views current look() — filesystem path inside current look current look http() — HTTP path inside current look plugin path() — filesystem path inside current plugin plugin http path() — HTTP path inside current plugin class path() — path to another plugin model class Plugins and compatibility plugin exists() — detect an active plugin by id missing plugins() — list missing dependencies outdated plugins() — list core incompatible plugins show plugins() — debug loaded plugin names Roles and permissions user roles() — current roles contains role() — role check user can() — permission check Forms and CSRF old value() — sticky value for inputs old select() — sticky selected option old checked() — sticky checked state csrf() — generate token or hidden field csrf verify() — verify submitted token Utility helpers get image() — image path with placeholder fallback esc() — escape HTML get date() — human readable date message() — flash messaging dd() — debug dump',
