            'search_text' => 'create the plugin use the thunder cli to scaffold the plugin and inspect the generated structure. getting started create your first plugin  start by generating the plugin: php thunder make:plugin hello world after generation, you should have a plugin folder with the recommended structure. at minimum, make sure these files exist: plugin.php config.json looks/main/look.json the cli generated structure is recommended because it matches the normal thunderphp workflow and keeps plugins consistent.',
