            'search_text' => 'set up config.json define the plugin metadata and the named routes for the first plugin. getting started create your first plugin  use a simple config.json like this: { "name": "hello world", "version": "1.0.0", "core requires": "^1.0.0", "id": "hello world", "description": "my first thunderphp plugin", "author": "your name", "website": "", "thumbnail": "thumbnail.jpg", "active": true, "look": "main", "index": 1, "routes": { "on": ["hello", "admin"], "off": [], "routes":[ { "method":"get", "pattern":"/hello", "name":"hello.index" }, { "method":"get", "pattern":"/admin/hello", "name":"hello.admin" } ] } } this gives the plugin one frontend page and one admin page, both with clear route names.',
            'plain_text' => 'Use a simple config.json like this: { "name": "Hello World", "version": "1.0.0", "core requires": "^1.0.0", "id": "hello world", "description": "My first ThunderPHP plugin", "author": "Your Name", "website": "", "thumbnail": "thumbnail.jpg", "active": true, "look": "main", "index": 1, "routes": { "on": ["hello", "admin"], "off": [], "routes":[ { "method":"GET", "pattern":"/hello", "name":"hello.index" }, { "method":"GET", "pattern":"/admin/hello", "name":"hello.admin" } ] } } This gives the plugin one frontend page and one admin page, both with clear route names.',
