            ],
            'search_text' => 'optional next step: add a migration see how even a small plugin can define its own tables when needed. getting started create your first plugin  if your first plugin needs a table, generate a migration: php thunder make:migration hello world create messages table example migration: namespace migration; class create messages table extends migration { public function up() { $this addcolumn("id int unsigned not null auto increment"); $this addcolumn("message varchar(255) not null"); $this addprimarykey("id"); $this createtable("hello world messages"); } public function down() { $this droptable("hello world messages"); } } then run it: php thunder migrate hello world this is one of the strengths of thunderphp: the plugin can own its own tables instead of depending on a fixed app schema.',
            'plain_text' => 'If your first plugin needs a table, generate a migration: php thunder make:migration hello world create messages table Example migration: namespace Migration; class Create messages table extends Migration { public function up() { $this addColumn("id INT UNSIGNED NOT NULL AUTO INCREMENT"); $this addColumn("message VARCHAR(255) NOT NULL"); $this addPrimaryKey("id"); $this createTable("hello world messages"); } public function down() { $this dropTable("hello world messages"); } } Then run it: php thunder migrate hello world This is one of the strengths of ThunderPHP: the plugin can own its own tables instead of depending on a fixed app schema.',
            'order' => 8,
        ],
