            'search_text' => 'what you learned review the main ideas a beginner should understand after finishing the first plugin. getting started create your first plugin  after building this first plugin, you should understand these core thunderphp ideas: a plugin is a reusable feature module plugin.php wires the plugin into the framework named routes make logic cleaner frontend pages normally render through view admin pages normally render through admin main content admin links can be added through admin before links controller logic can stay procedural or be moved into included files plugins can define their own tables through migrations once this mental model is clear, more advanced plugins start feeling much easier to design.',
            'plain_text' => 'After building this first plugin, you should understand these core ThunderPHP ideas: a plugin is a reusable feature module plugin.php wires the plugin into the framework named routes make logic cleaner frontend pages normally render through view admin pages normally render through admin main content admin links can be added through admin before links controller logic can stay procedural or be moved into included files plugins can define their own tables through migrations Once this mental model is clear, more advanced plugins start feeling much easier to design.',
