        [
            'id' => 'getting-started/getting-started/getting-started-with-thunderphp',
            'title' => 'Getting Started with ThunderPHP',
            'description' => 'An introduction to how ThunderPHP works and how to approach it as a plugin-based framework.',
            'topic' => 'Getting Started',
            'topic_slug' => 'getting-started',
            'subtopic' => 'Getting Started',
            'subtopic_slug' => 'getting-started',
            'section_slug' => 'getting-started-with-thunderphp',
            'url' => 'docs/getting-started/getting-started/getting-started-with-thunderphp',
            'path' => 'getting-started/getting-started/001-getting-started-with-thunderphp.md',
            'headings' => [
            ],
            'keywords' => [
                'getting',
                'started',
                'thunderphp',
                'introduction',
                'works',
                'approach',
                'plugin-based',
                'framework',
                'think',
                'about',
                'main',
                'idea',
            ],
            'search_text' => 'getting started with thunderphp an introduction to how thunderphp works and how to approach it as a plugin-based framework. getting started getting started  thunderphp is a plugin based framework built to combine the re usability of plugins with the freedom of a framework. in a normal mvc framework, features are often spread across many folders and tightly connected to the rest of the app. in thunderphp, a feature is usually built as a self contained plugin that can be reused in many projects. that means a plugin can: define its own routes define its own tables define its own permissions provide admin pages provide frontend pages be turned on or off more easily than tightly coupled app code how to think about thunderphp thunderphp is not strict mvc and it is not a cms. it is best understood as a hook driven modular framework where plugins are the main reusable unit. controllers are usually plain execution blocks registered on hooks, though you can still use classes if you prefer. the main idea build a feature once as a plugin, then reuse it in many projects with minimal changes.',
            'plain_text' => 'ThunderPHP is a plugin based framework built to combine the re usability of plugins with the freedom of a framework. In a normal MVC framework, features are often spread across many folders and tightly connected to the rest of the app. In ThunderPHP, a feature is usually built as a self contained plugin that can be reused in many projects. That means a plugin can: define its own routes define its own tables define its own permissions provide admin pages provide frontend pages be turned on or off more easily than tightly coupled app code How To Think About ThunderPHP ThunderPHP is not strict MVC and it is not a CMS. It is best understood as a hook driven modular framework where plugins are the main reusable unit. Controllers are usually plain execution blocks registered on hooks, though you can still use classes if you prefer. The Main Idea Build a feature once as a plugin, then reuse it in many projects with minimal changes.',
            'order' => 1,
        ],
        [
            'id' => 'getting-started/getting-started/what-a-plugin-is',
            'title' => 'What a Plugin Is',
            'description' => 'Understand the job of plugin.php, config.json, looks, migrations, models, and controllers.',
            'topic' => 'Getting Started',
            'topic_slug' => 'getting-started',
            'subtopic' => 'Getting Started',
            'subtopic_slug' => 'getting-started',
            'section_slug' => 'what-a-plugin-is',
            'url' => 'docs/getting-started/getting-started/what-a-plugin-is',
            'path' => 'getting-started/getting-started/002-what-a-plugin-is.md',
            'headings' => [
            ],
            'keywords' => [
                'plugin',
                'understand',
                'job',
                'php',
                'config',
                'json',
                'looks',
                'migrations',
                'models',
                'controllers',
                'getting',
                'started',
                'core',
                'files',
            ],
            'search_text' => 'what a plugin is understand the job of plugin.php, config.json, looks, migrations, models, and controllers. getting started getting started  in thunderphp, a plugin is a self contained feature module. a plugin normally contains: plugin.php config.json looks/ migrations/ models/ controllers/ the core files plugin.php is where the plugin registers actions and filters. config.json describes the plugin, its routes, whether it is active, and what look it uses. looks/ contains templates and assets for output. migrations/ contains schema changes for the plugin\'s tables. models/ contains plugin specific data classes. controllers/ can contain included controller files to keep plugin.php small. none of this is meant to trap the developer into a rigid structure, but following it keeps the plugin easier to understand and matches how the cli tool scaffolds files.',
            'plain_text' => 'In ThunderPHP, a plugin is a self contained feature module. A plugin normally contains: plugin.php config.json looks/ migrations/ models/ controllers/ The Core Files plugin.php is where the plugin registers actions and filters. config.json describes the plugin, its routes, whether it is active, and what look it uses. looks/ contains templates and assets for output. migrations/ contains schema changes for the plugin\'s tables. models/ contains plugin specific data classes. controllers/ can contain included controller files to keep plugin.php small. None of this is meant to trap the developer into a rigid structure, but following it keeps the plugin easier to understand and matches how the CLI tool scaffolds files.',
            'order' => 2,
        ],
        [
            'id' => 'getting-started/getting-started/how-hooks-drive-the-framework',
            'title' => 'How Hooks Drive the Framework',
            'description' => 'Learn the main execution flow and how plugins plug into it.',
            'topic' => 'Getting Started',
            'topic_slug' => 'getting-started',
            'subtopic' => 'Getting Started',
            'subtopic_slug' => 'getting-started',
            'section_slug' => 'how-hooks-drive-the-framework',
            'url' => 'docs/getting-started/getting-started/how-hooks-drive-the-framework',
            'path' => 'getting-started/getting-started/003-how-hooks-drive-the-framework.md',
            'headings' => [
            ],
            'keywords' => [
                'hooks',
                'drive',
                'framework',
                'learn',
                'main',
                'execution',
                'flow',
                'plugins',
                'plug',
                'getting',
                'started',
                'lifecycle',
                'action',
                'vs',
                'filter',
                'important',
                'naming',
                'rule',
            ],
            'search_text' => 'how hooks drive the framework learn the main execution flow and how plugins plug into it. getting started getting started  thunderphp plugins talk to the framework using hooks. the two main registration functions are: add action(\'hook name\', function($data){}, 10, \'\'); add filter(\'hook name\', function($data){ return $data; }, 10, \'\'); main lifecycle hooks 1. roles 2. permissions 3. before controller 4. controller 5. after controller 6. before view 7. view 8. after view this means a thunderphp page request is usually assembled by many plugins contributing behavior at different stages. action vs filter use an action when you want to run code use a filter when you want to modify and return data important naming rule standard admin hooks should use: admin main content admin before links for other custom hooks, follow the {plugin id} hook name convention to avoid collisions with other plugins.',
            'plain_text' => 'ThunderPHP plugins talk to the framework using hooks. The two main registration functions are: add action(\'hook name\', function($data){}, 10, \'\'); add filter(\'hook name\', function($data){ return $data; }, 10, \'\'); Main Lifecycle Hooks 1. roles 2. permissions 3. before controller 4. controller 5. after controller 6. before view 7. view 8. after view This means a ThunderPHP page request is usually assembled by many plugins contributing behavior at different stages. Action vs Filter use an action when you want to run code use a filter when you want to modify and return data Important Naming Rule Standard admin hooks should use: admin main content admin before links For other custom hooks, follow the {plugin id} hook name convention to avoid collisions with other plugins.',
            'order' => 3,
        ],
