            'id' => 'getting-started/getting-started/routes-and-named-route-thinking',
            'title' => 'Routes and Named Route Thinking',
            'description' => 'Why named routes are preferred and how they make plugins cleaner.',
            'topic' => 'Getting Started',
            'topic_slug' => 'getting-started',
            'subtopic' => 'Getting Started',
            'subtopic_slug' => 'getting-started',
            'section_slug' => 'routes-and-named-route-thinking',
            'url' => 'docs/getting-started/getting-started/routes-and-named-route-thinking',
            'path' => 'getting-started/getting-started/004-routes-and-named-route-thinking.md',
            'headings' => [
            ],
            'keywords' => [
                'routes',
                'named',
