                'thinking',
                'why',
                'preferred',
                'make',
                'plugins',
                'cleaner',
                'getting',
                'started',
                'matter',
            ],
            'search_text' => 'routes and named route thinking why named routes are preferred and how they make plugins cleaner. getting started getting started  thunderphp supports coarse plugin loading with routes.on and routes.off, but the preferred route system is the named route list in routes.routes. example: { "routes": { "on": ["blog", "admin"], "off": [], "routes":[ { "method":"get", "pattern":"/blog", "name":"blog.index" }, { "method":"get", "pattern":"/blog/{slug}", "name":"blog.view" } ] } } why named routes matter they let you scope logic directly to a route: add action(\'controller\', function($data){ include plugin path(\'controllers/frontend/index.php\'); }, 10, \'blog.index\'); they also make route checks easier: if(is route(\'blog.view\')) { $slug = get param(\'slug\'); } this approach scales much better than relying only on the first url segment.',
            'plain_text' => 'ThunderPHP supports coarse plugin loading with routes.on and routes.off, but the preferred route system is the named route list in routes.routes. Example: { "routes": { "on": ["blog", "admin"], "off": [], "routes":[ { "method":"GET", "pattern":"/blog", "name":"blog.index" }, { "method":"GET", "pattern":"/blog/{slug}", "name":"blog.view" } ] } } Why Named Routes Matter They let you scope logic directly to a route: add action(\'controller\', function($data){ include plugin path(\'controllers/frontend/index.php\'); }, 10, \'blog.index\'); They also make route checks easier: if(is route(\'blog.view\')) { $slug = get param(\'slug\'); } This approach scales much better than relying only on the first URL segment.',
            'order' => 4,
        ],
