            'search_text' => 'core helpers you will use early the most important helpers a beginner plugin author should know first. getting started getting started  some helpers are used in almost every plugin. request values for the current page load set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\' ]); $vars = get value(); url helpers $page = page(); $segment1 = url(1); $current = current url(); redirects redirect(\'admin/blog\'); output safety echo esc($title); messages message(\'success\', \'post saved\'); message(\'fail\', \'something went wrong\'); csrf then verify posted data: csrf verify($req post()); these helpers form the everyday working surface of thunderphp plugin development.',
