                'started',
                'best',
                'advice',
            ],
            'search_text' => 'beginner workflow a simple mental checklist for building a plugin from idea to working feature. getting started getting started  a simple thunderphp workflow looks like this: 1. create the plugin with the cli 2. define config.json 3. define named routes 4. set shared request values with set value() 5. create migrations if the plugin needs tables 6. register controller hooks for logic 7. register view or admin main content hooks for output 8. add permissions if needed 9. validate input 10. test route flow and 404 behavior best beginner advice keep plugin.php focused on hook registration and small setup tasks. move heavier logic into included files under controllers/ and keep views inside the active look. that pattern stays readable even as the plugin grows.',
            'plain_text' => 'A simple ThunderPHP workflow looks like this: 1. create the plugin with the CLI 2. define config.json 3. define named routes 4. set shared request values with set value() 5. create migrations if the plugin needs tables 6. register controller hooks for logic 7. register view or admin main content hooks for output 8. add permissions if needed 9. validate input 10. test route flow and 404 behavior Best Beginner Advice Keep plugin.php focused on hook registration and small setup tasks. Move heavier logic into included files under controllers/ and keep views inside the active look. That pattern stays readable even as the plugin grows.',
            'order' => 7,
        ],
        [
            'id' => 'getting-started/installation/system-requirements',
            'title' => 'System Requirements',
            'description' => 'Prepare PHP, MySQL or MariaDB, and the command-line tools needed to run ThunderPHP locally.',
            'topic' => 'Getting Started',
            'topic_slug' => 'getting-started',
            'subtopic' => 'Installation',
            'subtopic_slug' => 'installation',
            'section_slug' => 'system-requirements',
            'url' => 'docs/getting-started/installation/system-requirements',
            'path' => 'getting-started/installation/001-system-requirements.md',
            'headings' => [
                'Required software',
                'The easiest Windows setup: XAMPP',
                'macOS and Linux',
            ],
            'keywords' => [
                'installation',
                'requirements',
                'php',
                'mysql',
                'mariadb',
                'xampp',
                'cli',
                'pdo_mysql',
            ],
            'search_text' => 'system requirements prepare php, mysql or mariadb, and the command-line tools needed to run thunderphp locally. getting started installation required software the easiest windows setup: xampp macos and linux before downloading thunderphp, prepare a local php development environment. required software you need: php available from the command line. mysql or mariadb for plugins and applications that use the database. the php pdo and pdo mysql extensions. a web browser. git, if you want to clone the repository. git is optional when downloading a zip file. the easiest windows setup: xampp for many windows users, xampp is the quickest way to install php and a mysql compatible database together. after installing xampp: 1. open the xampp control panel. 2. start mysql . 3. make php available in your terminal by adding the xampp php folder to your system path. the usual php folder is: c:\\xampp\\php alternatively, open the xampp shell and run the thunderphp commands from there. you do not need to start apache when using thunderphp\'s built in development server. the php thunder serve command starts the local http server for you. macos and linux install php, pdo mysql, and mysql or mariadb using your operating system\'s package manager or a local development package. the package names vary by operating system and php version. after installation, confirm that the php command works in a terminal before continuing.',
            'plain_text' => 'Before downloading ThunderPHP, prepare a local PHP development environment. Required software You need: PHP available from the command line. MySQL or MariaDB for plugins and applications that use the database. The PHP PDO and PDO MySQL extensions. A web browser. Git, if you want to clone the repository. Git is optional when downloading a ZIP file. The easiest Windows setup: XAMPP For many Windows users, XAMPP is the quickest way to install PHP and a MySQL compatible database together. After installing XAMPP: 1. Open the XAMPP Control Panel. 2. Start MySQL . 3. Make PHP available in your terminal by adding the XAMPP PHP folder to your system PATH. The usual PHP folder is: C:\\xampp\\php Alternatively, open the XAMPP Shell and run the ThunderPHP commands from there. You do not need to start Apache when using ThunderPHP\'s built in development server. The php thunder serve command starts the local HTTP server for you. macOS and Linux Install PHP, PDO MySQL, and MySQL or MariaDB using your operating system\'s package manager or a local development package. The package names vary by operating system and PHP version. After installation, confirm that the php command works in a terminal before continuing.',
            'order' => 1,
        ],
        [
            'id' => 'getting-started/installation/download-thunderphp',
            'title' => 'Download ThunderPHP',
            'description' => 'Clone ThunderPHP from GitHub or download the repository as a ZIP archive.',
            'topic' => 'Getting Started',
            'topic_slug' => 'getting-started',
            'subtopic' => 'Installation',
            'subtopic_slug' => 'installation',
            'section_slug' => 'download-thunderphp',
            'url' => 'docs/getting-started/installation/download-thunderphp',
            'path' => 'getting-started/installation/002-download-thunderphp.md',
            'headings' => [
                'Clone with Git',
                'Download a ZIP file',
            ],
            'keywords' => [
                'download',
                'github',
                'clone',
                'git',
                'zip',
                'repository',
                'thunderphp',
            ],
            'search_text' => 'download thunderphp clone thunderphp from github or download the repository as a zip archive. getting started installation clone with git download a zip file thunderphp is available from its github repository: github.com/eathorne2/thunderphp clone with git open a terminal in the folder where you keep development projects, then run: git clone https://github.com/eathorne2/thunderphp.git cd thunderphp cloning with git makes it easier to pull future framework updates and inspect the project\'s commit history. download a zip file when git is not installed: 1. open the thunderphp repository in your browser. 2. select code . 3. select download zip . 4. extract the archive into your development folder. 5. open a terminal inside the extracted thunderphp folder. the terminal should be in the framework root—the folder containing the thunder command file—before you run any thunderphp cli commands.',
            'plain_text' => 'ThunderPHP is available from its GitHub repository: github.com/Eathorne2/ThunderPHP Clone with Git Open a terminal in the folder where you keep development projects, then run: git clone https://github.com/Eathorne2/ThunderPHP.git cd ThunderPHP Cloning with Git makes it easier to pull future framework updates and inspect the project\'s commit history. Download a ZIP file When Git is not installed: 1. Open the ThunderPHP repository in your browser. 2. Select Code . 3. Select Download ZIP . 4. Extract the archive into your development folder. 5. Open a terminal inside the extracted ThunderPHP folder. The terminal should be in the framework root—the folder containing the thunder command file—before you run any ThunderPHP CLI commands.',
            'order' => 2,
        ],
        [
            'id' => 'getting-started/installation/verify-your-environment',
            'title' => 'Verify Your Environment',
            'description' => 'Confirm that PHP and the required database extensions are available before starting ThunderPHP.',
            'topic' => 'Getting Started',
            'topic_slug' => 'getting-started',
            'subtopic' => 'Installation',
            'subtopic_slug' => 'installation',
            'section_slug' => 'verify-your-environment',
            'url' => 'docs/getting-started/installation/verify-your-environment',
            'path' => 'getting-started/installation/003-verify-your-environment.md',
            'headings' => [
                'Check PHP',
                'Check PHP extensions',
                'Check the database server',
            ],
            'keywords' => [
                'verify',
                'php version',
                'php modules',
                'pdo',
                'pdo_mysql',
                'mysql',
                'environment',
                'terminal',
            ],
            'search_text' => 'verify your environment confirm that php and the required database extensions are available before starting thunderphp. getting started installation check php check php extensions check the database server before starting the framework, verify that your terminal can find php. check php run: php v you should see the installed php version. if the command is not recognized, php is not installed or its folder has not been added to your system path. check php extensions list the enabled php modules: php m confirm that the list includes: pdo pdo mysql these extensions allow thunderphp applications to connect to mysql or mariadb through pdo. check the database server start mysql or mariadb before loading an application that requires a database. when using xampp, start mysql from the xampp control panel. apache can remain stopped when you plan to use php thunder serve. if the mysql command line client is installed and available in your path, you can also check it with: mysql version the absence of the mysql terminal command does not necessarily mean the database server is unavailable. xampp users can manage the server from the xampp control panel or phpmyadmin.',
            'plain_text' => 'Before starting the framework, verify that your terminal can find PHP. Check PHP Run: php v You should see the installed PHP version. If the command is not recognized, PHP is not installed or its folder has not been added to your system PATH. Check PHP extensions List the enabled PHP modules: php m Confirm that the list includes: PDO pdo mysql These extensions allow ThunderPHP applications to connect to MySQL or MariaDB through PDO. Check the database server Start MySQL or MariaDB before loading an application that requires a database. When using XAMPP, start MySQL from the XAMPP Control Panel. Apache can remain stopped when you plan to use php thunder serve. If the MySQL command line client is installed and available in your PATH, you can also check it with: mysql version The absence of the mysql terminal command does not necessarily mean the database server is unavailable. XAMPP users can manage the server from the XAMPP Control Panel or phpMyAdmin.',
            'order' => 3,
        ],
        [
            'id' => 'getting-started/installation/run-the-development-server',
            'title' => 'Run the Development Server',
            'description' => 'Start ThunderPHP with the built-in development server and customize the host or port.',
            'topic' => 'Getting Started',
            'topic_slug' => 'getting-started',
            'subtopic' => 'Installation',
            'subtopic_slug' => 'installation',
            'section_slug' => 'run-the-development-server',
            'url' => 'docs/getting-started/installation/run-the-development-server',
            'path' => 'getting-started/installation/004-run-the-development-server.md',
            'headings' => [
                'Start with the defaults',
                'Use a custom host and port',
                'View command help',
                'Stop the server',
            ],
            'keywords' => [
                'serve',
                'development server',
                'localhost',
                '127.0.0.1',
                'port',
                'host',
                'thunder cli',
                'run',
            ],
            'search_text' => 'run the development server start thunderphp with the built-in development server and customize the host or port. getting started installation start with the defaults use a custom host and port view command help stop the server open a terminal in the thunderphp project root. start with the defaults run: php thunder serve this serves the application at: http://127.0.0.1:8000 open that address in your browser. use a custom host and port options can be written with an equals sign: php thunder serve host=0.0.0.0 port=8080 spaced options are also supported: php thunder serve host 127.0.0.1 port 9000 use 0.0.0.0 when the development server must listen on all available network interfaces. use an appropriate firewall configuration and only expose a development server on a trusted network. view command help run: php thunder serve help this displays the options supported by the serve command. stop the server return to the terminal where the server is running and press: ctrl+c the built in server is intended for local development and testing. use a properly configured production web server when deploying a live application.',
            'plain_text' => 'Open a terminal in the ThunderPHP project root. Start with the defaults Run: php thunder serve This serves the application at: http://127.0.0.1:8000 Open that address in your browser. Use a custom host and port Options can be written with an equals sign: php thunder serve host=0.0.0.0 port=8080 Spaced options are also supported: php thunder serve host 127.0.0.1 port 9000 Use 0.0.0.0 when the development server must listen on all available network interfaces. Use an appropriate firewall configuration and only expose a development server on a trusted network. View command help Run: php thunder serve help This displays the options supported by the serve command. Stop the server Return to the terminal where the server is running and press: Ctrl+C The built in server is intended for local development and testing. Use a properly configured production web server when deploying a live application.',
            'order' => 4,
        ],
        [
            'id' => 'getting-started/installation/common-setup-problems',
            'title' => 'Common Setup Problems',
            'description' => 'Resolve common PHP, port, working-directory, and database issues encountered during installation.',
            'topic' => 'Getting Started',
            'topic_slug' => 'getting-started',
            'subtopic' => 'Installation',
            'subtopic_slug' => 'installation',
            'section_slug' => 'common-setup-problems',
            'url' => 'docs/getting-started/installation/common-setup-problems',
            'path' => 'getting-started/installation/005-common-setup-problems.md',
            'headings' => [
                'php is not recognized',
                'The thunder file cannot be found',
                'Port 8000 is already in use',
                'The page opens but a database error appears',
                'Changes are not visible',
            ],
            'keywords' => [
                'troubleshooting',
                'php not recognized',
                'port in use',
                'database connection',
                'mysql',
                'working directory',
                'serve error',
            ],
            'search_text' => 'common setup problems resolve common php, port, working-directory, and database issues encountered during installation. getting started installation php is not recognized the thunder file cannot be found port 8000 is already in use the page opens but a database error appears changes are not visible php is not recognized php is either not installed or its directory is not in your system path. when using xampp on windows, add this folder to path: c:\\xampp\\php close and reopen the terminal after changing path, then run: php v the thunder file cannot be found make sure the terminal is in the thunderphp project root. you can inspect the current folder before running the command: php thunder help if php reports that it cannot open the thunder file, change into the extracted or cloned thunderphp directory and try again. port 8000 is already in use start the server on another port: php thunder serve port=8080 you can choose another unused local port when necessary. the page opens but a database error appears check that: mysql or mariadb is running. the application is using the correct database name, username, password, host, and driver. the pdo and pdo mysql php extensions are enabled. the required plugin migrations have been run for the application. the local development server and the database server are separate processes. starting php thunder serve does not automatically start mysql. changes are not visible stop the development server with ctrl+c, start it again, and refresh the browser. also verify that you are editing the same thunderphp folder from which the server was started.',
            'plain_text' => 'php is not recognized PHP is either not installed or its directory is not in your system PATH. When using XAMPP on Windows, add this folder to PATH: C:\\xampp\\php Close and reopen the terminal after changing PATH, then run: php v The thunder file cannot be found Make sure the terminal is in the ThunderPHP project root. You can inspect the current folder before running the command: php thunder help If PHP reports that it cannot open the thunder file, change into the extracted or cloned ThunderPHP directory and try again. Port 8000 is already in use Start the server on another port: php thunder serve port=8080 You can choose another unused local port when necessary. The page opens but a database error appears Check that: MySQL or MariaDB is running. The application is using the correct database name, username, password, host, and driver. The PDO and pdo mysql PHP extensions are enabled. The required plugin migrations have been run for the application. The local development server and the database server are separate processes. Starting php thunder serve does not automatically start MySQL. Changes are not visible Stop the development server with Ctrl+C, start it again, and refresh the browser. Also verify that you are editing the same ThunderPHP folder from which the server was started.',
            'order' => 5,
        ],
        [
            'id' => 'getting-started/routing-hooks/routing-hooks-guide-overview',
