                'model',
                'getting',
                'started',
            ],
            'search_text' => 'routing & hooks guide overview understand how routes and hooks combine to form thunderphp’s execution model. getting started routing & hooks  thunderphp combines routing and hooks to build pages. routes decide when something should run. hooks decide where in the lifecycle it runs. unlike mvc frameworks where a route maps directly to a controller, thunderphp allows multiple plugins to contribute to the same request through hooks. this is what makes it powerful but also requires understanding the flow properly. core lifecycle: 1. before controller 2. controller 3. after controller 4. before view 5. view 6. after view each plugin can attach logic to any of these stages.',
            'plain_text' => 'ThunderPHP combines routing and hooks to build pages. Routes decide when something should run. Hooks decide where in the lifecycle it runs. Unlike MVC frameworks where a route maps directly to a controller, ThunderPHP allows multiple plugins to contribute to the same request through hooks. This is what makes it powerful but also requires understanding the flow properly. Core lifecycle: 1. before controller 2. controller 3. after controller 4. before view 5. view 6. after view Each plugin can attach logic to any of these stages.',
            'order' => 1,
        ],
        [
