            'search_text' => 'understanding named routes how named routes work and why they are preferred. getting started routing & hooks  named routes are defined in config.json: { "method":"get", "pattern":"/blog/{slug}", "name":"blog.view" } they allow clean targeting: add action(\'controller\', function(){ // logic }, 10, \'blog.view\'); benefits: cleaner than url segment checks easier to scale easier to debug works well with route parameters always prefer named routes for actual feature logic.',
            'plain_text' => 'Named routes are defined in config.json: { "method":"GET", "pattern":"/blog/{slug}", "name":"blog.view" } They allow clean targeting: add action(\'controller\', function(){ // logic }, 10, \'blog.view\'); Benefits: cleaner than URL segment checks easier to scale easier to debug works well with route parameters Always prefer named routes for actual feature logic.',
