            'search_text' => 'hook priority explained how execution order works and why it matters. getting started routing & hooks  hooks use priority numbers: add action(\'view\', fn() = ..., 5); add action(\'view\', fn() = ..., 10); lower number runs first. execution order: 5 runs before 10 10 runs before 20 use cases: layout first (low number) content later (default 10) overrides last (higher number) this lets you control rendering layers precisely.',
            'plain_text' => 'Hooks use priority numbers: add action(\'view\', fn() = ..., 5); add action(\'view\', fn() = ..., 10); Lower number runs first. Execution order: 5 runs before 10 10 runs before 20 Use cases: layout first (low number) content later (default 10) overrides last (higher number) This lets you control rendering layers precisely.',
            'order' => 4,
