            'search_text' => 'global vs route-based view hooks understand how view hooks behave globally and per-route. getting started routing & hooks  global view hook add action(\'view\', function(){ include current look(\'layout.php\'); }); runs on all matched routes in that plugin. route specific view hook add action(\'view\', function(){ include current look(\'post.php\'); }, 10, \'blog.view\'); runs only for that route. important rule a 404 happens only when: all view hooks are route specific none match the current route if at least one global view exists → no 404. this is critical to understand early.',
            'plain_text' => 'Global View Hook add action(\'view\', function(){ include current look(\'layout.php\'); }); Runs on ALL matched routes in that plugin. Route Specific View Hook add action(\'view\', function(){ include current look(\'post.php\'); }, 10, \'blog.view\'); Runs ONLY for that route. Important Rule A 404 happens ONLY when: all view hooks are route specific none match the current route If at least one global view exists → no 404. This is critical to understand early.',
            'order' => 5,
        ],
