            ],
            'search_text' => 'avoiding the 404 trap common mistake with route-specific view hooks. getting started routing & hooks  wrong approach: add action(\'view\', fn()= ..., 10, \'blog.index\'); add action(\'view\', fn()= ..., 10, \'blog.view\'); if route mismatch → 404. correct approach: // layout add action(\'view\', function(){ include current look(\'layout.php\'); }); // route content add action(\'view\', function(){ include current look(\'post.php\'); }, 10, \'blog.view\'); this guarantees rendering always happens.',
            'plain_text' => 'Wrong approach: add action(\'view\', fn()= ..., 10, \'blog.index\'); add action(\'view\', fn()= ..., 10, \'blog.view\'); If route mismatch → 404. Correct approach: // layout add action(\'view\', function(){ include current look(\'layout.php\'); }); // route content add action(\'view\', function(){ include current look(\'post.php\'); }, 10, \'blog.view\'); This guarantees rendering always happens.',
            'order' => 6,
        ],
