            'search_text' => 'combining layout and content best practice pattern for real plugins. getting started routing & hooks  recommended pattern: // global layout add action(\'view\', function(){ include current look(\'frontend/layout.php\'); }); // route content add action(\'view\', function(){ include current look(\'frontend/index.php\'); }, 10, \'blog.index\'); this mimics layout + page structure found in mvc frameworks but keeps flexibility of hooks.',
            'plain_text' => 'Recommended pattern: // global layout add action(\'view\', function(){ include current look(\'frontend/layout.php\'); }); // route content add action(\'view\', function(){ include current look(\'frontend/index.php\'); }, 10, \'blog.index\'); This mimics layout + page structure found in MVC frameworks but keeps flexibility of hooks.',
