            'search_text' => 'admin hooks usage correct usage of admin hooks in thunderphp. getting started routing & hooks  standard admin hooks: add filter(\'admin before links\', fn($links)= $links); add action(\'admin main content\', fn()= ...); these should not be prefixed. custom hooks should follow: pluginid hookname example: add action(\'blog after post\', fn()= ...); this avoids collisions between plugins.',
            'plain_text' => 'Standard admin hooks: add filter(\'admin before links\', fn($links)= $links); add action(\'admin main content\', fn()= ...); These should NOT be prefixed. Custom hooks should follow: pluginid hookname Example: add action(\'blog after post\', fn()= ...); This avoids collisions between plugins.',
