            'search_text' => 'mental model summary how to think about routes and hooks together. getting started routing & hooks  think of thunderphp like this: routes = entry points hooks = execution layers plugins = feature providers flow: 1. route matches 2. controller hooks run 3. view hooks build output global view = layout route view = content once this clicks, plugin development becomes much easier.',
