                'thunderphp',
                'way',
                'dev',
                'tutorials',
                'first',
            ],
            'search_text' => 'build a real plugin: overview a step-by-step walkthrough for building a reusable thunderphp plugin the thunderphp way. plugin dev tutorials build your first plugin  this guide walks through building a real thunderphp plugin using the framework\'s current patterns. the goal is not just to make a feature work, but to make it reusable across projects. in this guide, the plugin will: define its own routes create its own database tables register hooks use controller files for cleaner logic render frontend and admin views validate forms handle images paginate results this reflects thunderphp\'s design philosophy: build self contained features that can be moved between projects with minimal friction.',
            'plain_text' => 'This guide walks through building a real ThunderPHP plugin using the framework\'s current patterns. The goal is not just to make a feature work, but to make it reusable across projects. In this guide, the plugin will: define its own routes create its own database tables register hooks use controller files for cleaner logic render frontend and admin views validate forms handle images paginate results This reflects ThunderPHP\'s design philosophy: build self contained features that can be moved between projects with minimal friction.',
            'order' => 1,
        ],
        [
