            ],
            'search_text' => 'create the plugin skeleton how to start with the cli and the recommended folder structure. plugin dev tutorials build your first plugin  start with the cli: php thunder make:plugin basic blog this gives you a recommended structure that already fits thunderphp\'s normal plugin workflow. after creation, make sure the plugin has: plugin.php config.json looks/main/look.json migration, model, controller, and asset folders as needed thunderphp allows flexible layouts, but sticking to the generated structure keeps the plugin easier to maintain and aligns it with cli expectations.',
            'plain_text' => 'Start with the CLI: php thunder make:plugin basic blog This gives you a recommended structure that already fits ThunderPHP\'s normal plugin workflow. After creation, make sure the plugin has: plugin.php config.json looks/main/look.json migration, model, controller, and asset folders as needed ThunderPHP allows flexible layouts, but sticking to the generated structure keeps the plugin easier to maintain and aligns it with CLI expectations.',
