            ],
            'search_text' => 'define config and routes set up plugin metadata, activation, load order, and preferred named routes. plugin dev tutorials build your first plugin  create config.json for the plugin. example: { "name": "basic blog", "version": "1.0.0", "core requires": "^1.0.0", "id": "basic blog", "description": "a reusable blog plugin", "author": "your name", "website": "example.com", "thumbnail": "thumbnail.jpg", "active": true, "look": "main", "index": 1, "routes": { "on": ["blog", "admin"], "off": [], "routes":[ { "method":"get", "pattern":"/blog", "name":"blog.index" }, { "method":"get", "pattern":"/blog/{slug}", "name":"blog.view" }, { "method":"get", "pattern":"/admin/blog", "name":"blog.admin.index" } ] } } use named routes wherever possible. they make later hook registration much cleaner than relying only on broad first segment loading.',
            'plain_text' => 'Create config.json for the plugin. Example: { "name": "Basic Blog", "version": "1.0.0", "core requires": "^1.0.0", "id": "basic blog", "description": "A reusable blog plugin", "author": "Your Name", "website": "example.com", "thumbnail": "thumbnail.jpg", "active": true, "look": "main", "index": 1, "routes": { "on": ["blog", "admin"], "off": [], "routes":[ { "method":"GET", "pattern":"/blog", "name":"blog.index" }, { "method":"GET", "pattern":"/blog/{slug}", "name":"blog.view" }, { "method":"GET", "pattern":"/admin/blog", "name":"blog.admin.index" } ] } } Use named routes wherever possible. They make later hook registration much cleaner than relying only on broad first segment loading.',
            'order' => 3,
        ],
        [
            'id' => 'plugin-development-tutorials/build-your-first-plugin/set-plugin-context-values',
