            'search_text' => 'set plugin context values store route names, table names, and shared plugin settings for the current request. plugin dev tutorials build your first plugin  near the top of plugin.php, store shared values needed throughout the plugin. set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', \'tables\' = [ \'posts table\' = \'basic blog posts\' ] ]); this keeps paths and table names consistent across controllers, models, and views during the current page load. remember that these values do not survive redirects.',
            'plain_text' => 'Near the top of plugin.php, store shared values needed throughout the plugin. set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', \'tables\' = [ \'posts table\' = \'basic blog posts\' ] ]); This keeps paths and table names consistent across controllers, models, and views during the current page load. Remember that these values do not survive redirects.',
            'order' => 4,
        ],
        [
            'id' => 'plugin-development-tutorials/build-your-first-plugin/create-and-run-the-migration',
            'title' => 'Create and Run the Migration',
            'description' => 'Build the posts table and run it through the Thunder migration system.',
            'topic' => 'Plugin Dev Tutorials',
            'topic_slug' => 'plugin-development-tutorials',
            'subtopic' => 'Build your first plugin',
            'subtopic_slug' => 'build-your-first-plugin',
            'section_slug' => 'create-and-run-the-migration',
            'url' => 'docs/plugin-development-tutorials/build-your-first-plugin/create-and-run-the-migration',
            'path' => 'plugin-development-tutorials/build-your-first-plugin/005-create-and-run-the-migration.md',
            'headings' => [
