                'thunder',
                'system',
                'plugin',
                'dev',
                'tutorials',
                'first',
            ],
            'search_text' => 'create and run the migration build the posts table and run it through the thunder migration system. plugin dev tutorials build your first plugin  generate a migration: php thunder make:migration basic blog create posts table inside the migration: namespace migration; class create posts table extends migration { public function up() { $this addcolumn("id int unsigned not null auto increment"); $this addcolumn("title varchar(255) not null"); $this addcolumn("slug varchar(255) not null"); $this addcolumn("content longtext null"); $this addcolumn("featured image varchar(255) null"); $this addcolumn("published tinyint(1) not null default 0"); $this addcolumn("date created datetime null"); $this addprimarykey("id"); $this adduniquekey("slug", "uniq blog slug"); $this createtable("basic blog posts"); } public function down() { $this droptable("basic blog posts"); } } then run: php thunder migrate basic blog the migration system tracks runs per plugin, supports batch rollback, and resolves classes from timestamped filenames.',
            'plain_text' => 'Generate a migration: php thunder make:migration basic blog create posts table Inside the migration: namespace Migration; class Create posts table extends Migration { public function up() { $this addColumn("id INT UNSIGNED NOT NULL AUTO INCREMENT"); $this addColumn("title VARCHAR(255) NOT NULL"); $this addColumn("slug VARCHAR(255) NOT NULL"); $this addColumn("content LONGTEXT NULL"); $this addColumn("featured image VARCHAR(255) NULL"); $this addColumn("published TINYINT(1) NOT NULL DEFAULT 0"); $this addColumn("date created DATETIME NULL"); $this addPrimaryKey("id"); $this addUniqueKey("slug", "uniq blog slug"); $this createTable("basic blog posts"); } public function down() { $this dropTable("basic blog posts"); } } Then run: php thunder migrate basic blog The migration system tracks runs per plugin, supports batch rollback, and resolves classes from timestamped filenames.',
            'order' => 5,
        ],
        [
