            'search_text' => 'write hook-driven controllers register controller hooks and move heavy logic into included files when needed. plugin dev tutorials build your first plugin  thunderphp controllers are execution blocks, not necessarily mvc controller classes. in plugin.php, register route scoped controller logic: add action(\'controller\', function($data){ include plugin path(\'controllers/frontend/blog index.php\'); }, 10, \'blog.index\'); add action(\'controller\', function($data){ include plugin path(\'controllers/frontend/blog view.php\'); }, 10, \'blog.view\'); for admin routes: add action(\'controller\', function($data){ include plugin path(\'controllers/admin/blog admin.php\'); }, 10, \'blog.admin.index\'); this keeps plugin.php readable while staying within thunderphp\'s hook driven lifecycle.',
            'plain_text' => 'ThunderPHP controllers are execution blocks, not necessarily MVC controller classes. In plugin.php, register route scoped controller logic: add action(\'controller\', function($data){ include plugin path(\'controllers/frontend/blog index.php\'); }, 10, \'blog.index\'); add action(\'controller\', function($data){ include plugin path(\'controllers/frontend/blog view.php\'); }, 10, \'blog.view\'); For admin routes: add action(\'controller\', function($data){ include plugin path(\'controllers/admin/blog admin.php\'); }, 10, \'blog.admin.index\'); This keeps plugin.php readable while staying within ThunderPHP\'s hook driven lifecycle.',
