            'search_text' => 'query data the modern way use the updated query builder or database class to fetch and save plugin data. plugin dev tutorials build your first plugin  use the updated query builder where it improves clarity. example list query: $postmodel = new post; $posts = $postmodel select(\'id\', \'title\', \'slug\', \'date created\') where(\'published\', 1) orderby(\'date created\', \'desc\') paginate(10, $ get[\'page\'] ?? 1); example single post: $post = $postmodel where(\'slug\', get param(\'slug\')) where(\'published\', 1) first(); the updated builder supports joins, nested conditions, raw clauses, pagination metadata, aggregates, unions, upserts, and more, so plugin authors no longer need to fall back to raw sql for every non trivial query.',
            'plain_text' => 'Use the updated query builder where it improves clarity. Example list query: $postModel = new Post; $posts = $postModel select(\'id\', \'title\', \'slug\', \'date created\') where(\'published\', 1) orderBy(\'date created\', \'DESC\') paginate(10, $ GET[\'page\'] ?? 1); Example single post: $post = $postModel where(\'slug\', get param(\'slug\')) where(\'published\', 1) first(); The updated builder supports joins, nested conditions, raw clauses, pagination metadata, aggregates, unions, upserts, and more, so plugin authors no longer need to fall back to raw SQL for every non trivial query.',
            'order' => 7,
