            'search_text' => 'render frontend views through looks output frontend templates using the current look system. plugin dev tutorials build your first plugin  register a view hook for output: add action(\'view\', function($data){ include current look(\'frontend/index.php\'); }, 10, \'blog.index\'); add action(\'view\', function($data){ include current look(\'frontend/view.php\'); }, 10, \'blog.view\'); this gives the plugin a clean separation between controller processing and final output. it also allows the plugin to support alternate looks later without rewriting business logic.',
