            'search_text' => 'add admin integration hook the plugin into an admin plugin and render admin content the expected way. plugin dev tutorials build your first plugin  many thunderphp projects use a plugin based admin system. add a sidebar link: add filter(\'admin before links\', function($links){ $vars = get value(); $obj = (object)[]; $obj title = \'blog\'; $obj link = root . \'/\'.$vars[\'admin route\'].\'/\'.$vars[\'plugin route\']; $obj icon = \'fa solid fa newspaper\'; $obj parent = 0; $links[] = $obj; return $links; }); render the admin page: add action(\'admin main content\', function($data){ include current look(\'admin/index.php\'); }, 10, \'blog.admin.index\'); this is a good example of how thunderphp plugins compose with each other through hooks instead of depending on a fixed admin panel.',
            'plain_text' => 'Many ThunderPHP projects use a plugin based admin system. Add a sidebar link: add filter(\'admin before links\', function($links){ $vars = get value(); $obj = (object)[]; $obj title = \'Blog\'; $obj link = ROOT . \'/\'.$vars[\'admin route\'].\'/\'.$vars[\'plugin route\']; $obj icon = \'fa solid fa newspaper\'; $obj parent = 0; $links[] = $obj; return $links; }); Render the admin page: add action(\'admin main content\', function($data){ include current look(\'admin/index.php\'); }, 10, \'blog.admin.index\'); This is a good example of how ThunderPHP plugins compose with each other through hooks instead of depending on a fixed admin panel.',
