            'search_text' => 'validate form data use the newer validate class properly in plugin forms. plugin dev tutorials build your first plugin  when saving posts, validate the input before inserting or updating. $req = new \\core\\request; $validate = new \\core\\validate($req post()); $validate setrules([ \'title\' = [ \'name\' = \'title\', \'rules\' = [\'required\', \'min:3\', \'max:255\'] ], \'slug\' = [ \'name\' = \'slug\', \'rules\' = [ \'required\', [ \'rule\' = \'unique\', \'table\' = \'basic blog posts\', \'column\' = \'slug\', \'where\' = [ \'deleted\' = 0 ] ] ] ] ]); if($validate fails()) { set value(\'errors\', $validate geterrors()); } the updated validator supports richer unique logic, including where and wherenot, which is useful for soft deletes and edit forms.',
            'plain_text' => 'When saving posts, validate the input before inserting or updating. $req = new \\Core\\Request; $validate = new \\Core\\Validate($req post()); $validate setRules([ \'title\' = [ \'name\' = \'Title\', \'rules\' = [\'required\', \'min:3\', \'max:255\'] ], \'slug\' = [ \'name\' = \'Slug\', \'rules\' = [ \'required\', [ \'rule\' = \'unique\', \'table\' = \'basic blog posts\', \'column\' = \'slug\', \'where\' = [ \'deleted\' = 0 ] ] ] ] ]); if($validate fails()) { set value(\'errors\', $validate getErrors()); } The updated validator supports richer unique logic, including where and whereNot, which is useful for soft deletes and edit forms.',
