            'search_text' => 'handle uploads and images use request and image together for featured images and media-friendly plugins. plugin dev tutorials build your first plugin  for a featured image upload, combine request and image. $req = new \\core\\request; $files = $req upload files(\'featured image\'); if(!$req has upload errors()) { $image = new \\core\\image; $image set webp quality(80); $image resize(rootpath . $files[\'featured image\'][\'full path\'], 1600); $thumb = $image get thumbnail(rootpath . $files[\'featured image\'][\'full path\'], 600, 400); } the current request layer supports structured upload rules and grouped results, while the current image class supports resize, crop, contain fit, conversions, thumbnail generation, and output workflows.',
            'plain_text' => 'For a featured image upload, combine Request and Image. $req = new \\Core\\Request; $files = $req upload files(\'featured image\'); if(!$req has upload errors()) { $image = new \\Core\\Image; $image set webp quality(80); $image resize(ROOTPATH . $files[\'featured image\'][\'full path\'], 1600); $thumb = $image get thumbnail(ROOTPATH . $files[\'featured image\'][\'full path\'], 600, 400); } The current Request layer supports structured upload rules and grouped results, while the current Image class supports resize, crop, contain fit, conversions, thumbnail generation, and output workflows.',
