            'search_text' => 'paginate the post list use the current pager class to keep list pages in sync with the query. plugin dev tutorials build your first plugin  you can use the dedicated pager class directly, or use query builder pagination metadata where that fits better. direct pager example: $total rows = 125; $pager = new \\core\\pager(10, 2, $total rows); $rows = $db query("select from basic blog posts limit {$pager limit()} offset {$pager offset()}"); foreach($rows as $row) { echo $row title . ""; } $pager display(); the current pager supports render(), display(), has prev(), has next(), current page detection from the query string, and custom layout strategies when you do not want the default html output.',
            'plain_text' => 'You can use the dedicated Pager class directly, or use query builder pagination metadata where that fits better. Direct Pager example: $total rows = 125; $pager = new \\Core\\Pager(10, 2, $total rows); $rows = $db query("select from basic blog posts limit {$pager limit()} offset {$pager offset()}"); foreach($rows as $row) { echo $row title . ""; } $pager display(); The current Pager supports render(), display(), has prev(), has next(), current page detection from the query string, and custom layout strategies when you do not want the default HTML output.',
