            'search_text' => 'permissions and role-aware admin features add capability checks so the plugin can be reused in different projects safely. plugin dev tutorials build your first plugin  register the plugin\'s permissions: add filter(\'permissions\', function($permissions){ $permissions[] = \'view blog posts\'; $permissions[] = \'add blog post\'; $permissions[] = \'edit blog post\'; $permissions[] = \'delete blog post\'; return $permissions; }); then check them: if(!user can(\'add blog post\')) { message(\'fail\', \'you do not have permission\'); redirect(\'admin/blog\'); } this keeps the plugin reusable across many projects with different role and permission systems.',
            'plain_text' => 'Register the plugin\'s permissions: add filter(\'permissions\', function($permissions){ $permissions[] = \'view blog posts\'; $permissions[] = \'add blog post\'; $permissions[] = \'edit blog post\'; $permissions[] = \'delete blog post\'; return $permissions; }); Then check them: if(!user can(\'add blog post\')) { message(\'fail\', \'You do not have permission\'); redirect(\'admin/blog\'); } This keeps the plugin reusable across many projects with different role and permission systems.',
