                'plugins',
                'plugin',
                'dev',
                'tutorials',
                'build',
                'first',
                'always',
                'provide',
                'view',
                'hook',
                'routes',
                'end',
                'non-view',
                'explicitly',
            ],
            'search_text' => 'avoid the 404 trap and other real-world tips common guide-level mistakes and how to avoid them in real plugins. plugin dev tutorials build your first plugin  always provide a view hook for view routes if a route is meant to show html, make sure the relevant view or admin content hook actually runs. otherwise the framework may treat the route as unresolved and trigger 404 fallback handling. end non view routes explicitly for json or ajax only routes, output the response and end the request. use included controller files for large logic thunderphp encourages hook driven controllers, but large procedural blocks should still be split into included files. prefer current class behavior build new plugins using the updated request, image, pager, validate, migration, and query builder docs rather than relying on older class summaries. think in reusable features if a piece of code might be useful in another project, it probably belongs in the plugin instead of being spread across the app.',
            'plain_text' => 'Always Provide a View Hook for View Routes If a route is meant to show HTML, make sure the relevant view or admin content hook actually runs. Otherwise the framework may treat the route as unresolved and trigger 404 fallback handling. End Non View Routes Explicitly For JSON or AJAX only routes, output the response and end the request. Use Included Controller Files for Large Logic ThunderPHP encourages hook driven controllers, but large procedural blocks should still be split into included files. Prefer Current Class Behavior Build new plugins using the updated Request, Image, Pager, Validate, migration, and query builder docs rather than relying on older class summaries. Think in Reusable Features If a piece of code might be useful in another project, it probably belongs in the plugin instead of being spread across the app.',
            'order' => 14,
        ],
        [
            'id' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/thunderphp-plugin-development-overview',
            'title' => 'ThunderPHP Plugin Development Overview',
            'description' => 'What ThunderPHP is, why it exists, and how plugin development differs from plain MVC or WordPress.',
            'topic' => 'Plugin Reference',
            'topic_slug' => 'plugin-reference',
            'subtopic' => 'A refrence for ThunderPHP plugin developers',
            'subtopic_slug' => 'a-refrence-for-thunderphp-plugin-developers',
            'section_slug' => 'thunderphp-plugin-development-overview',
            'url' => 'docs/plugin-reference/a-refrence-for-thunderphp-plugin-developers/thunderphp-plugin-development-overview',
            'path' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/001-thunderphp-plugin-development-overview.md',
            'headings' => [
            ],
            'keywords' => [
                'thunderphp',
                'plugin',
                'development',
                'overview',
                'why',
                'exists',
                'differs',
                'plain',
                'mvc',
                'wordpress',
                'reference',
                'refrence',
                'developers',
                'think',
                'about',
            ],
            'search_text' => 'thunderphp plugin development overview what thunderphp is, why it exists, and how plugin development differs from plain mvc or wordpress. plugin reference a refrence for thunderphp plugin developers  thunderphp is a plugin based php framework that sits between a traditional mvc framework and a wordpress style modular system. the goal is to combine two things: the re usability and switchable feature model of plugins the control and freedom of a framework in thunderphp, a feature is usually built as a self contained plugin. that plugin can then be reused in many projects, turned on or off, migrated independently, and extended through hooks. why thunderphp exists thunderphp was designed to solve problems common in ordinary mvc projects: features are often tightly coupled to the app reusing a full feature in another project is harder than it should be turning a feature off usually means editing many files adding new features often means touching unrelated code it also addresses limitations common in cms driven systems: database structure is not imposed by the core authentication, admin systems, and user tables can be designed by plugin authors developers keep low level control instead of inheriting a fixed app structure in short, thunderphp aims to deliver the power of plugins with the independence of a framework. how to think about it thunderphp is not a strict mvc framework. it is better described as a hook driven modular framework with optional mvc style organization. that means: plugins are the main unit of re use hooks are the main communication layer controllers are execution blocks, not necessarily controller classes the database is defined by plugins, not by the core a developer is free to write class based controllers and richer architecture when needed, but the framework does not force that model.',
            'plain_text' => 'ThunderPHP is a plugin based PHP framework that sits between a traditional MVC framework and a WordPress style modular system. The goal is to combine two things: the re usability and switchable feature model of plugins the control and freedom of a framework In ThunderPHP, a feature is usually built as a self contained plugin. That plugin can then be reused in many projects, turned on or off, migrated independently, and extended through hooks. Why ThunderPHP Exists ThunderPHP was designed to solve problems common in ordinary MVC projects: features are often tightly coupled to the app reusing a full feature in another project is harder than it should be turning a feature off usually means editing many files adding new features often means touching unrelated code It also addresses limitations common in CMS driven systems: database structure is not imposed by the core authentication, admin systems, and user tables can be designed by plugin authors developers keep low level control instead of inheriting a fixed app structure In short, ThunderPHP aims to deliver the power of plugins with the independence of a framework. How To Think About It ThunderPHP is not a strict MVC framework. It is better described as a hook driven modular framework with optional MVC style organization. That means: plugins are the main unit of re use hooks are the main communication layer controllers are execution blocks, not necessarily controller classes the database is defined by plugins, not by the core A developer is free to write class based controllers and richer architecture when needed, but the framework does not force that model.',
            'order' => 1,
        ],
        [
            'id' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/recommended-plugin-structure',
            'title' => 'Recommended Plugin Structure',
            'description' => 'Best-practice folder structure for ThunderPHP plugins and what each folder is for.',
            'topic' => 'Plugin Reference',
            'topic_slug' => 'plugin-reference',
            'subtopic' => 'A refrence for ThunderPHP plugin developers',
            'subtopic_slug' => 'a-refrence-for-thunderphp-plugin-developers',
            'section_slug' => 'recommended-plugin-structure',
            'url' => 'docs/plugin-reference/a-refrence-for-thunderphp-plugin-developers/recommended-plugin-structure',
            'path' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/002-recommended-plugin-structure.md',
            'headings' => [
