            'search_text' => 'required files and plugin metadata reference for plugin.php, config.json, look.json, and the main metadata rules. plugin reference a refrence for thunderphp plugin developers  the main files expected in normal plugin development are: plugin.php config.json look.json inside each look folder plugin.php this is where the plugin registers hooks using add action() and add filter(). config.json this file defines metadata and route loading rules. example: { "name": "basic blog", "version": "1.0.0", "core requires": "^1.0.0", "id": "basic blog", "description": "a basic but complete blogging system", "author": "eathorne choongo", "website": "thunderphp.com", "thumbnail": "thumbnail.jpg", "active": true, "look": "main", "index": 1, "routes": { "on": ["products", "admin", "home"], "off": ["login", "logout"], "routes":[ { "method":"get", "pattern":"/", "name":"home.index" }, { "method":"get", "pattern":"/post/{slug}", "name":"post.view" } ] }, "dependencies": { "basic admin":{ "name":"basic admin", "version":"1.0.0", "required":false } } } key metadata rules plugin id must be unique lower index values load earlier core requires describes compatible framework versions look selects the active look folder dependencies can describe plugin requirements or optional integrations look.json each look should define itself with a look.json file. { "name": "dark theme", "version": "1.0.0", "plugin": "plugin id", "plugin requires": "^1.2", "author": "your name", "thumbnail": "screenshot.png", "description": "a dark look for the plugin" } this helps keeps alternate looks explicit and easier to manage.',
            'plain_text' => 'The main files expected in normal plugin development are: plugin.php config.json look.json inside each look folder plugin.php This is where the plugin registers hooks using add action() and add filter(). config.json This file defines metadata and route loading rules. Example: { "name": "Basic Blog", "version": "1.0.0", "core requires": "^1.0.0", "id": "basic blog", "description": "A basic but complete blogging system", "author": "Eathorne Choongo", "website": "thunderphp.com", "thumbnail": "thumbnail.jpg", "active": true, "look": "main", "index": 1, "routes": { "on": ["products", "admin", "home"], "off": ["login", "logout"], "routes":[ { "method":"GET", "pattern":"/", "name":"home.index" }, { "method":"GET", "pattern":"/post/{slug}", "name":"post.view" } ] }, "dependencies": { "basic admin":{ "name":"Basic Admin", "version":"1.0.0", "required":false } } } Key Metadata Rules plugin id must be unique lower index values load earlier core requires describes compatible framework versions look selects the active look folder dependencies can describe plugin requirements or optional integrations look.json Each look should define itself with a look.json file. { "name": "Dark Theme", "version": "1.0.0", "plugin": "plugin id", "plugin requires": "^1.2", "author": "Your Name", "thumbnail": "screenshot.png", "description": "A dark look for the plugin" } This helps keeps alternate looks explicit and easier to manage.',
            'order' => 3,
        ],
        [
            'id' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/routing-in-thunderphp',
            'title' => 'Routing in ThunderPHP',
            'description' => 'How coarse route loading and named clean routes work, and which approach is preferred.',
            'topic' => 'Plugin Reference',
            'topic_slug' => 'plugin-reference',
            'subtopic' => 'A refrence for ThunderPHP plugin developers',
            'subtopic_slug' => 'a-refrence-for-thunderphp-plugin-developers',
            'section_slug' => 'routing-in-thunderphp',
            'url' => 'docs/plugin-reference/a-refrence-for-thunderphp-plugin-developers/routing-in-thunderphp',
            'path' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/004-routing-in-thunderphp.md',
            'headings' => [
            ],
            'keywords' => [
                'routing',
