                'off',
                'fine-grained',
                'prefer',
                'parameters',
            ],
            'search_text' => 'routing in thunderphp how coarse route loading and named clean routes work, and which approach is preferred. plugin reference a refrence for thunderphp plugin developers  thunderphp supports two route loading layers in plugins. 1. coarse loading with routes.on and routes.off these affect plugin loading based on the first url segment only. for example, if products is in routes.on, the plugin loads for urls that begin with /products/.... this is simple and still supported. 2. fine grained named routes with routes.routes this is the cleaner and preferred approach. example: "routes":[ { "method":"get", "pattern":"/", "name":"home.index" }, { "method":"get", "pattern":"/post/{slug}", "name":"post.view" } ] these named routes can then be used in hook registration or route checks. add action(\'controller\', function($data){ // controller logic }, 10, \'post.view\'); or: if(is route(\'post.view\')) { // route specific logic } which should you prefer? both systems work, but routes.routes is preferred because it is cleaner, more explicit, and easier to reason about in larger plugins. routes.on and routes.off are still useful for broad load control. route parameters if a route contains placeholders such as {slug} or {id}, their values can be read with get param(). $slug = get param(\'slug\');',
            'plain_text' => 'ThunderPHP supports two route loading layers in plugins. 1. Coarse Loading With routes.on and routes.off These affect plugin loading based on the first URL segment only. For example, if products is in routes.on, the plugin loads for URLs that begin with /products/.... This is simple and still supported. 2. Fine Grained Named Routes With routes.routes This is the cleaner and preferred approach. Example: "routes":[ { "method":"GET", "pattern":"/", "name":"home.index" }, { "method":"GET", "pattern":"/post/{slug}", "name":"post.view" } ] These named routes can then be used in hook registration or route checks. add action(\'controller\', function($data){ // controller logic }, 10, \'post.view\'); Or: if(is route(\'post.view\')) { // route specific logic } Which Should You Prefer? Both systems work, but routes.routes is preferred because it is cleaner, more explicit, and easier to reason about in larger plugins. routes.on and routes.off are still useful for broad load control. Route Parameters If a route contains placeholders such as {slug} or {id}, their values can be read with get param(). $slug = get param(\'slug\');',
            'order' => 4,
        ],
        [
