                'practice',
            ],
            'search_text' => 'hooks, actions, and filters how plugins register behavior and how route-scoped hooks work. plugin reference a refrence for thunderphp plugin developers  thunderphp plugins interact with the core through two global functions: add action(\'hook name\', function($data) {}, int $priority = 10, string $route = \'\'): void add filter(\'hook name\', function($data) { return $data; }, int $priority = 10, string $route = \'\'): void rules actions do not need to return anything filters must return the modified data lower priority numbers run first the optional route parameter limits the callback to a named route what this means in practice instead of directly wiring features together, plugins expose and consume behavior through hook points. example filter: add filter(\'permissions\', function($permissions){ $permissions[] = \'view posts\'; $permissions[] = \'add post\'; return $permissions; }); example action: add action(\'controller\', function($data){ // process request }, 10, \'post.view\'); this makes plugins easier to turn on, turn off, and reuse without editing many unrelated files.',
            'plain_text' => 'ThunderPHP plugins interact with the core through two global functions: add action(\'hook name\', function($data) {}, int $priority = 10, string $route = \'\'): void add filter(\'hook name\', function($data) { return $data; }, int $priority = 10, string $route = \'\'): void Rules actions do not need to return anything filters must return the modified data lower priority numbers run first the optional route parameter limits the callback to a named route What This Means In Practice Instead of directly wiring features together, plugins expose and consume behavior through hook points. Example filter: add filter(\'permissions\', function($permissions){ $permissions[] = \'view posts\'; $permissions[] = \'add post\'; return $permissions; }); Example action: add action(\'controller\', function($data){ // process request }, 10, \'post.view\'); This makes plugins easier to turn on, turn off, and reuse without editing many unrelated files.',
            'order' => 5,
        ],
        [
            'id' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/execution-lifecycle-and-404-behavior',
            'title' => 'Execution Lifecycle and 404 Behavior',
            'description' => 'The main execution order, intended 404 safeguard, and how plugin authors can override it.',
            'topic' => 'Plugin Reference',
            'topic_slug' => 'plugin-reference',
            'subtopic' => 'A refrence for ThunderPHP plugin developers',
            'subtopic_slug' => 'a-refrence-for-thunderphp-plugin-developers',
            'section_slug' => 'execution-lifecycle-and-404-behavior',
            'url' => 'docs/plugin-reference/a-refrence-for-thunderphp-plugin-developers/execution-lifecycle-and-404-behavior',
            'path' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/006-execution-lifecycle-and-404-behavior.md',
            'headings' => [
            ],
            'keywords' => [
                'execution',
                'lifecycle',
                'behavior',
                'main',
                'order',
                'intended',
                'safeguard',
                'plugin',
                'authors',
                'override',
                'reference',
                'refrence',
                'thunderphp',
                'developers',
                'controllers',
                'blocks',
                'hook',
                'views',
            ],
            'search_text' => 'execution lifecycle and 404 behavior the main execution order, intended 404 safeguard, and how plugin authors can override it. plugin reference a refrence for thunderphp plugin developers  the core hook order is: 1. roles 2. permissions 3. before controller 4. controller 5. after controller 6. before view 7. view 8. after view this is the normal request lifecycle thunderphp expects plugins to work within. controllers are execution blocks in thunderphp, controllers are not necessarily mvc controller classes. they are usually hook driven execution blocks, often plain procedural code. for larger plugins, it is perfectly fine to include controller files from controllers/admin or controllers/frontend to keep plugin.php clean. 404 safeguard if no view hook is defined or run for the matched route, the framework treats that as a missing view and loads the 404 flow. this is an intended safeguard. for routes that intentionally return json, files, or other direct output, it is normal to end the request with die() or exit() to avoid falling into the 404 behavior. override hook the newer framework behavior adds: do action(\'before 404 redirect\'); this gives plugin authors an easier interception point before the redirect or fallback 404 handling occurs. plugin 404 views if no plugin provides a custom 404 view, the framework falls back to the default 404 view. if a plugin defines its own 404 rendering for that route, the plugin version is used instead.',
            'plain_text' => 'The core hook order is: 1. roles 2. permissions 3. before controller 4. controller 5. after controller 6. before view 7. view 8. after view This is the normal request lifecycle ThunderPHP expects plugins to work within. Controllers Are Execution Blocks In ThunderPHP, controllers are not necessarily MVC controller classes. They are usually hook driven execution blocks, often plain procedural code. For larger plugins, it is perfectly fine to include controller files from controllers/admin or controllers/frontend to keep plugin.php clean. 404 Safeguard If no view hook is defined or run for the matched route, the framework treats that as a missing view and loads the 404 flow. This is an intended safeguard. For routes that intentionally return JSON, files, or other direct output, it is normal to end the request with die() or exit() to avoid falling into the 404 behavior. Override Hook The newer framework behavior adds: do action(\'before 404 redirect\'); This gives plugin authors an easier interception point before the redirect or fallback 404 handling occurs. Plugin 404 Views If no plugin provides a custom 404 view, the framework falls back to the default 404 view. If a plugin defines its own 404 rendering for that route, the plugin version is used instead.',
            'order' => 6,
        ],
