            'search_text' => 'looks, views, and asset paths how thunderphp handles looks, templates, and look-specific asset loading. plugin reference a refrence for thunderphp plugin developers  a plugin can contain multiple looks. a look is a complete view set stored under the plugin\'s looks/ directory. the active look is selected through plugin metadata, and helper functions resolve the correct files. filesystem path to a view include current look(\'frontend/header.php\'); current look() returns the full filesystem path inside the currently active look folder. http path to look assets',
            'plain_text' => 'A plugin can contain multiple looks. A look is a complete view set stored under the plugin\'s looks/ directory. The active look is selected through plugin metadata, and helper functions resolve the correct files. Filesystem Path to a View include current look(\'frontend/header.php\'); current look() returns the full filesystem path inside the currently active look folder. HTTP Path to Look Assets',
