                'plugin',
                'reference',
                'refrence',
                'thunderphp',
                'developers',
            ],
            'search_text' => 'page-load data and app context how to share request-lifetime values with set_value, get_value, app, and app_set. plugin reference a refrence for thunderphp plugin developers  thunderphp includes helpers for storing data for the current request only. set value() and get value() set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', \'tables\' = [ \'posts table\' = \'bb posts\' ] ]); later: $vars = get value(); $plugin route = get value(\'plugin route\'); these values exist only during the current page load. they do not persist across redirects. app() and app set() app() returns app wide information for the current page load, such as context, loaded plugins, permissions, roles, and compatibility information. app set() lets you add page load app data without storing it in session state. when to use which use set value() for plugin local request data use app set() for broader app context during the current request do not rely on either one after redirects',
            'plain_text' => 'ThunderPHP includes helpers for storing data for the current request only. set value() and get value() set value([ \'plugin route\' = \'blog\', \'admin route\' = \'admin\', \'tables\' = [ \'posts table\' = \'bb posts\' ] ]); Later: $vars = get value(); $plugin route = get value(\'plugin route\'); These values exist only during the current page load. They do not persist across redirects. APP() and APP SET() APP() returns app wide information for the current page load, such as context, loaded plugins, permissions, roles, and compatibility information. APP SET() lets you add page load app data without storing it in session state. When To Use Which use set value() for plugin local request data use APP SET() for broader app context during the current request do not rely on either one after redirects',
            'order' => 8,
        ],
        [
            'id' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/database-and-query-builder-in-plugins',
            'title' => 'Database and Query Builder in Plugins',
            'description' => 'How plugin authors should use the Database and newer QueryBuilder features.',
            'topic' => 'Plugin Reference',
