            ],
            'search_text' => 'database and query builder in plugins how plugin authors should use the database and newer querybuilder features. plugin reference a refrence for thunderphp plugin developers  thunderphp plugins can use the database in two broad ways: raw sql through \\core\\database fluent query building through the updated querybuilder api database basics $db = new \\core\\database; $rows = $db query("select from posts where active = :active", [\'active\' = 1]); $row = $db get row("select from posts where id = :id limit 1", [\'id\' = 5]); useful properties include: has error error insert id affected rows static query id for after query customization updated query builder the newer query builder supports fluent select, insert, update, delete, joins, grouped conditions, aggregates, pagination metadata, unions, raw expressions, subqueries, upserts, and error tracking. results are returned as an array of objects, a single object, or null depending on the query path. example: $postmodel = new post; $posts = $postmodel select(\'id\', \'title\', \'slug\') where(\'published\', 1) orderby(\'date created\', \'desc\') paginate(20, $ get[\'page\'] ?? 1); why this matters for plugin docs older thunderphp docs that treat the database layer as mostly raw sql are incomplete now. plugin authors can build much richer plugin data access with the updated builder api and should be encouraged to do so where it improves clarity.',
            'plain_text' => 'ThunderPHP plugins can use the database in two broad ways: raw SQL through \\Core\\Database fluent query building through the updated QueryBuilder API Database Basics $db = new \\Core\\Database; $rows = $db query("select from posts where active = :active", [\'active\' = 1]); $row = $db get row("select from posts where id = :id limit 1", [\'id\' = 5]); Useful properties include: has error error insert id affected rows static query id for after query customization Updated Query Builder The newer query builder supports fluent select, insert, update, delete, joins, grouped conditions, aggregates, pagination metadata, unions, raw expressions, subqueries, upserts, and error tracking. Results are returned as an array of objects, a single object, or null depending on the query path. Example: $postModel = new Post; $posts = $postModel select(\'id\', \'title\', \'slug\') where(\'published\', 1) orderBy(\'date created\', \'DESC\') paginate(20, $ GET[\'page\'] ?? 1); Why This Matters For Plugin Docs Older ThunderPHP docs that treat the database layer as mostly raw SQL are incomplete now. Plugin authors can build much richer plugin data access with the updated builder API and should be encouraged to do so where it improves clarity.',
            'order' => 9,
        ],
        [
