            ],
            'search_text' => 'request handling and file uploads current request class behavior for methods, input reading, and modern upload workflows. plugin reference a refrence for thunderphp plugin developers  the \\core\\request class is now more capable than the older summary docs suggested. it covers: method detection $ post, $ get, $ files, and $ request request metadata structured uploads with validation support core method helpers method() posted() is get() is ajax() reading input post() input() get() files() all() example: $req = new \\core\\request; if($req posted()) { $title = $req post(\'title\'); $slug = $req post(\'slug\', \'\'); } uploads upload files() supports: single file uploads multiple uploads using fields like photos[] all fields at once per field rules mime checks extension checks optional image validation optional image dimension limits grouped upload results the upload shape is normalized internally so plugin authors do not have to manually untangle raw $ files structures in normal use. error checking should still be done through upload error helpers before assuming a file was stored successfully.',
            'plain_text' => 'The \\Core\\Request class is now more capable than the older summary docs suggested. It covers: method detection $ POST, $ GET, $ FILES, and $ REQUEST request metadata structured uploads with validation support Core Method Helpers method() posted() is get() is ajax() Reading Input post() input() get() files() all() Example: $req = new \\Core\\Request; if($req posted()) { $title = $req post(\'title\'); $slug = $req post(\'slug\', \'\'); } Uploads upload files() supports: single file uploads multiple uploads using fields like photos[] all fields at once per field rules MIME checks extension checks optional image validation optional image dimension limits grouped upload results The upload shape is normalized internally so plugin authors do not have to manually untangle raw $ FILES structures in normal use. Error checking should still be done through upload error helpers before assuming a file was stored successfully.',
            'order' => 10,
