            'search_text' => 'validation in real plugins current validate class capabilities, including hooks, custom rules, and unique constraints with where and wherenot. plugin reference a refrence for thunderphp plugin developers  thunderphp uses \\core\\validate for structured request validation. the newer validation documentation shows support for: built in scalar rules file and image validation custom rules through hooks static rule registration advanced unique rules with where and wherenot support example: $validate = new \\core\\validate($ post); $validate setrules([ \'username\' = [ \'name\' = \'username\', \'rules\' = [\'required\', \'alpha numeric\', \'min:3\', \'max:20\'] ], \'email\' = [ \'name\' = \'email address\', \'rules\' = [\'required\', \'email\'] ], ]); if($validate validate()) { // valid } else { $errors = $validate geterrors(); } important plugin author features firsterror() for field specific display fails() for failure checks validation rules filter for hook based custom rules \\core\\validate::extend() for static rule registration where and wherenot for soft delete aware uniqueness logic recommendation prefer extending validation through hooks or registration methods instead of modifying the validator class directly.',
            'plain_text' => 'ThunderPHP uses \\Core\\Validate for structured request validation. The newer validation documentation shows support for: built in scalar rules file and image validation custom rules through hooks static rule registration advanced unique rules with where and whereNot support Example: $validate = new \\Core\\Validate($ POST); $validate setRules([ \'username\' = [ \'name\' = \'Username\', \'rules\' = [\'required\', \'alpha numeric\', \'min:3\', \'max:20\'] ], \'email\' = [ \'name\' = \'Email address\', \'rules\' = [\'required\', \'email\'] ], ]); if($validate validate()) { // valid } else { $errors = $validate getErrors(); } Important Plugin Author Features firstError() for field specific display fails() for failure checks validation rules filter for hook based custom rules \\Core\\Validate::extend() for static rule registration where and whereNot for soft delete aware uniqueness logic Recommendation Prefer extending validation through hooks or registration methods instead of modifying the validator class directly.',
