            ],
            'search_text' => 'images and media workflows current image class features for resizing, cropping, thumbnails, conversion, and browser output. plugin reference a refrence for thunderphp plugin developers  the current \\core\\image class is much more capable than a simple resize helper. it supports: proportional resize exact crop contain fit inside a box save as conversion webp conversion single thumbnail generation bulk thumbnail generation uploaded image processing building files from binary strings direct browser output configuration methods set jpeg quality() set png compression() set webp quality() allow upscale() set thumbnail dir() use hashed names() choosing the right method use resize() for proportional downscaling use crop() for fixed rectangles such as avatars or cards use fit contain() when the full image must remain visible, such as logos or admin previews this makes the image class especially useful inside upload pipelines, media libraries, blog plugins, and admin systems.',
            'plain_text' => 'The current \\Core\\Image class is much more capable than a simple resize helper. It supports: proportional resize exact crop contain fit inside a box save as conversion WebP conversion single thumbnail generation bulk thumbnail generation uploaded image processing building files from binary strings direct browser output Configuration Methods set jpeg quality() set png compression() set webp quality() allow upscale() set thumbnail dir() use hashed names() Choosing the Right Method use resize() for proportional downscaling use crop() for fixed rectangles such as avatars or cards use fit contain() when the full image must remain visible, such as logos or admin previews This makes the Image class especially useful inside upload pipelines, media libraries, blog plugins, and admin systems.',
            'order' => 12,
