            'id' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/pagination-in-plugin-uis',
            'title' => 'Pagination in Plugin UIs',
            'description' => 'Current Pager class behavior, constructor options, rendering methods, and custom markup strategy.',
            'topic' => 'Plugin Reference',
            'topic_slug' => 'plugin-reference',
            'subtopic' => 'A refrence for ThunderPHP plugin developers',
            'subtopic_slug' => 'a-refrence-for-thunderphp-plugin-developers',
