                'reference',
                'refrence',
                'thunderphp',
                'developers',
                'output',
            ],
            'search_text' => 'pagination in plugin uis current pager class behavior, constructor options, rendering methods, and custom markup strategy. plugin reference a refrence for thunderphp plugin developers  the current \\core\\pager class is a full pagination utility, not just an offset helper. it handles: current page detection offset and limit calculation previous and next state html output custom render control constructor $pager = new \\core\\pager($limit, $extras, $total rows); limit: records per page extras: page numbers around the current page total rows: total result count the current page is read from the page query parameter and sanitized so missing or invalid page values fall back safely to page 1. output methods display() echoes the pager html render() returns the html string plugin authors who want custom markup can build their own layout while still using pager methods like has prev() and has next().',
            'plain_text' => 'The current \\Core\\Pager class is a full pagination utility, not just an offset helper. It handles: current page detection offset and limit calculation previous and next state HTML output custom render control Constructor $pager = new \\Core\\Pager($limit, $extras, $total rows); limit: records per page extras: page numbers around the current page total rows: total result count The current page is read from the page query parameter and sanitized so missing or invalid page values fall back safely to page 1. Output Methods display() echoes the pager HTML render() returns the HTML string Plugin authors who want custom markup can build their own layout while still using pager methods like has prev() and has next().',
            'order' => 13,
        ],
