            'id' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/roles-permissions-and-access-checks',
            'title' => 'Roles, Permissions, and Access Checks',
            'description' => 'How plugins define permissions and role-aware behavior.',
            'topic' => 'Plugin Reference',
            'topic_slug' => 'plugin-reference',
            'subtopic' => 'A refrence for ThunderPHP plugin developers',
            'subtopic_slug' => 'a-refrence-for-thunderphp-plugin-developers',
            'section_slug' => 'roles-permissions-and-access-checks',
            'url' => 'docs/plugin-reference/a-refrence-for-thunderphp-plugin-developers/roles-permissions-and-access-checks',
            'path' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/014-roles-permissions-and-access-checks.md',
            'headings' => [
            ],
            'keywords' => [
                'roles',
                'permissions',
                'access',
                'checks',
                'plugins',
                'define',
                'role-aware',
                'behavior',
                'plugin',
                'reference',
                'refrence',
                'thunderphp',
                'developers',
                'practical',
                'advice',
            ],
            'search_text' => 'roles, permissions, and access checks how plugins define permissions and role-aware behavior. plugin reference a refrence for thunderphp plugin developers  thunderphp expects plugins to register possible roles and permissions through filters. example permissions filter: add filter(\'permissions\', function($permissions){ $permissions[] = \'view posts\'; $permissions[] = \'add post\'; $permissions[] = \'edit post\'; $permissions[] = \'delete post\'; return $permissions; }); then in views or controllers: if(user can(\'add post\')) { // allow action } user can() caches permission loading per page load and supports an all permission for universal access. role helpers such as user roles() and contains role() provide similar convenience for role based systems. practical advice use roles for broad identity grouping use permissions for capability checks prefer permission checks in views and controllers instead of hardcoding role names everywhere',
            'plain_text' => 'ThunderPHP expects plugins to register possible roles and permissions through filters. Example permissions filter: add filter(\'permissions\', function($permissions){ $permissions[] = \'view posts\'; $permissions[] = \'add post\'; $permissions[] = \'edit post\'; $permissions[] = \'delete post\'; return $permissions; }); Then in views or controllers: if(user can(\'add post\')) { // allow action } user can() caches permission loading per page load and supports an all permission for universal access. Role helpers such as user roles() and contains role() provide similar convenience for role based systems. Practical Advice use roles for broad identity grouping use permissions for capability checks prefer permission checks in views and controllers instead of hardcoding role names everywhere',
            'order' => 14,
        ],
        [
            'id' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/admin-conventions-and-cross-plugin-hooks',
            'title' => 'Admin Conventions and Cross-Plugin Hooks',
            'description' => 'How admin content and sidebar links are typically injected.',
            'topic' => 'Plugin Reference',
            'topic_slug' => 'plugin-reference',
            'subtopic' => 'A refrence for ThunderPHP plugin developers',
            'subtopic_slug' => 'a-refrence-for-thunderphp-plugin-developers',
            'section_slug' => 'admin-conventions-and-cross-plugin-hooks',
            'url' => 'docs/plugin-reference/a-refrence-for-thunderphp-plugin-developers/admin-conventions-and-cross-plugin-hooks',
            'path' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/015-admin-conventions-and-cross-plugin-hooks.md',
            'headings' => [
            ],
            'keywords' => [
                'admin',
                'conventions',
                'cross-plugin',
                'hooks',
                'content',
                'sidebar',
                'links',
                'typically',
                'injected',
                'plugin',
                'reference',
                'refrence',
                'thunderphp',
                'developers',
            ],
            'search_text' => 'admin conventions and cross-plugin hooks how admin content and sidebar links are typically injected. plugin reference a refrence for thunderphp plugin developers  unless a project defines otherwise, admin pages are assumed to live under page() === \'admin\'. in many thunderphp setups, the expected admin content hook is: admin main content and the typical sidebar link injection filter is: admin before links example: add filter(\'admin before links\', function($links){ $vars = get value(); $obj = (object)[]; $obj title = \'user access\'; $obj link = root . \'/\'.$vars[\'admin route\'].\'/\'.$vars[\'plugin route\']; $obj icon = \'fa solid fa file lines\'; $obj parent = 0; $links[] = $obj; return $links; }); this pattern is useful because admin systems are themselves be plugins, and feature plugins can integrate into them through standard hook contracts instead of hard coupling.',
            'plain_text' => 'Unless a project defines otherwise, admin pages are assumed to live under page() === \'admin\'. In many ThunderPHP setups, the expected admin content hook is: admin main content And the typical sidebar link injection filter is: admin before links Example: add filter(\'admin before links\', function($links){ $vars = get value(); $obj = (object)[]; $obj title = \'User Access\'; $obj link = ROOT . \'/\'.$vars[\'admin route\'].\'/\'.$vars[\'plugin route\']; $obj icon = \'fa solid fa file lines\'; $obj parent = 0; $links[] = $obj; return $links; }); This pattern is useful because admin systems are themselves be plugins, and feature plugins can integrate into them through standard hook contracts instead of hard coupling.',
            'order' => 15,
        ],
        [
            'id' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/plugin-recipes-and-common-pitfalls',
            'title' => 'Plugin Recipes and Common Pitfalls',
            'description' => 'Practical patterns and the mistakes plugin authors should avoid.',
            'topic' => 'Plugin Reference',
            'topic_slug' => 'plugin-reference',
            'subtopic' => 'A refrence for ThunderPHP plugin developers',
            'subtopic_slug' => 'a-refrence-for-thunderphp-plugin-developers',
            'section_slug' => 'plugin-recipes-and-common-pitfalls',
            'url' => 'docs/plugin-reference/a-refrence-for-thunderphp-plugin-developers/plugin-recipes-and-common-pitfalls',
            'path' => 'plugin-reference/a-refrence-for-thunderphp-plugin-developers/016-plugin-recipes-and-common-pitfalls.md',
            'headings' => [
            ],
            'keywords' => [
