                'small',
                'redirect',
                'after',
                'validation',
                'errors',
                'must',
                'read',
                'immediately',
            ],
            'search_text' => 'plugin recipes and common pitfalls practical patterns and the mistakes plugin authors should avoid. plugin reference a refrence for thunderphp plugin developers  recipe: keep plugin.php small put route setup and hook registration in plugin.php, but include files for large controller logic. add action(\'controller\', function($data){ include plugin path(\'controllers/frontend/posts.php\'); }, 10, \'post.view\'); recipe: do not redirect after validation if errors must be read immediately since set value() is request scoped and does not persist across redirects, validation errors intended for the same page should usually be handled without redirecting. recipe: prefer named routes use routes.routes when possible. it scales better and makes route scoped hooks cleaner. pitfall: accidental 404 if you are building an api like route and do not render a view, end the request after output, or the framework may continue into the 404 safeguard. pitfall: outdated class assumptions older docs may understate what the newer request, image, pager, validate, and querybuilder layers can do. base new plugin docs on the current class references instead of old summaries.',
            'plain_text' => 'Recipe: Keep plugin.php Small Put route setup and hook registration in plugin.php, but include files for large controller logic. add action(\'controller\', function($data){ include plugin path(\'controllers/frontend/posts.php\'); }, 10, \'post.view\'); Recipe: Do Not Redirect After Validation If Errors Must Be Read Immediately Since set value() is request scoped and does not persist across redirects, validation errors intended for the same page should usually be handled without redirecting. Recipe: Prefer Named Routes Use routes.routes when possible. It scales better and makes route scoped hooks cleaner. Pitfall: Accidental 404 If you are building an API like route and do not render a view, end the request after output, or the framework may continue into the 404 safeguard. Pitfall: Outdated Class Assumptions Older docs may understate what the newer Request, Image, Pager, Validate, and QueryBuilder layers can do. Base new plugin docs on the current class references instead of old summaries.',
            'order' => 16,
        ],
