            'search_text' => 'introduction learn what the query builder is and why it is useful. query builder query builder beginner guide  the query builder in thunderphp allows you to interact with your database using simple, readable php code instead of writing raw sql. instead of writing: select from users where status = \'active\' you write: $usermodel where(\'status\', \'active\') get(); it is safer, easier to read, and helps prevent sql injection automatically.',
            'plain_text' => 'The Query Builder in ThunderPHP allows you to interact with your database using simple, readable PHP code instead of writing raw SQL. Instead of writing: SELECT FROM users WHERE status = \'active\' You write: $userModel where(\'status\', \'active\') get(); It is safer, easier to read, and helps prevent SQL injection automatically.',
            'order' => 1,
        ],
