            'search_text' => 'step 2: getting data (select) fetch all rows, specific columns, or a single record. query builder query builder beginner guide  use get() when you want multiple rows and first() when you only need one row. get all rows: $users = $usermodel get(); foreach ($users as $user) { echo $user name; } get specific columns: $users = $usermodel select(\'id\', \'name\') get(); get one row: $user = $usermodel where(\'id\', 1) first(); echo $user name;',
            'plain_text' => 'Use get() when you want multiple rows and first() when you only need one row. Get all rows: $users = $userModel get(); foreach ($users as $user) { echo $user name; } Get specific columns: $users = $userModel select(\'id\', \'name\') get(); Get one row: $user = $userModel where(\'id\', 1) first(); echo $user name;',
