            'search_text' => 'step 13: reusing queries reuse a base query with cloning to avoid repetition. query builder query builder beginner guide  a useful pattern is to build a base query once and then clone it for different variations. $base = $usermodel where(\'status\', \'active\'); $admins = (clone $base) where(\'role\', \'admin\') get(); $users = (clone $base) where(\'role\', \'user\') get();',
            'plain_text' => 'A useful pattern is to build a base query once and then clone it for different variations. $base = $userModel where(\'status\', \'active\'); $admins = (clone $base) where(\'role\', \'admin\') get(); $users = (clone $base) where(\'role\', \'user\') get();',
            'order' => 14,
