        [
            'id' => 'query-builder/query-builder-beginner-guide/common-mistakes',
            'title' => 'Common Mistakes',
            'description' => 'Avoid a few common beginner mistakes when using the builder.',
            'topic' => 'Query Builder',
            'topic_slug' => 'query-builder',
            'subtopic' => 'Query Builder Beginner Guide',
            'subtopic_slug' => 'query-builder-beginner-guide',
