                'beginner',
                'builder',
                'query',
                'guide',
            ],
            'search_text' => 'common mistakes avoid a few common beginner mistakes when using the builder. query builder query builder beginner guide  forgetting get(): $usermodel where(\'status\', \'active\'); the query above only builds the query. it does not execute it. correct version: $usermodel where(\'status\', \'active\') get(); mixing array and object access: echo $user[\'name\']; correct version: echo $user name; updating without a where() clause: $usermodel update([\'status\' = \'inactive\']); that updates every row in the table, so be careful.',
            'plain_text' => 'Forgetting get(): $userModel where(\'status\', \'active\'); The query above only builds the query. It does not execute it. Correct version: $userModel where(\'status\', \'active\') get(); Mixing array and object access: echo $user[\'name\']; Correct version: echo $user name; Updating without a where() clause: $userModel update([\'status\' = \'inactive\']); That updates every row in the table, so be careful.',
            'order' => 16,
        ],
        [
