        [
            'id' => 'query-builder/query-builder-initialisation-and-usage/initialization',
            'title' => 'Initialization',
            'description' => 'The query builder can be initialized in two ways.',
            'topic' => 'Query Builder',
            'topic_slug' => 'query-builder',
            'subtopic' => 'Query Builder Initialisation and Usage',
            'subtopic_slug' => 'query-builder-initialisation-and-usage',
            'section_slug' => 'initialization',
            'url' => 'docs/query-builder/query-builder-initialisation-and-usage/initialization',
            'path' => 'query-builder/query-builder-initialisation-and-usage/001-initialization.md',
            'headings' => [
            ],
            'keywords' => [
                'initialization',
                'query',
                'builder',
                'initialized',
                'two',
                'ways',
                'initialisation',
                'usage',
                'direct',
                'model',
                'recommended',
            ],
            'search_text' => 'initialization the query builder can be initialized in two ways. query builder query builder initialisation and usage  1. direct usage through the \\\\core\\database class. using this method means you always have to define the database table you\'re targeting. $qb = new \\\\core\\database; $users = $qb table(\'users\') get(); 2. using a model (recommended) this method is better because you skip the table selection and also keep the ability to add your own methods to the model. create a model models must always live in the models folder of your plugin i.e plugin folder/models/. use \\model\\model; class user extends model { protected string $table = \'users\'; } usage $usermodel = new user; $users = $usermodel where(\'active\', 1) get(); the above code will query all active users in the users table. the table name is already defined in the class and so theres no need to specify it in the query building process.',
            'plain_text' => '1. Direct Usage Through the \\\\Core\\Database class. Using this method means you always have to define the database table you\'re targeting. $qb = new \\\\Core\\Database; $users = $qb table(\'users\') get(); 2. Using a Model (Recommended) This method is better because you skip the table selection and also keep the ability to add your own methods to the Model. Create a Model Models must always live in the models folder of your plugin i.e plugin folder/models/. use \\Model\\Model; class User extends Model { protected string $table = \'users\'; } Usage $userModel = new User; $users = $userModel where(\'active\', 1) get(); The above code will query all active users in the users table. The table name is already defined in the class and so theres no need to specify it in the query building process.',
            'order' => 1,
        ],
        [
