            'search_text' => 'where clauses how to filter query results with the `where` clause. provided below are some examples: query builder query builder initialisation and usage  basic $usermodel where(\'status\', \'active\'); with operator $usermodel where(\'age\', \' \', 18); or condition $usermodel where(\'role\', \'admin\') orwhere(\'role\', \'moderator\'); where in $usermodel wherein(\'id\', [1,2,3]); where null $usermodel wherenull(\'deleted at\'); between $usermodel wherebetween(\'age\', [18, 30]); nested conditions $usermodel wherenested(function($q) { $q where(\'role\', \'admin\') orwhere(\'role\', \'superuser\'); }); raw where $usermodel whereraw(\'age ?\', [18]);',
            'plain_text' => 'Basic $userModel where(\'status\', \'active\'); With operator $userModel where(\'age\', \' \', 18); OR condition $userModel where(\'role\', \'admin\') orWhere(\'role\', \'moderator\'); WHERE IN $userModel whereIn(\'id\', [1,2,3]); WHERE NULL $userModel whereNull(\'deleted at\'); BETWEEN $userModel whereBetween(\'age\', [18, 30]); Nested Conditions $userModel whereNested(function($q) { $q where(\'role\', \'admin\') orWhere(\'role\', \'superuser\'); }); Raw WHERE $userModel whereRaw(\'age ?\', [18]);',
            'order' => 4,
        ],
