                'form',
                'validate',
                'user',
                'input',
            ],
            'search_text' => 'basic usage create a validator instance, define rules, run validation, and retrieve errors. form validation how to validate form or user input  at the top of your page. use \\\\core\\validate; use \\\\core\\request; $req = new request; $req post() is the same as $ post. create a new validator using your incoming data, then define rules with setrules(). $validate = new validate($req post()); $validate setrules([ \'username\' = [ \'name\' = \'username\', \'rules\' = [\'required\', \'alpha numeric\', \'min:3\', \'max:20\'] ], \'email\' = [ \'name\' = \'email address\', \'rules\' = [\'required\', \'email\'] ], ]); if($validate validate()) { // valid } else { $errors = $validate geterrors(); } this is the standard validation flow collect request data create validator define rules run validation handle errors if validation fails',
            'plain_text' => 'At the top of your page. use \\\\Core\\Validate; use \\\\Core\\Request; $req = new Request; $req post() is the same as $ POST. Create a new validator using your incoming data, then define rules with setRules(). $validate = new Validate($req post()); $validate setRules([ \'username\' = [ \'name\' = \'Username\', \'rules\' = [\'required\', \'alpha numeric\', \'min:3\', \'max:20\'] ], \'email\' = [ \'name\' = \'Email address\', \'rules\' = [\'required\', \'email\'] ], ]); if($validate validate()) { // valid } else { $errors = $validate getErrors(); } This is the standard validation flow collect request data create validator define rules run validation handle errors if validation fails',
            'order' => 0,
        ],
        [
