            'search_text' => 'rule definition styles rules for how to validate user input can be written in a short form or a named form with user-friendly labels. form validation how to validate form or user input  you can define rules in more than one style. simple style $validate setrules([ \'email\' = [\'required\', \'email\'] ]); named style $validate setrules([ \'email\' = [ \'name\' = \'email address\', \'rules\' = [\'required\', \'email\'] ] ]); the named style is better for user facing forms because error messages can use a readable input name instead of the raw field key.',
            'plain_text' => 'You can define rules in more than one style. Simple style $validate setRules([ \'email\' = [\'required\', \'email\'] ]); Named style $validate setRules([ \'email\' = [ \'name\' = \'Email address\', \'rules\' = [\'required\', \'email\'] ] ]); The named style is better for user facing forms because error messages can use a readable input name instead of the raw field key.',
