            ],
            'search_text' => 'built-in rules thunderphp includes common validation rules for strings, numbers, choices, comparisons, files, and uploads.

below are the built-in rules supported by the validator. form validation how to validate form or user input  1. required the field must not be empty. \'required\' 2. nullable marker rule for optional fields. it does not raise errors by itself. \'nullable\' 3. email the field must contain a valid email address. \'email\' 4. url the field must contain a valid url. \'url\' 5. numeric the field must be numeric. \'numeric\' 6. integer the field must be a whole number. \'integer\' 7. min the field must have at least the given character length. \'min:3\' 8. max the field must not exceed the given character length. \'max:100\' 9. min value the numeric value must be at least the given amount. \'min value:10\' 10. max value the numeric value must not exceed the given amount. \'max value:100\' 11. date the field must be a valid date string. \'date\' 12. match the field must match another field. \'match:password\' 13. alpha the field may contain letters and spaces only. \'alpha\' 14. alpha numeric the field may contain letters, numbers, and spaces only. \'alpha\' 15. no space the field must not contain spaces. \'no space\' 16. in the value must be one of the allowed values. \'in:admin,user,editor\' array form: [ \'rule\' = \'in\', \'param\' = [\'admin\', \'user\', \'editor\'] ] 17. not in the value must not be one of the blocked values. \'not in:banned,deleted\' 18. regex the value must match a full regex pattern. \'regex:/^[a z0 9]+$/\' 19. required if the field becomes required when another field has a given value. \'required if:account type,business\' 20. file validates that an uploaded file exists and was uploaded without errors. \'file\' 21. image validates that an uploaded file is an image. \'image\' 22. boolean the value must be a recognized boolean like value. \'boolean\' 23. unique checks uniqueness in the database. \'unique:users\' advanced form: [ \'rule\' = \'unique\', \'param\' = [ \'table\' = \'users\', \'column\' = \'email\', \'where\' = [ \'deleted\' = 0 ] ] ]',
            'plain_text' => '1. required The field must not be empty. \'required\' 2. nullable Marker rule for optional fields. It does not raise errors by itself. \'nullable\' 3. email The field must contain a valid email address. \'email\' 4. url The field must contain a valid URL. \'url\' 5. numeric The field must be numeric. \'numeric\' 6. integer The field must be a whole number. \'integer\' 7. min The field must have at least the given character length. \'min:3\' 8. max The field must not exceed the given character length. \'max:100\' 9. min value The numeric value must be at least the given amount. \'min value:10\' 10. max value The numeric value must not exceed the given amount. \'max value:100\' 11. date The field must be a valid date string. \'date\' 12. match The field must match another field. \'match:password\' 13. alpha The field may contain letters and spaces only. \'alpha\' 14. alpha numeric The field may contain letters, numbers, and spaces only. \'alpha\' 15. no space The field must not contain spaces. \'no space\' 16. in The value must be one of the allowed values. \'in:admin,user,editor\' Array form: [ \'rule\' = \'in\', \'param\' = [\'admin\', \'user\', \'editor\'] ] 17. not in The value must not be one of the blocked values. \'not in:banned,deleted\' 18. regex The value must match a full regex pattern. \'regex:/^[A Z0 9]+$/\' 19. required if The field becomes required when another field has a given value. \'required if:account type,business\' 20. file Validates that an uploaded file exists and was uploaded without errors. \'file\' 21. image Validates that an uploaded file is an image. \'image\' 22. boolean The value must be a recognized boolean like value. \'boolean\' 23. unique Checks uniqueness in the database. \'unique:users\' Advanced Form: [ \'rule\' = \'unique\', \'param\' = [ \'table\' = \'users\', \'column\' = \'email\', \'where\' = [ \'deleted\' = 0 ] ] ]',
            'order' => 2,
