            ],
            'search_text' => 'unique rule options the advanced unique rule supports table targeting, ignored records, and scoped conditions. form validation how to validate form or user input  the advanced unique rule supports the following keys: table column primary key ignore value ignore from data where wherenot explanation of each parameter: table database table name in which to search for the unique value. \'table\' = \'users\' column database column name. if omitted, the current field name is used e.g name of your form input. \'column\' = \'email\' primary key the primary key column used when ignoring the current record during updates. e.g if updating a user record from a form and email is used as unique identifier, the validator will ignore the current user\'s record when checking for duplicates \'primary key\' = \'user id\' ignore value explicitly sets the record id to ignore. \'ignore value\' = \'12\' ignore from data loads the ignore value from the validation data. \'ignore from data\' = \'user id\' where adds equality conditions. i.e a where clause in the query when searching for duplicates in the table \'where\' = [ \'deleted\' = 0, \'school id\' = $school id ] wherenot adds inequality conditions. \'wherenot\' = [ \'active\' = 0, \'status\' = \'archived\' ]',
            'plain_text' => 'The advanced unique rule supports the following keys: table column primary key ignore value ignore from data where whereNot Explanation of each parameter: table Database table name in which to search for the unique value. \'table\' = \'users\' column Database column name. If omitted, the current field name is used e.g name of your form input. \'column\' = \'email\' primary key The primary key column used when ignoring the current record during updates. e.g if updating a user record from a form and email is used as unique identifier, the validator will ignore the current user\'s record when checking for duplicates \'primary key\' = \'user id\' ignore value Explicitly sets the record ID to ignore. \'ignore value\' = \'12\' ignore from data Loads the ignore value from the validation data. \'ignore from data\' = \'user id\' where Adds equality conditions. i.e a where clause in the query when searching for duplicates in the table \'where\' = [ \'deleted\' = 0, \'school id\' = $school id ] whereNot Adds inequality conditions. \'whereNot\' = [ \'active\' = 0, \'status\' = \'archived\' ]',
            'order' => 3,
        ],
        [
            'id' => 'validation/validate-form-input/soft-delete-and-scoped-uniqueness',
            'title' => 'Soft Delete and Scoped Uniqueness',
            'description' => 'Use where and whereNot to make uniqueness checks respect soft deletes, school scopes, or custom filtering.',
            'topic' => 'Form Validation',
            'topic_slug' => 'validation',
            'subtopic' => 'How to validate form or user input',
            'subtopic_slug' => 'validate-form-input',
            'section_slug' => 'soft-delete-and-scoped-uniqueness',
            'url' => 'docs/validation/validate-form-input/soft-delete-and-scoped-uniqueness',
            'path' => 'validation/validate-form-input/004-soft-delete-and-scoped-uniqueness.md',
            'headings' => [
