                'input',
                'example',
            ],
            'search_text' => 'soft delete and scoped uniqueness use where and wherenot to make uniqueness checks respect soft deletes, school scopes, or custom filtering. form validation how to validate form or user input  soft delete example \'email\' = [ \'name\' = \'email address\', \'rules\' = [ \'required\', \'email\', [ \'rule\' = \'unique\', \'param\' = [ \'table\' = \'users\', \'column\' = \'email\', \'where\' = [ \'deleted\' = 0 ] ] ] ] ] since soft deleted records still exist in the table, this checks uniqueness only among non deleted rows. wherenot example \'email\' = [ \'name\' = \'email address\', \'rules\' = [ [ \'rule\' = \'unique\', \'param\' = [ \'table\' = \'users\', \'column\' = \'email\', \'wherenot\' = [ \'active\' = 0 ] ] ] ] ] this checks uniqueness only among rows where active != 0. scoped uniqueness example \'email\' = [ \'name\' = \'email address\', \'rules\' = [ [ \'rule\' = \'unique\', \'param\' = [ \'table\' = \'users\', \'column\' = \'email\', \'where\' = [ \'school id\' = $school id, \'deleted\' = 0 ], \'wherenot\' = [ \'status\' = \'archived\' ] ] ] ] ] this is useful when uniqueness should only apply inside a specific scope such as a school(multi school website), tenant, company, or active record set.',
            'plain_text' => 'Soft Delete Example \'email\' = [ \'name\' = \'Email address\', \'rules\' = [ \'required\', \'email\', [ \'rule\' = \'unique\', \'param\' = [ \'table\' = \'users\', \'column\' = \'email\', \'where\' = [ \'deleted\' = 0 ] ] ] ] ] Since soft deleted records still exist in the table, this checks uniqueness only among non deleted rows. whereNot Example \'email\' = [ \'name\' = \'Email address\', \'rules\' = [ [ \'rule\' = \'unique\', \'param\' = [ \'table\' = \'users\', \'column\' = \'email\', \'whereNot\' = [ \'active\' = 0 ] ] ] ] ] This checks uniqueness only among rows where active != 0. Scoped Uniqueness Example \'email\' = [ \'name\' = \'Email address\', \'rules\' = [ [ \'rule\' = \'unique\', \'param\' = [ \'table\' = \'users\', \'column\' = \'email\', \'where\' = [ \'school id\' = $school id, \'deleted\' = 0 ], \'whereNot\' = [ \'status\' = \'archived\' ] ] ] ] ] This is useful when uniqueness should only apply inside a specific scope such as a school(multi school website), tenant, company, or active record set.',
            'order' => 4,
        ],
