            'search_text' => 'updating existing records ignore the current record during unique checks when editing rows. form validation how to validate form or user input  when editing a record, the validator can ignore the current row so the existing value does not fail the uniqueness check. example data $data = [ \'id\' = 10, \'email\' = \'admin@example.com\' ]; if your table uses another primary key: $validate primarykey = \'user id\'; or set it directly in the rule: [ \'rule\' = \'unique\', \'param\' = [ \'table\' = \'users\', \'primary key\' = \'user id\', \'ignore from data\' = \'user id\' ] ] this is especially important for update forms where the record already owns the current value.',
            'plain_text' => 'When editing a record, the validator can ignore the current row so the existing value does not fail the uniqueness check. Example data $data = [ \'id\' = 10, \'email\' = \'admin@example.com\' ]; If your table uses another primary key: $validate primaryKey = \'user id\'; Or set it directly in the rule: [ \'rule\' = \'unique\', \'param\' = [ \'table\' = \'users\', \'primary key\' = \'user id\', \'ignore from data\' = \'user id\' ] ] This is especially important for update forms where the record already owns the current value.',
