            'search_text' => 'custom error messages and reading errors override specific messages and retrieve validation failures in different ways. form validation how to validate form or user input  custom error messages you can override error messages for individual rules. \'email\' = [ \'name\' = \'email address\', \'rules\' = [ \'required\', [ \'rule\' = \'email\', \'error message\' = \'please enter a valid email address\' ] ] ] get all errors $errors = $validate geterrors(); get first error for one field $error = $validate firsterror(\'email\'); check failure if($validate fails()) { // handle errors }',
            'plain_text' => 'Custom Error Messages You can override error messages for individual rules. \'email\' = [ \'name\' = \'Email address\', \'rules\' = [ \'required\', [ \'rule\' = \'email\', \'error message\' = \'Please enter a valid email address\' ] ] ] Get all errors $errors = $validate getErrors(); Get first error for one field $error = $validate firstError(\'email\'); Check failure if($validate fails()) { // handle errors }',
