            ],
            'search_text' => 'custom rules and static registration extend validation through hooks or static rule registration without editing the validator core. form validation how to validate form or user input  custom rules through hooks plugins can register custom validation rules using the validation rules filter. this is an example of adding a custom phone number validation. in this case a zambian phone number. add filter(\'validation rules\', function($rules){ $rules[\'phone zm\'] = function($field, $value, $param, $meta, $validator){ if($validator isempty($value)) return; if(!preg match(\'/^(?:\\+260 0)(95 96 97)\\d{7}$/\', (string)$value)) { $validator adderror( $field, !empty($meta[\'error message\']) ? $meta[\'error message\'] : $meta[\'input name\']." is not a valid zambian mobile number" ); } }; return $rules; }); use the rule like this: $validate setrules([ \'phone\' = [ \'name\' = \'phone number\', \'rules\' = [\'required\', \'phone zm\'] ] ]); static rule registration \\\\core\\validate::extend(\'slug\', function($field, $value, $param, $meta, $validator){ if($validator isempty($value)) return; if(!preg match(\'/^[a z0 9\\ ]+$/\', (string)$value)) { $validator adderror( $field, !empty($meta[\'error message\']) ? $meta[\'error message\'] : $meta[\'input name\']." is not a valid slug" ); } }); both approaches let you extend validation cleanly without changing the core validator file.',
            'plain_text' => 'Custom rules through hooks Plugins can register custom validation rules using the validation rules filter. This is an example of adding a custom phone number validation. In this case a Zambian phone number. add filter(\'validation rules\', function($rules){ $rules[\'phone zm\'] = function($field, $value, $param, $meta, $validator){ if($validator isEmpty($value)) return; if(!preg match(\'/^(?:\\+260 0)(95 96 97)\\d{7}$/\', (string)$value)) { $validator addError( $field, !empty($meta[\'error message\']) ? $meta[\'error message\'] : $meta[\'input name\']." is not a valid Zambian mobile number" ); } }; return $rules; }); Use the rule like this: $validate setRules([ \'phone\' = [ \'name\' = \'Phone number\', \'rules\' = [\'required\', \'phone zm\'] ] ]); Static rule registration \\\\Core\\Validate::extend(\'slug\', function($field, $value, $param, $meta, $validator){ if($validator isEmpty($value)) return; if(!preg match(\'/^[a z0 9\\ ]+$/\', (string)$value)) { $validator addError( $field, !empty($meta[\'error message\']) ? $meta[\'error message\'] : $meta[\'input name\']." is not a valid slug" ); } }); Both approaches let you extend validation cleanly without changing the core validator file.',
            'order' => 7,
        ],
