            'search_text' => 'recommendations best practices for writing validation rules that stay readable, reusable, and easy to maintain. form validation how to validate form or user input  recommended practices when using the validator: use name for user facing forms use where for soft delete aware uniqueness use wherenot for inequality based uniqueness filters use custom rules for domain specific validation prefer hook based extension over editing the validator keep custom rule names short and descriptive a good rule set should be easy to read, easy to extend, and easy to reuse across forms.',
            'plain_text' => 'Recommended practices when using the validator: use name for user facing forms use where for soft delete aware uniqueness use whereNot for inequality based uniqueness filters use custom rules for domain specific validation prefer hook based extension over editing the validator keep custom rule names short and descriptive A good rule set should be easy to read, easy to extend, and easy to reuse across forms.',
